// Helpers extracted from content-repository-factory to keep that file
// under the 400-line arch-lint warning.

import type { AstropressContentRepositoryInput } from "./content-repository-factory";
import type { Actor, ContentRecord, ContentRepository } from "./persistence-types";

type CreateInput = Parameters<ContentRepository["createContentRecord"]>[0];
type RestoreResult = ReturnType<ContentRepository["restoreRevision"]>;
type CreateResult = ReturnType<ContentRepository["createContentRecord"]>;

export function restoreRevisionImpl(
	input: AstropressContentRepositoryInput,
	slug: string,
	revisionId: string,
	actor: Actor,
): RestoreResult {
	const record = input.findContentRecord(slug);
	if (!record) {
		return {
			ok: false as const,
			error: "The selected content record could not be found.",
		};
	}

	input.ensureBaselineRevision(record);
	const revision = input.getPersistedRevision(record.slug, revisionId);
	if (!revision) {
		return { ok: false as const, error: "Revision not found." };
	}

	input.upsertContentOverride(
		record.slug,
		{
			title: revision.title,
			status: revision.status,
			scheduledAt: revision.scheduledAt,
			body: revision.body,
			seoTitle: revision.seoTitle,
			metaDescription: revision.metaDescription,
			excerpt: revision.excerpt,
			ogTitle: revision.ogTitle,
			ogDescription: revision.ogDescription,
			ogImage: revision.ogImage,
			canonicalUrlOverride: revision.canonicalUrlOverride,
			robotsDirective: revision.robotsDirective,
		},
		actor,
	);

	input.replaceContentAssignments(record.slug, {
		authorIds: revision.authorIds ?? [],
		categoryIds: revision.categoryIds ?? [],
		tagIds: revision.tagIds ?? [],
	});

	input.insertReviewedRevision(
		record.slug,
		{
			title: revision.title,
			status: revision.status,
			scheduledAt: revision.scheduledAt,
			body: revision.body,
			seoTitle: revision.seoTitle,
			metaDescription: revision.metaDescription,
			excerpt: revision.excerpt,
			ogTitle: revision.ogTitle,
			ogDescription: revision.ogDescription,
			ogImage: revision.ogImage,
			authorIds: revision.authorIds,
			categoryIds: revision.categoryIds,
			tagIds: revision.tagIds,
			canonicalUrlOverride: revision.canonicalUrlOverride,
			robotsDirective: revision.robotsDirective,
			revisionNote: revision.revisionNote,
		},
		actor,
	);

	input.recordContentAudit({
		actor,
		action: "content.restore",
		summary: `Restored revision ${revisionId} for ${slug}.`,
		targetId: record.slug,
	});

	return { ok: true as const };
}

export function createContentRecordImpl(
	input: AstropressContentRepositoryInput,
	getContentState: (slug: string) => ContentRecord | null,
	rawInput: CreateInput,
	actor: Actor,
): CreateResult {
	const title = rawInput.title.trim();
	const slug = input.slugifyTerm(rawInput.slug);
	const legacyUrl = input.normalizePath(rawInput.legacyUrl?.trim() || `/${slug}`);
	const seoTitle = rawInput.seoTitle.trim() || title;
	const metaDescription = rawInput.metaDescription.trim();
	const status = input.normalizeContentStatus(rawInput.status);
	const body = rawInput.body?.trim() || "";
	const summary = rawInput.summary?.trim() || "";

	if (!title || !slug || !metaDescription) {
		return {
			ok: false as const,
			error: "Title, slug, and meta description are required.",
		};
	}

	if (input.findContentRecord(slug) || input.findContentRecord(legacyUrl.replace(/^\//, ""))) {
		return { ok: false as const, error: "That slug is already in use." };
	}

	const inserted = input.insertContentEntry({
		slug,
		legacyUrl,
		title,
		body,
		summary,
		seoTitle,
		metaDescription,
		ogTitle: rawInput.ogTitle?.trim() || undefined,
		ogDescription: rawInput.ogDescription?.trim() || undefined,
		ogImage: rawInput.ogImage?.trim() || undefined,
	});
	if (!inserted) {
		return {
			ok: false as const,
			error: "That slug or route is already in use.",
		};
	}

	input.upsertContentOverride(
		slug,
		{
			title,
			status,
			body,
			seoTitle,
			metaDescription,
			excerpt: rawInput.excerpt?.trim() || summary || undefined,
			ogTitle: rawInput.ogTitle?.trim() || undefined,
			ogDescription: rawInput.ogDescription?.trim() || undefined,
			ogImage: rawInput.ogImage?.trim() || undefined,
			canonicalUrlOverride: rawInput.canonicalUrlOverride?.trim() || undefined,
			robotsDirective: rawInput.robotsDirective?.trim() || undefined,
		},
		actor,
	);

	input.insertReviewedRevision(
		slug,
		{
			title,
			status,
			body,
			seoTitle,
			metaDescription,
			excerpt: rawInput.excerpt?.trim() || summary || undefined,
			ogTitle: rawInput.ogTitle?.trim() || undefined,
			ogDescription: rawInput.ogDescription?.trim() || undefined,
			ogImage: rawInput.ogImage?.trim() || undefined,
			canonicalUrlOverride: rawInput.canonicalUrlOverride?.trim() || undefined,
			robotsDirective: rawInput.robotsDirective?.trim() || undefined,
			revisionNote: "Created new post.",
		},
		actor,
	);

	input.recordContentAudit({
		actor,
		action: "content.create",
		summary: `Created post ${legacyUrl}.`,
		targetId: slug,
	});

	return { ok: true as const, state: getContentState(slug) };
}

src/import/fetch-wix.ts.source:
import { mkdir } from "node:fs/promises";
import path from "node:path";

// ---------------------------------------------------------------------------
// Typed error classes
// ---------------------------------------------------------------------------

export class WixInvalidCredentialsError extends Error {
	override name = "WixInvalidCredentialsError";
	constructor() {
		super("Login failed: incorrect email or password");
	}
}

export class WixTwoFactorRequiredError extends Error {
	override name = "WixTwoFactorRequiredError";
	constructor() {
		super("Two-factor authentication is required — export the file manually and use --source");
	}
}

export class WixCaptchaDetectedError extends Error {
	override name = "WixCaptchaDetectedError";
	constructor() {
		super(
			"CAPTCHA detected — the site requires human verification.\n" +
				"Export the blog CSV manually via your Wix Dashboard → Blog → Posts → Export and use --source.",
		);
	}
}

export class WixBotDetectionError extends Error {
	override name = "WixBotDetectionError";
	constructor() {
		super(
			"Bot detection triggered (Cloudflare or similar security layer).\n" +
				"Export the blog CSV manually via your Wix Dashboard → Blog → Posts → Export and use --source.",
		);
	}
}

export class WixSiteNotFoundError extends Error {
	override name = "WixSiteNotFoundError";
	constructor() {
		super(
			"Blog export is not available for this site — make sure the Wix Blog app is installed.\n" +
				"In your Wix Dashboard go to Blog → Posts and confirm posts are visible.",
		);
	}
}

// ---------------------------------------------------------------------------
// Options / Result
// ---------------------------------------------------------------------------

export type WixFetchOptions = {
	siteUrl: string;
	email: string;
	password: string;
	downloadDir: string;
	headless?: boolean;
	timeoutMs?: number;
};

export type WixFetchResult = {
	exportPath: string;
	warnings: string[];
};

// ---------------------------------------------------------------------------
// Lazy Playwright loader
// ---------------------------------------------------------------------------

async function requirePlaywright() {
	try {
		return await import("playwright");
	} catch {
		throw new Error(
			"Browser automation requires Playwright.\n" +
				"Install it with:  bun add playwright && bunx playwright install chromium\n" +
				"Or export the file manually and use --source.",
		);
	}
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function isBotBlocked(content: string): boolean {
	return (
		content.includes("cf-browser-verification") ||
		content.includes("cf-challenge") ||
		content.includes("cf-spinner") ||
		content.includes("window._cf_chl_opt") ||
		content.includes("__cf_chl_jschl_tk__")
	);
}

// ---------------------------------------------------------------------------
// Single-attempt implementation (internal)
// ---------------------------------------------------------------------------

async function attemptWixExport(
	opts: WixFetchOptions & { headless: boolean },
): Promise<WixFetchResult> {
	const { siteUrl: _siteUrl, email, password, downloadDir, headless, timeoutMs = 30_000 } = opts;

	const pw = await requirePlaywright();
	const browser = await pw.chromium.launch({ headless });
	const warnings: string[] = [];

	try {
		const context = await browser.newContext({ acceptDownloads: true });
		const page = await context.newPage();

		// 1. Navigate to Wix signin
		await page.goto("https://users.wix.com/signin", {
			timeout: timeoutMs,
			waitUntil: "domcontentloaded",
		});

		// 2. Check for bot detection / CAPTCHA before attempting login
		const loginContent = await page.content();
		if (isBotBlocked(loginContent)) {
			throw new WixBotDetectionError();
		}
		if (loginContent.includes("g-recaptcha") || loginContent.includes("h-captcha")) {
			throw new WixCaptchaDetectedError();
		}

		// 3. Fill email and submit first step
		await page.fill('[type="email"], [name="email"], #email', email);
		await page.click('[type="submit"], button[data-testid="submit"]');

		// 4. Fill password and submit second step
		await page.fill('[type="password"], [name="password"], #password', password);
		await page.click('[type="submit"], button[data-testid="submit"]');

		// 5. Check for 2FA / error — only if still on signin domain
		const postLoginUrl = page.url();
		let isOnWixManage = false;
		try {
			const parsed = new URL(postLoginUrl);
			isOnWixManage =
				parsed.hostname === "manage.wix.com" || parsed.hostname.endsWith(".manage.wix.com");
		} catch {
			// malformed URL — treat as not on manage.wix.com
		}
		if (postLoginUrl.includes("signin") || !isOnWixManage) {
			if (postLoginUrl.includes("/signin/verification")) {
				throw new WixTwoFactorRequiredError();
			}
			const has2FA = await page
				.locator('[data-testid*="verification"], [data-testid*="phone"], input[name*="code"]')
				.count();
			if (has2FA > 0) {
				throw new WixTwoFactorRequiredError();
			}
			const hasError = await page
				.locator('[data-testid="error-message"], .error-message, [data-testid*="error"]')
				.count();
			if (hasError > 0) {
				throw new WixInvalidCredentialsError();
			}
		}

		// 6. Find blog export in dashboard
		await mkdir(downloadDir, { recursive: true });

		const hasBlogExport = await page
			.locator('[data-testid*="blog"], a[href*="blog"], button:has-text("Export")')
			.count();
		if (hasBlogExport === 0) {
			throw new WixSiteNotFoundError();
		}

		// 7. Trigger download
		const downloadPromise = page.waitForEvent("download", {
			timeout: timeoutMs,
		});
		await page.locator('button:has-text("Export")').first().click();

		const download = await downloadPromise;
		const filename = download.suggestedFilename();
		const exportPath = path.join(downloadDir, filename);
		await download.saveAs(exportPath);

		return { exportPath, warnings };
	} finally {
		await browser.close();
	}
}

// ---------------------------------------------------------------------------
// Public API — auto-retries with visible browser on bot detection / CAPTCHA
// ---------------------------------------------------------------------------

export async function fetchWixExport(opts: WixFetchOptions): Promise<WixFetchResult> {
	if (opts.headless === false) {
		return attemptWixExport({ ...opts, headless: false });
	}

	try {
		return await attemptWixExport({ ...opts, headless: true });
	} catch (err) {
		if (err instanceof WixCaptchaDetectedError || err instanceof WixBotDetectionError) {
			process.stderr.write(
				"\n[astropress] Bot detection or CAPTCHA triggered in headless mode.\n" +
					"[astropress] Opening a visible browser — please solve any challenge that appears,\n" +
					"[astropress] then the export will continue automatically.\n\n",
			);
			return await attemptWixExport({ ...opts, headless: false });
		}
		throw err;
	}
}

