import type { AstropressSqliteDatabaseLike } from "./utils";

export interface ContentLockResult {
	ok: true;
	lockToken: string;
	expiresAt: string;
}

export interface ContentLockConflict {
	ok: false;
	conflict: true;
	lockedByEmail: string;
	lockedByName: string;
	expiresAt: string;
}

const LOCK_TTL_MINUTES = 5;

function lockExpiresAt(): string {
	const d = new Date();
	d.setMinutes(d.getMinutes() + LOCK_TTL_MINUTES);
	return d.toISOString();
}

export function createSqliteLocksOps(getDb: () => AstropressSqliteDatabaseLike) {
	return {
		acquireLock(
			slug: string,
			email: string,
			name: string,
		): ContentLockResult | ContentLockConflict {
			const db = getDb();
			db.exec("BEGIN IMMEDIATE");
			try {
				db.prepare("DELETE FROM content_locks WHERE expires_at <= ?").run(new Date().toISOString());

				const existing = db
					.prepare(
						"SELECT locked_by_email, locked_by_name, expires_at FROM content_locks WHERE slug = ? LIMIT 1",
					)
					.get(slug) as
					| {
							locked_by_email: string;
							locked_by_name: string;
							expires_at: string;
					  }
					| undefined;

				if (existing && existing.locked_by_email !== email) {
					db.exec("ROLLBACK");
					return {
						ok: false,
						conflict: true,
						lockedByEmail: existing.locked_by_email,
						lockedByName: existing.locked_by_name,
						expiresAt: existing.expires_at,
					};
				}

				const lockToken = crypto.randomUUID();
				const expiresAt = lockExpiresAt();
				db.prepare(
					`INSERT INTO content_locks (slug, locked_by_email, locked_by_name, lock_token, expires_at)
             VALUES (?, ?, ?, ?, ?)
             ON CONFLICT(slug) DO UPDATE SET
               locked_by_email = excluded.locked_by_email,
               locked_by_name = excluded.locked_by_name,
               lock_token = excluded.lock_token,
               expires_at = excluded.expires_at`,
				).run(slug, email, name, lockToken, expiresAt);
				db.exec("COMMIT");
				return { ok: true, lockToken, expiresAt };
			} catch (e) {
				db.exec("ROLLBACK");
				throw e;
			}
		},

		refreshLock(slug: string, lockToken: string): boolean {
			const expiresAt = lockExpiresAt();
			const result = getDb()
				.prepare("UPDATE content_locks SET expires_at = ? WHERE slug = ? AND lock_token = ?")
				.run(expiresAt, slug, lockToken);
			return (result.changes as number) > 0;
		},

		releaseLock(slug: string, lockToken: string): boolean {
			const result = getDb()
				.prepare("DELETE FROM content_locks WHERE slug = ? AND lock_token = ?")
				.run(slug, lockToken);
			return (result.changes as number) > 0;
		},
	};
}

src/access/d1-access-page-store.ts.source:
/**
 * D1 read path for the /ap-admin/access page model. Lives here (filename
 * prefix `d1-`) so the SQL-containment arch rule keeps `.prepare()` confined
 * to the adapter layer.
 */

import type { D1DatabaseLike } from "../d1-database";
import type { RolePolicyRecord, RoleRecord } from "./repository";
import type { Condition, Effect } from "./types";

export interface AccessTabData {
	roles: RoleRecord[];
	userRoleMap: Record<number, string[]>;
	userDirectGrantCounts: Record<number, number>;
	rolePoliciesMap: Record<string, RolePolicyRecord[]>;
	activeAdminCount: number;
}

export async function loadAccessTabDataFromD1(db: D1DatabaseLike): Promise<AccessTabData> {
	const [roleRows, assignmentRows, grantCountRows, rolePolicyRows, adminCountRow] =
		await Promise.all([
			db
				.prepare(
					"SELECT id, name, description, is_system, created_at, updated_at FROM access_roles ORDER BY name",
				)
				.all<{
					id: string;
					name: string;
					description: string;
					is_system: number;
					created_at: string;
					updated_at: string;
				}>(),
			db
				.prepare("SELECT user_id, role_id FROM access_user_roles")
				.all<{ user_id: number; role_id: string }>(),
			db
				.prepare("SELECT user_id, COUNT(*) AS n FROM access_user_policies GROUP BY user_id")
				.all<{ user_id: number; n: number }>(),
			db
				.prepare(
					"SELECT id, role_id, effect, action, condition_json, priority FROM access_role_policies ORDER BY role_id, priority DESC, id",
				)
				.all<{
					id: string;
					role_id: string;
					effect: Effect;
					action: string;
					condition_json: string | null;
					priority: number;
				}>(),
			db
				.prepare("SELECT COUNT(*) AS n FROM admin_users WHERE active = 1 AND is_admin = 1")
				.first<{ n: number }>(),
		]);

	const roles: RoleRecord[] = (roleRows.results ?? []).map((r) => ({
		id: r.id,
		name: r.name,
		description: r.description,
		isSystem: r.is_system === 1,
		createdAt: r.created_at,
		updatedAt: r.updated_at,
	}));

	const userRoleMap: Record<number, string[]> = {};
	for (const row of assignmentRows.results ?? []) {
		const list = userRoleMap[row.user_id] ?? [];
		list.push(row.role_id);
		userRoleMap[row.user_id] = list;
	}

	const userDirectGrantCounts: Record<number, number> = {};
	for (const row of grantCountRows.results ?? []) {
		userDirectGrantCounts[row.user_id] = row.n;
	}

	const rolePoliciesMap: Record<string, RolePolicyRecord[]> = {};
	for (const row of rolePolicyRows.results ?? []) {
		const list = rolePoliciesMap[row.role_id] ?? [];
		let condition: Condition | null = null;
		if (row.condition_json) {
			try {
				condition = JSON.parse(row.condition_json) as Condition;
			} catch {
				condition = null;
			}
		}
		list.push({
			id: row.id,
			roleId: row.role_id,
			effect: row.effect,
			action: row.action,
			condition,
			priority: row.priority,
		});
		rolePoliciesMap[row.role_id] = list;
	}

	return {
		roles,
		userRoleMap,
		userDirectGrantCounts,
		rolePoliciesMap,
		activeAdminCount: adminCountRow?.n ?? 0,
	};
}

src/adapters/cloudflare-auth.ts.source:
import { createSessionTokenDigest, verifyPassword } from "../crypto-utils.js";
import type { D1DatabaseLike } from "../d1-database";
import type { AuthStore, AuthUser } from "../platform-contracts";
import { isProductionRuntime } from "../runtime-env";
import { createLogger } from "../runtime-logger";
import {
	CLOUDFLARE_DEFAULT_SESSION_SECRET,
	CLOUDFLARE_SESSION_LOGGER_CONTEXT,
	CLOUDFLARE_SESSION_TTL_MS,
} from "./cloudflare-auth-data";

export { CLOUDFLARE_SESSION_TTL_MS };

const logger = createLogger(CLOUDFLARE_SESSION_LOGGER_CONTEXT);

export type AstropressCloudflareSeedUser = AuthUser & { password: string };

function getConfiguredSecrets(...values: Array<string | undefined>) {
	const seen = new Set<string>();
	const configured: string[] = [];

	for (const value of values) {
		const trimmed = value?.trim();
		if (!trimmed || seen.has(trimmed)) {
			continue;
		}
		seen.add(trimmed);
		configured.push(trimmed);
	}

	return configured;
}

export function resolveCloudflareSessionSecret(): string {
	const secret =
		// audit-boundary: opaque-passthrough -- dev default; production throws below
		process.env.CLOUDFLARE_SESSION_SECRET ?? CLOUDFLARE_DEFAULT_SESSION_SECRET;
	if (secret === CLOUDFLARE_DEFAULT_SESSION_SECRET) {
		if (isProductionRuntime()) {
			throw new Error(
				"[astropress] CLOUDFLARE_SESSION_SECRET must be set before deployment. " +
					"Use a random string of 32+ characters.",
			);
		}
		logger.warn(
			"CLOUDFLARE_SESSION_SECRET is using the insecure default. " +
				"Set this env var to a long random string before deploying.",
		);
	}
	return secret;
}

export function resolveCloudflareSessionSecretCandidates(): string[] {
	return getConfiguredSecrets(
		resolveCloudflareSessionSecret(),
		process.env.CLOUDFLARE_SESSION_SECRET_PREV,
	);
}

export async function cleanupExpiredCloudflareSessions(db: D1DatabaseLike) {
	await db
		.prepare(
			`
        UPDATE admin_sessions
        SET revoked_at = CURRENT_TIMESTAMP
        WHERE revoked_at IS NULL
          AND last_active_at < datetime('now', '-12 hours')
      `,
		)
		.run();
}

export async function getLiveCloudflareSessionRow(db: D1DatabaseLike, sessionId: string) {
	await cleanupExpiredCloudflareSessions(db);

	const sessionCandidates = [sessionId];
	for (const secret of resolveCloudflareSessionSecretCandidates()) {
		sessionCandidates.push(await createSessionTokenDigest(sessionId, secret));
	}
	let row: {
		id: string;
		last_active_at: string;
		email: string;
		is_admin: number;
	} | null = null;

	for (const candidate of sessionCandidates) {
		row = await db
			.prepare(
				`
          SELECT s.id, s.last_active_at, u.email, u.is_admin
          FROM admin_sessions s
          JOIN admin_users u ON u.id = s.user_id
          WHERE s.id = ?
            AND s.revoked_at IS NULL
            AND u.active = 1
          LIMIT 1
        `,
			)
			.bind(candidate)
			.first<{
				id: string;
				last_active_at: string;
				email: string;
				is_admin: number;
			}>();
		if (row) break;
	}

	if (!row) return null;

	const lastActiveAt = Date.parse(row.last_active_at);
	if (!Number.isFinite(lastActiveAt) || Date.now() - lastActiveAt > CLOUDFLARE_SESSION_TTL_MS) {
		await db
			.prepare(
				"UPDATE admin_sessions SET revoked_at = CURRENT_TIMESTAMP WHERE id = ? AND revoked_at IS NULL",
			)
			.bind(row.id)
			.run();
		return null;
	}

	await db
		.prepare("UPDATE admin_sessions SET last_active_at = CURRENT_TIMESTAMP WHERE id = ?")
		.bind(row.id)
		.run();
	return row;
}

export function createFallbackCloudflareAuthStore(
	seedUsers: AstropressCloudflareSeedUser[],
): AuthStore {
	const users = new Map(seedUsers.map((user) => [user.email.toLowerCase(), user]));
	const sessions = new Map<string, AuthUser>();

	return {
		async signIn(email, password) {
			const user = users.get(email.trim().toLowerCase());
			if (!user || user.password !== password) return null;
			const sessionId = `cloudflare-session:${user.id}`;
			const sessionUser: AuthUser = {
				id: sessionId,
				email: user.email,
				isAdmin: user.isAdmin,
			};
			sessions.set(sessionId, sessionUser);
			return sessionUser;
		},
		async signOut(sessionId) {
			sessions.delete(sessionId);
		},
		async getSession(sessionId) {
			return sessions.get(sessionId) ?? null;
		},
	};
}

export function createDisabledCloudflareAuthStore(): AuthStore {
	return {
		async signIn() {
			return null;
		},
		async signOut() {},
		async getSession() {
			return null;
		},
	};
}

export function createD1CloudflareAuthStore(db: D1DatabaseLike): AuthStore {
	return {
		async signIn(email, password) {
			const row = await db
				.prepare(
					"SELECT id, email, is_admin, password_hash FROM admin_users WHERE email = ? AND active = 1 LIMIT 1",
				)
				.bind(email.trim().toLowerCase())
				.first<{
					id: number;
					email: string;
					is_admin: number;
					password_hash: string;
				}>();

			if (!row || !(await verifyPassword(password, row.password_hash))) return null;

			const sessionId = crypto.randomUUID();
			const storedSessionId = await createSessionTokenDigest(
				sessionId,
				resolveCloudflareSessionSecret(),
			);
			const csrfToken = crypto.randomUUID();

			// Batch cleanup of expired sessions with the new session insert — atomic on D1
			await db.batch([
				db.prepare(
					`UPDATE admin_sessions SET revoked_at = CURRENT_TIMESTAMP
           WHERE revoked_at IS NULL AND last_active_at < datetime('now', '-12 hours')`,
				),
				db
					.prepare(
						"INSERT INTO admin_sessions (id, user_id, csrf_token, ip_address, user_agent) VALUES (?, ?, ?, ?, ?)",
					)
					.bind(storedSessionId, row.id, csrfToken, null, "astropress-cloudflare-adapter"),
			]);

			return {
				id: sessionId,
				email: row.email,
				isAdmin: row.is_admin === 1,
			};
		},
		async signOut(sessionId) {
			const revokeStmt =
				"UPDATE admin_sessions SET revoked_at = CURRENT_TIMESTAMP WHERE id = ? AND revoked_at IS NULL";
			const statements = [db.prepare(revokeStmt).bind(sessionId)];
			for (const secret of resolveCloudflareSessionSecretCandidates()) {
				statements.push(
					db.prepare(revokeStmt).bind(await createSessionTokenDigest(sessionId, secret)),
				);
			}
			await db.batch(statements);
		},
		async getSession(sessionId) {
			const row = await getLiveCloudflareSessionRow(db, sessionId);
			if (!row) return null;
			return {
				id: sessionId,
				email: row.email,
				isAdmin: row.is_admin === 1,
			};
		},
	};
}

