import type { D1DatabaseLike } from "./d1-database";
import type { LocalAdminStoreModule } from "./local-runtime-modules";
import { loadLocalAdminStore } from "./local-runtime-modules";
import { getCloudflareBindings } from "./runtime-env";

/** Returns the D1 database binding from request locals, or undefined if not available. */
export function getAdminDb(locals?: App.Locals | null): D1DatabaseLike | undefined {
	return getCloudflareBindings(locals).DB;
}

/**
 * Dispatches to the D1 handler when a database binding is present,
 * or to the local admin store fallback otherwise.
 *
 * This is the single point of dispatch for all admin runtime operations,
 * eliminating the repeated `if (!db) { loadLocalAdminStore() }` pattern.
 */
export async function withLocalStoreFallback<T>(
	locals: App.Locals | null | undefined,
	onD1: (db: D1DatabaseLike) => Promise<T>,
	onLocal: (store: LocalAdminStoreModule) => Promise<T>,
): Promise<T> {
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const localStore = await loadLocalAdminStore();
		return onLocal(localStore);
	}
	return onD1(db);
}

/**
 * Loads the local admin store, returning null if it fails to load.
 * Used in read-only contexts where a missing local store should fall back to static data.
 */
export async function safeLoadLocalAdminStore(): Promise<LocalAdminStoreModule | null> {
	/* v8 ignore next 6 */
	try {
		return await loadLocalAdminStore();
	} catch {
		return null;
	}
}

/**
 * Like withLocalStoreFallback, but catches errors when loading the local store.
 * Used in read-only contexts where a missing local store should return a static fallback.
 */
export async function withSafeLocalStoreFallback<T>(
	locals: App.Locals | null | undefined,
	onD1: (db: D1DatabaseLike) => Promise<T>,
	onLocal: (store: LocalAdminStoreModule | null) => Promise<T>,
): Promise<T> {
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		let localStore: LocalAdminStoreModule | null = null;
		/* v8 ignore next 6 */
		try {
			localStore = await loadLocalAdminStore();
		} catch {
			// local store unavailable — onLocal receives null and handles fallback
		}
		return onLocal(localStore);
	}
	return onD1(db);
}

src/build-time-content-loader.ts.source:
import type {
	AstropressPlatformAdapter,
	ContentStoreRecord,
	ReadableContentKind,
} from "./platform-contracts";

export interface AstropressBuildTimeLoaderOptions {
	/** Locale to filter content by. Defaults to all locales. */
	locale?: string;
}

/**
 * A lazy loader that fetches a collection of records from the provider at
 * build time and returns them for use in Astro content collections.
 */
export interface AstropressContentLoader {
	/**
	 * Fetch all records of this kind from the provider.
	 * By default, only "published" records are returned.
	 */
	load(): Promise<ContentStoreRecord[]>;
	/** The content kind this loader targets. */
	readonly kind: ReadableContentKind;
}

/**
 * Create build-time content collection loaders for a given provider adapter.
 *
 * Each loader calls ContentStore.list with status "published" so that draft
 * content is never included in the static production build.
 *
 * @example
 * ```ts
 * // astro.config.mjs (public site project)
 * import { defineCollection } from "astro:content";
 * import { createAstropressBuildTimeLoader } from "@astropress-diy/astropress";
 * import { adapter } from "./src/astropress/local-runtime-modules";
 *
 * const loader = createAstropressBuildTimeLoader(adapter);
 *
 * export const collections = {
 *   posts: defineCollection({ loader: loader.posts() }),
 *   pages: defineCollection({ loader: loader.pages() }),
 * };
 * ```
 */
export function createAstropressBuildTimeLoader(
	provider: AstropressPlatformAdapter,
	options: AstropressBuildTimeLoaderOptions = {},
): {
	posts(): AstropressContentLoader;
	pages(): AstropressContentLoader;
} {
	function makeLoader(kind: "post" | "page"): AstropressContentLoader {
		return {
			kind,
			async load() {
				const records = await provider.content.list(kind, {
					status: "published",
					locale: options.locale,
				});
				return records;
			},
		};
	}

	return {
		posts: () => makeLoader("post"),
		pages: () => makeLoader("page"),
	};
}

