	cloudflareSqliteBootstrapStubPath?: string;
};

type ResolvedStubPaths = {
	localImageStorage: string;
	localMediaStorage: string;
	sqliteAdapter: string;
	sqliteAdminRuntime: string;
	sqliteBootstrap: string;
	localRuntimeStubs: string;
};

type ResolveIdEntry = {
	check: (id: string, localRuntimeModulesPath: string) => boolean;
	stubKey: keyof ResolvedStubPaths;
};

const aliasPatterns: Array<{
	find: string | RegExp;
	stubKey: keyof ResolvedStubPaths;
}> = [
	{ find: "astropress/local-image-storage", stubKey: "localImageStorage" },
	{
		find: /^.*\/local-image-storage(?:\.[cm]?[jt]s)?$/,
		stubKey: "localImageStorage",
	},
	{ find: "astropress/local-media-storage", stubKey: "localMediaStorage" },
	{
		find: /^.*\/local-media-storage(?:\.[cm]?[jt]s)?$/,
		stubKey: "localMediaStorage",
	},
	{ find: "astropress/adapters/sqlite", stubKey: "sqliteAdapter" },
	{ find: /^.*\/adapters\/sqlite(?:\.[cm]?[jt]s)?$/, stubKey: "sqliteAdapter" },
	{ find: "astropress/sqlite-admin-runtime", stubKey: "sqliteAdminRuntime" },
	{
		find: /^.*\/sqlite-admin-runtime(?:\.[cm]?[jt]s)?$/,
		stubKey: "sqliteAdminRuntime",
	},
	{ find: "astropress/sqlite-bootstrap", stubKey: "sqliteBootstrap" },
	{
		find: /^.*\/sqlite-bootstrap(?:\.[cm]?[jt]s)?$/,
		stubKey: "sqliteBootstrap",
	},
	{
		find: /^\.\/local-runtime-modules(?:\.ts)?$/,
		stubKey: "localRuntimeStubs",
	},
	{
		find: /^.*\/local-runtime-modules(?:\.ts)?$/,
		stubKey: "localRuntimeStubs",
	},
];

const resolveIdEntries: ResolveIdEntry[] = [
	{
		check: (id) => isPackageStorageModuleRequest(id, "local-image-storage"),
		stubKey: "localImageStorage",
	},
	{
		check: (id) => isPackageStorageModuleRequest(id, "local-media-storage"),
		stubKey: "localMediaStorage",
	},
	{ check: (id) => isSqliteAdapterRequest(id), stubKey: "sqliteAdapter" },
	{
		check: (id) => isSqliteAdminRuntimeRequest(id),
		stubKey: "sqliteAdminRuntime",
	},
	{ check: (id) => isSqliteBootstrapRequest(id), stubKey: "sqliteBootstrap" },
	{
		check: (id, lrm) => isLocalRuntimeModuleRequest(id, lrm),
		stubKey: "localRuntimeStubs",
	},
];

function isLocalRuntimeModuleRequest(id: string, localRuntimeModulesPath: string): boolean {
	if (
		id === "./local-runtime-modules" ||
		id === "./local-runtime-modules.ts" ||
		id === "local-runtime-modules" ||
		id === "local-runtime-modules.ts"
	) {
		return true;
	}

	return (
		id === localRuntimeModulesPath ||
		id.endsWith("/local-runtime-modules") ||
		id.endsWith("/local-runtime-modules.ts")
	);
}

function isPackageStorageModuleRequest(
	id: string,
	moduleName: "local-image-storage" | "local-media-storage",
): boolean {
	return (
		id === `astropress/${moduleName}` ||
		id.endsWith(`/${moduleName}`) ||
		id.endsWith(`/${moduleName}.ts`) ||
		id.endsWith(`/${moduleName}.js`)
	);
}

function isSqliteAdminRuntimeRequest(id: string): boolean {
	return (
		id === "astropress/sqlite-admin-runtime" ||
		id.endsWith("/sqlite-admin-runtime") ||
		id.endsWith("/sqlite-admin-runtime.ts") ||
		id.endsWith("/sqlite-admin-runtime.js")
	);
}

function isSqliteAdapterRequest(id: string): boolean {
	return (
		id === "astropress/adapters/sqlite" ||
		id.endsWith("/adapters/sqlite") ||
		id.endsWith("/adapters/sqlite.ts") ||
		id.endsWith("/adapters/sqlite.js")
	);
}

function isSqliteBootstrapRequest(id: string): boolean {
	return (
		id === "astropress/sqlite-bootstrap" ||
		id.endsWith("/sqlite-bootstrap") ||
		id.endsWith("/sqlite-bootstrap.ts") ||
		id.endsWith("/sqlite-bootstrap.js")
	);
}

function normalizeImportId(id: string): string {
	let normalized = id.replaceAll("\\", "/");
	if (normalized.startsWith("file://")) {
		normalized = decodeURIComponent(normalized.replace(/^file:\/\/\/?/, "/"));
	}

	if (/^\/[a-zA-Z]:\//.test(normalized)) {
		return normalized.slice(1);
	}

	return normalized;
}

function resolveStubPaths(options: AstropressCloudflareViteIntegrationOptions): ResolvedStubPaths {
	return {
		localImageStorage:
			options.cloudflareLocalImageStorageStubPath ??
			"astropress/cloudflare-local-image-storage-stub",
		localMediaStorage:
			options.cloudflareLocalMediaStorageStubPath ??
			"astropress/cloudflare-local-media-storage-stub",
		sqliteAdapter:
			options.cloudflareSqliteAdapterStubPath ?? "astropress/cloudflare-sqlite-adapter-stub",
		sqliteAdminRuntime:
			options.cloudflareSqliteAdminRuntimeStubPath ??
			"astropress/cloudflare-sqlite-admin-runtime-stub",
		sqliteBootstrap:
			options.cloudflareSqliteBootstrapStubPath ?? "astropress/cloudflare-sqlite-bootstrap-stub",
		localRuntimeStubs:
			options.cloudflareLocalRuntimeStubsPath ?? "astropress/cloudflare-local-runtime-stubs",
	};
}

function resolvePluginId(
	normalizedId: string,
	localRuntimeModulesPath: string,
	stubs: ResolvedStubPaths,
): string | null {
	const match = resolveIdEntries.find((entry) =>
		entry.check(normalizedId, localRuntimeModulesPath),
	);
	return match ? stubs[match.stubKey] : null;
}

function buildAliases(
	stubs: ResolvedStubPaths,
	localRuntimeModulesPath: string,
): Array<{ find: string | RegExp; replacement: string }> {
	const aliases = aliasPatterns.map((entry) => ({
		find: entry.find,
		replacement: stubs[entry.stubKey],
	}));
	aliases.push({
		find: localRuntimeModulesPath,
		replacement: stubs.localRuntimeStubs,
	});
	return aliases;
}

export function createAstropressCloudflareViteIntegration(
	localRuntimeModulesPath: string,
	options: AstropressCloudflareViteIntegrationOptions = {},
): AstropressCloudflareViteIntegration {
	const stubs = resolveStubPaths(options);

	return {
		aliases: buildAliases(stubs, localRuntimeModulesPath),
		plugin: {
			name: "astropress-cloudflare-local-runtime-stubs",
			enforce: "pre",
			resolveId(id) {
				return resolvePluginId(normalizeImportId(id), localRuntimeModulesPath, stubs);
			},
		},
	};
}

src/cms-route-registry-helpers.ts.source:
import type { Actor } from "./persistence-types";
import type { RuntimeSystemRouteRecord } from "./runtime-route-registry";

export type { AstropressCmsRouteRegistryFactoryInput } from "./cms-route-registry-types";

import type { AstropressCmsRouteRegistryFactoryInput } from "./cms-route-registry-types";

interface RouteActor extends Actor {}

export type StructuredPageInput = {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks?: Array<{ hreflang: string; href: string }>;
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	sections?: Record<string, unknown> | null;
	revisionNote?: string;
};

export type ArchiveRouteInput = {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	revisionNote?: string;
};

/** Normalize structured page input fields, centralising branchy fallback logic. */
export function normalizeStructuredInput(rawInput: {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks?: Array<{ hreflang: string; href: string }>;
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	sections?: Record<string, unknown> | null;
}) {
	const title = rawInput.title.trim();
	const summary = rawInput.summary?.trim() || null;
	const seoTitle = rawInput.seoTitle?.trim() || title;
	const metaDescription = rawInput.metaDescription?.trim() || summary || title;
	const canonicalUrlOverride = rawInput.canonicalUrlOverride?.trim() || null;
	const robotsDirective = rawInput.robotsDirective?.trim() || null;
	const ogImage = rawInput.ogImage?.trim() || null;
	const alternateLinks = rawInput.alternateLinks ?? [];
	const sections = rawInput.sections ?? null;
	return {
		title,
		summary,
		seoTitle,
		metaDescription,
		canonicalUrlOverride,
		robotsDirective,
		ogImage,
		alternateLinks,
		sections,
	};
}

/** Normalize archive route input fields. */
export function normalizeArchiveInput(rawInput: {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
}) {
	const title = rawInput.title.trim();
	const summary = rawInput.summary?.trim() || null;
	const seoTitle = rawInput.seoTitle?.trim() || title;
	const metaDescription = rawInput.metaDescription?.trim() || summary || "";
	const canonicalUrlOverride = rawInput.canonicalUrlOverride?.trim() || null;
	const robotsDirective = rawInput.robotsDirective?.trim() || null;
	return {
		title,
		summary,
		seoTitle,
		metaDescription,
		canonicalUrlOverride,
		robotsDirective,
	};
}

export function doSaveSystemRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: {
		title: string;
		summary?: string;
		bodyHtml?: string;
		// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
		settings?: Record<string, unknown> | null;
		revisionNote?: string;
	},
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	if (!normalizedPath) {
		return { ok: false as const, error: "A system route path is required." };
	}
	const route = ctx.findSystemRouteForUpdate(normalizedPath);
	if (!route) {
		return {
			ok: false as const,
			error: "The selected system route could not be found.",
		};
	}
	const title = rawInput.title.trim();
	if (!title) {
		return { ok: false as const, error: "A title is required." };
	}
	const summary = rawInput.summary?.trim() || null;
	const bodyHtml = rawInput.bodyHtml?.trim() || null;
	const settings = rawInput.settings ?? null;
	ctx.persistSystemRoute({
		routeId: route.id,
		title,
		summary,
		bodyHtml,
		settingsJson: settings ? JSON.stringify(settings) : null,
		actor,
	});
	ctx.appendSystemRouteRevision({
		routeId: route.id,
		pathname: normalizedPath,
		locale: ctx.localeFromPath(normalizedPath),
		title,
		summary,
		bodyHtml,
		settings,
		renderStrategy: route.renderStrategy,
		revisionNote: rawInput.revisionNote?.trim() || null,
		actor,
	});
	ctx.recordRouteAudit({
		actor,
		action: "system.update",
		summary: `Updated system route ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	return {
		ok: true as const,
		route: {
			path: normalizedPath,
			title,
			summary: summary ?? undefined,
			bodyHtml: bodyHtml ?? undefined,
			settings,
			renderStrategy: route.renderStrategy,
		} satisfies RuntimeSystemRouteRecord,
	};
}

export function doCreateStructuredPageRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: StructuredPageInput,
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	if (!normalizedPath || normalizedPath === "/") {
		return { ok: false as const, error: "A public path is required." };
	}
	if (ctx.isRoutePathTaken(normalizedPath)) {
		return { ok: false as const, error: "That public path is already in use." };
	}
	const f = normalizeStructuredInput(rawInput);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}
	const locale = ctx.localeFromPath(normalizedPath);
	const shared = {
		pathname: normalizedPath,
		locale,
		templateKey: rawInput.templateKey,
		actor,
		...f,
	};
	ctx.insertStructuredRoute(shared);
	const created = ctx.getStructuredPageRoute(normalizedPath);
	const routeId = ctx.findStructuredRouteForUpdate(normalizedPath);
	if (!created || !routeId) {
		return {
			ok: false as const,
			error: "The route page could not be created.",
		};
	}
	ctx.appendStructuredRouteRevision({
		routeId: routeId.id,
		...shared,
		revisionNote: rawInput.revisionNote?.trim() || "Created route page.",
	});
	ctx.recordRouteAudit({
		actor,
		action: "route_page.create",
		summary: `Created route page ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	return { ok: true as const, route: created };
}

export function doSaveStructuredPageRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: StructuredPageInput,
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	const route = ctx.findStructuredRouteForUpdate(normalizedPath);
	if (!route) {
		return {
			ok: false as const,
			error: "The selected route page could not be found.",
		};
	}
	const f = normalizeStructuredInput(rawInput);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}
	const shared = {
		pathname: normalizedPath,
		templateKey: rawInput.templateKey,
		actor,
		...f,
	};
	ctx.persistStructuredRoute({ routeId: route.id, ...shared });
	ctx.appendStructuredRouteRevision({
		routeId: route.id,
		locale: ctx.localeFromPath(normalizedPath),
		...shared,
		revisionNote: rawInput.revisionNote?.trim() || null,
	});
	ctx.recordRouteAudit({
		actor,
		action: "route_page.update",
		summary: `Updated route page ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	const saved = ctx.getStructuredPageRoute(normalizedPath);
	if (!saved) throw new Error(`Route ${normalizedPath} not found after save`);
	return { ok: true as const, route: saved };
}

export function doSaveArchiveRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: ArchiveRouteInput,
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	const route = ctx.findArchiveRouteForUpdate(normalizedPath);
	if (!route) {
		return {
			ok: false as const,
			error: "The selected archive route could not be found.",
		};
	}
	const f = normalizeArchiveInput(rawInput);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}
	ctx.persistArchiveRoute({
		routeId: route.id,
		pathname: normalizedPath,
		actor,
		...f,
	});
	ctx.appendArchiveRouteRevision({
		routeId: route.id,
		pathname: normalizedPath,
		...f,
		revisionNote: rawInput.revisionNote?.trim() || null,
		actor,
	});
	ctx.recordRouteAudit({
		actor,
		action: "archive.update",
		summary: `Updated archive route ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	const savedArchive = ctx.getArchiveRoute(normalizedPath);
	if (!savedArchive) throw new Error(`Archive route ${normalizedPath} not found after save`);
	return { ok: true as const, route: savedArchive };
}

src/crypto-primitives.ts.source:
import { argon2id } from "@noble/hashes/argon2.js";
import { kmac256 } from "@noble/hashes/sha3-addons.js";
import { ml_dsa65 } from "@noble/post-quantum/ml-dsa.js";

const textEncoder = new TextEncoder();

const ARGON2_PREFIX = "v3:argon2id";
const ARGON2_MEMORY_KIB = 19_456;
const ARGON2_ITERATIONS = 2;
const ARGON2_LANES = 1;
const ARGON2_HASH_LENGTH = 32;
const DEFAULT_SALT_LENGTH = 16;
const DEFAULT_KMAC_LENGTH = 32;

function encodeUtf8(value: string) {
	return textEncoder.encode(value);
}

function base64ToBytes(value: string) {
	const binary = atob(value);
	const bytes = new Uint8Array(binary.length);
	for (let index = 0; index < binary.length; index += 1) {
		bytes[index] = binary.charCodeAt(index);
	}
	return bytes;
}

export function bytesToBase64(bytes: Uint8Array) {
	let binary = "";
	for (const byte of bytes) {
		binary += String.fromCharCode(byte);
	}
	return btoa(binary);
}

export function bytesToHex(bytes: Uint8Array) {
	return Array.from(bytes)
		.map((byte) => byte.toString(16).padStart(2, "0"))
		.join("");
}

export function constantTimeEqual(left: Uint8Array, right: Uint8Array) {
	if (left.length !== right.length) {
		return false;
	}

	let mismatch = 0;
	for (let index = 0; index < left.length; index += 1) {
		mismatch |= left[index] ^ right[index];
	}
	return mismatch === 0;
}

function randomBytes(length: number) {
	return crypto.getRandomValues(new Uint8Array(length));
}

function kmacContext(purpose: string) {
	return encodeUtf8(`astropress:${purpose}`);
}

export function createKmacDigest(
	value: string,
	secret: string,
	purpose: string,
	dkLen = DEFAULT_KMAC_LENGTH,
) {
	const digest = kmac256(encodeUtf8(secret), encodeUtf8(value), {
		dkLen,
		personalization: kmacContext(purpose),
	});
	return bytesToHex(digest);
}

export function hashPasswordArgon2id(
	password: string,
	options: {
		saltLength?: number;
		iterations?: number;
		memoryKiB?: number;
		parallelism?: number;
	} = {},
) {
	const salt = randomBytes(options.saltLength ?? DEFAULT_SALT_LENGTH);
	const iterations = options.iterations ?? ARGON2_ITERATIONS;
	const memoryKiB = options.memoryKiB ?? ARGON2_MEMORY_KIB;
	const parallelism = options.parallelism ?? ARGON2_LANES;
	const digest = argon2id(encodeUtf8(password), salt, {
		t: iterations,
		m: memoryKiB,
		p: parallelism,
		dkLen: ARGON2_HASH_LENGTH,
	});
	return `${ARGON2_PREFIX}$${iterations}$${memoryKiB}$${parallelism}$${bytesToBase64(salt)}$${bytesToBase64(digest)}`;
}

export function isArgon2idHash(storedHash: string) {
	return storedHash.startsWith(`${ARGON2_PREFIX}$`);
}

export function verifyArgon2idPassword(password: string, storedHash: string) {
	try {
		if (!isArgon2idHash(storedHash)) {
			return false;
		}

		const [prefix, iterationsText, memoryText, parallelismText, saltBase64, hashBase64] =
			storedHash.split("$");
		if (
			prefix !== ARGON2_PREFIX ||
			!iterationsText ||
			!memoryText ||
			!parallelismText ||
			!saltBase64 ||
			!hashBase64
		) {
			return false;
		}

		const iterations = Number.parseInt(iterationsText, 10);
		const memoryKiB = Number.parseInt(memoryText, 10);
		const parallelism = Number.parseInt(parallelismText, 10);
		if (!iterations || !memoryKiB || !parallelism) {
			return false;
		}

		const salt = base64ToBytes(saltBase64);
		const expected = base64ToBytes(hashBase64);
		const actual = argon2id(encodeUtf8(password), salt, {
			t: iterations,
			m: memoryKiB,
			p: parallelism,
			dkLen: expected.length,
		});
		return constantTimeEqual(actual, expected);
	} catch {
		return false;
	}
}

export interface MlDsaVerificationKey {
	algorithm: "ML-DSA-65";
	keyId: string;
	publicKey: string;
	encoding: "base64";
}

export function createMlDsaKeyPair(keyId: string, seed = randomBytes(32)) {
	const keys = ml_dsa65.keygen(seed);
	return {
		keyId,
		publicKey: keys.publicKey,
		secretKey: keys.secretKey,
		verification: {
			algorithm: "ML-DSA-65" as const,
			keyId,
			publicKey: bytesToBase64(keys.publicKey),
			encoding: "base64" as const,
		},
	};
}

export function signMlDsaMessage(message: string, secretKeyBase64: string) {
	return bytesToBase64(ml_dsa65.sign(encodeUtf8(message), base64ToBytes(secretKeyBase64)));
}

export function verifyMlDsaMessage(
	message: string,
	signatureBase64: string,
	publicKeyBase64: string,
) {
	return ml_dsa65.verify(
		base64ToBytes(signatureBase64),
		encodeUtf8(message),
		base64ToBytes(publicKeyBase64),
	);
}

export function secretKeyToBase64(secretKey: Uint8Array) {
	return bytesToBase64(secretKey);
}

src/d1-rate-limit-part.ts.source:
import type { D1AdminReadStore } from "./d1-admin-store";
import type { D1DatabaseLike } from "./d1-database";

/** Rate-limit logic shared between read (check/peek) and mutation (recordFailedAttempt) stores. */
export function createD1RateLimitPart(db: D1DatabaseLike): D1AdminReadStore["rateLimits"] {
	return {
		async checkRateLimit(key: string, max: number, windowMs: number) {
			const now = Date.now();
			const row = await db
				.prepare("SELECT count, window_start_ms, window_ms FROM rate_limits WHERE key = ? LIMIT 1")
				.bind(key)
				.first<{ count: number; window_start_ms: number; window_ms: number }>();

			if (!row || now - row.window_start_ms > windowMs) {
				await db
					.prepare(
						`
              INSERT INTO rate_limits (key, count, window_start_ms, window_ms)
              VALUES (?, 1, ?, ?)
              ON CONFLICT(key) DO UPDATE SET
                count = 1,
                window_start_ms = excluded.window_start_ms,
                window_ms = excluded.window_ms
            `,
					)
					.bind(key, now, windowMs)
					.run();
				return true;
			}

			if (row.count < max) {
				await db.prepare("UPDATE rate_limits SET count = count + 1 WHERE key = ?").bind(key).run();
				return true;
			}

			return false;
		},
		async peekRateLimit(key: string, max: number, windowMs: number) {
			const now = Date.now();
			const row = await db
				.prepare("SELECT count, window_start_ms FROM rate_limits WHERE key = ? LIMIT 1")
				.bind(key)
				.first<{ count: number; window_start_ms: number }>();
			if (!row || now - row.window_start_ms > windowMs) return true;
			return row.count < max;
		},
		async recordFailedAttempt(key: string, _max: number, windowMs: number) {
			const now = Date.now();
			const row = await db
				.prepare("SELECT count, window_start_ms FROM rate_limits WHERE key = ? LIMIT 1")
				.bind(key)
				.first<{ count: number; window_start_ms: number }>();
			if (!row || now - row.window_start_ms > windowMs) {
				await db
					.prepare(
						`
              INSERT INTO rate_limits (key, count, window_start_ms, window_ms)
              VALUES (?, 1, ?, ?)
              ON CONFLICT(key) DO UPDATE SET
                count = 1,
                window_start_ms = excluded.window_start_ms,
                window_ms = excluded.window_ms
            `,
					)
					.bind(key, now, windowMs)
					.run();
				return;
			}
			await db.prepare("UPDATE rate_limits SET count = count + 1 WHERE key = ?").bind(key).run();
		},
	};
}

src/d1-store-operations-helpers.ts.source:
import type { D1DatabaseLike } from "./d1-database";
import {
	deriveAdminUserStatus,
	mapPersistedAdminUserRow,
	mapPersistedAuditEvent,
	type PersistedAdminUserRow,
	type PersistedAuditEventRow,
	SQL_LIST_ADMIN_USERS_WITH_INVITE,
	SQL_LIST_AUDIT_EVENTS,
} from "./persistence-commons";
import type {
	AuditEvent,
	CommentRecord,
	CommentStatus,
	ContactSubmission,
	MediaAsset,
	RedirectRule,
	TestimonialSource,
	TestimonialStatus,
	TestimonialSubmission,
	TestimonialSubmissionInput,
} from "./persistence-types";
import type { SiteSettings } from "./site-settings";

export { deriveAdminUserStatus };

export type CommentPolicy = "legacy-readonly" | "disabled" | "open-moderated";

export type AuditEventRow = PersistedAuditEventRow;

export type AdminUserRow = PersistedAdminUserRow;

export type CommentRow = {
	id: string;
	author: string;
	email: string | null;
	body: string | null;
	route: string;
	status: CommentStatus;
	policy: CommentPolicy;
	submitted_at: string;
};

export type TestimonialRow = {
	id: string;
	name: string;
	email: string;
	company: string | null;
	role: string | null;
	before_state: string | null;
	transformation: string | null;
	specific_result: string | null;
	consent_to_publish: number;
	status: string;
	source: string;
	submitted_at: string;
	approved_at: string | null;
};

export type MediaRow = {
	id: string;
	source_url: string | null;
	local_path: string;
	r2_key: string | null;
	mime_type: string | null;
	width: number | null;
	height: number | null;
	file_size: number | null;
	alt_text: string | null;
	title: string | null;
	uploaded_at: string;
	uploaded_by: string | null;
};

export type SettingsRow = {
	site_title: string;
	site_tagline: string;
	donation_url: string;
	newsletter_enabled: number;
	comments_default_policy: SiteSettings["commentsDefaultPolicy"];
	admin_slug: string;
};

/* ── Constants ── */

export const SQL_AUDIT_EVENTS = SQL_LIST_AUDIT_EVENTS;
export const SQL_ADMIN_USERS = SQL_LIST_ADMIN_USERS_WITH_INVITE;

export const SQL_REDIRECT_RULES = `SELECT source_path, target_path, status_code FROM redirect_rules
   WHERE deleted_at IS NULL ORDER BY source_path ASC`;

export const SQL_COMMENTS = `SELECT id, author, email, body, route, status, policy, submitted_at FROM comments
   ORDER BY CASE status WHEN 'pending' THEN 0 WHEN 'approved' THEN 1 ELSE 2 END,
     datetime(submitted_at) DESC, id DESC`;

export const SQL_CONTACT_SUBMISSIONS = `SELECT id, name, email, message, submitted_at FROM contact_submissions
   ORDER BY datetime(submitted_at) DESC, id DESC`;

export const SQL_TESTIMONIALS = `SELECT id, name, email, company, role, before_state, transformation,
          specific_result, consent_to_publish, status, source, submitted_at, approved_at
   FROM testimonial_submissions WHERE (? IS NULL OR status = ?)
   ORDER BY submitted_at DESC, id DESC`;

export const SQL_TRANSLATION_STATE =
	"SELECT state FROM translation_overrides WHERE route = ? LIMIT 1";

export const SQL_SITE_SETTINGS = `SELECT site_title, site_tagline, donation_url, newsletter_enabled,
          comments_default_policy, admin_slug
   FROM site_settings WHERE id = 1 LIMIT 1`;

export const SQL_MEDIA_ASSETS = `SELECT id, source_url, local_path, r2_key, mime_type, width, height,
          file_size, alt_text, title, uploaded_at, uploaded_by
   FROM media_assets WHERE deleted_at IS NULL
   ORDER BY datetime(uploaded_at) DESC, id DESC`;

export const TESTIMONIAL_INSERT_SQL = `INSERT INTO testimonial_submissions
     (id, name, email, company, role, before_state, transformation,
      specific_result, consent_to_publish, status, source, submitted_at)
   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?)`;

export const CONTACT_INSERT_SQL = `INSERT INTO contact_submissions (id, name, email, message, submitted_at)
   VALUES (?, ?, ?, ?, ?)`;

export const COMMENT_INSERT_SQL = `INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at)
   VALUES (?, ?, ?, ?, ?, ?, ?, ?)`;

/* ── Row-mapping helpers ── */

export function mapAuditEventRow(row: AuditEventRow): AuditEvent {
	return mapPersistedAuditEvent({ row, idPrefix: "d1-audit-" });
}

export const deriveUserStatus = deriveAdminUserStatus;

export const mapAdminUserRow = mapPersistedAdminUserRow;

export function mapCommentRow(row: CommentRow): CommentRecord {
	return {
		id: row.id,
		author: row.author,
		email: row.email ?? undefined,
		body: row.body ?? undefined,
		route: row.route,
		status: row.status,
		policy: row.policy,
		submittedAt: row.submitted_at,
	};
}

export function mapTestimonialRow(row: TestimonialRow): TestimonialSubmission {
	return {
		id: row.id,
		name: row.name,
		email: row.email,
		company: row.company ?? undefined,
		role: row.role ?? undefined,
		beforeState: row.before_state ?? undefined,
		transformation: row.transformation ?? undefined,
		specificResult: row.specific_result ?? undefined,
		consentToPublish: row.consent_to_publish === 1,
		status: row.status as TestimonialStatus,
		source: row.source as TestimonialSource,
		submittedAt: row.submitted_at,
		approvedAt: row.approved_at ?? undefined,
	};
}

export function mapSettingsRow(row: SettingsRow): SiteSettings {
	return {
		siteTitle: row.site_title,
		siteTagline: row.site_tagline,
		donationUrl: row.donation_url,
		newsletterEnabled: row.newsletter_enabled === 1,
		commentsDefaultPolicy: row.comments_default_policy,
		adminSlug: row.admin_slug ?? "ap-admin",
	};
}

export function mapMediaRow(row: MediaRow): MediaAsset {
	return {
		id: row.id,
		sourceUrl: row.source_url,
		localPath: row.local_path,
		r2Key: row.r2_key,
		mimeType: row.mime_type,
		width: row.width,
		height: row.height,
		fileSize: row.file_size,
		altText: row.alt_text ?? "",
		title: row.title ?? "",
		uploadedAt: row.uploaded_at,
		uploadedBy: row.uploaded_by ?? "",
	};
}

export function mapContactRow(row: {
	id: string;
	name: string;
	email: string;
	message: string;
	submitted_at: string;
}): ContactSubmission {
	return {
		id: row.id,
		name: row.name,
		email: row.email,
		message: row.message,
		submittedAt: row.submitted_at,
	};
}

export function mapRedirectRow(row: {
	source_path: string;
	target_path: string;
	status_code: 301 | 302;
}): RedirectRule {
	return {
		sourcePath: row.source_path,
		targetPath: row.target_path,
		statusCode: row.status_code,
	};
}

/* ── Bind-param helpers ── */

export function testimonialInputBindParams(id: string, input: TestimonialSubmissionInput) {
	return [
		id,
		input.name,
		input.email,
		input.company ?? null,
		input.role ?? null,
		input.beforeState ?? null,
		input.transformation ?? null,
		input.specificResult ?? null,
		input.consentToPublish ? 1 : 0,
		input.source,
		input.submittedAt,
	] as const;
}

export function buildCommentBindParams(comment: CommentRecord, submittedAt: string) {
	return [
		comment.id,
		comment.author,
		comment.email ?? null,
		comment.body ?? null,
		comment.route,
		comment.status,
		comment.policy,
		submittedAt,
	] as const;
}

export function bindTestimonialFilter(
	db: D1DatabaseLike,
	status: TestimonialStatus | null | undefined,
) {
	const val = status ?? null;
	return db.prepare(SQL_TESTIMONIALS).bind(val, val);
}

export function buildApprovedAtExpr(status: TestimonialStatus): string {
	const approvedStatuses: TestimonialStatus[] = ["approved", "featured"];
	return approvedStatuses.includes(status)
		? "CASE WHEN approved_at IS NULL THEN CURRENT_TIMESTAMP ELSE approved_at END"
		: "approved_at";
}

export function buildModerateSql(db: D1DatabaseLike, status: TestimonialStatus, id: string) {
	const approvedAtExpr = buildApprovedAtExpr(status);
	const sql = `UPDATE testimonial_submissions SET status = ?, approved_at = ${approvedAtExpr} WHERE id = ?`;
	return db.prepare(sql).bind(status, id).run();
}

