src/integrations/providers/cloudflare-cd.source:
/**
 * Cloudflare CDN purge provider — push-button registration for the
 * cdn-purge domain.
 *
 * verify() is a two-step probe:
 *
 *   1. GET /client/v4/user/tokens/verify — confirms the token itself
 *      is valid (Cloudflare returns 401 for revoked / malformed
 *      tokens here).
 *   2. GET /client/v4/zones/{zoneId} — confirms the token has scope
 *      for the configured zone (a token without zone:read on this
 *      zone returns 403 here even though step 1 succeeded).
 *
 * The classifier (classifyCloudflareStatus) is shared between both
 * steps so the mapping stays consistent and is unit-testable as a
 * pure function.
 */

import { z } from "zod";

import type { IntegrationErrorCode } from "../../integration-error-sanitizer.js";
import { registerCdnPurge } from "../domains.js";
import type { RegisteredProvider } from "../registry.js";

export const CLOUDFLARE_CDN_FIELDS = z.object({
	apiToken: z.string().min(1),
	zoneId: z.string().min(1),
});

export type CloudflareCdnFields = z.infer<typeof CLOUDFLARE_CDN_FIELDS>;

const HOST = "https://api.cloudflare.com";
const TOKEN_VERIFY_PATH = "/client/v4/user/tokens/verify";
const ZONES_PATH = "/client/v4/zones/";

export class CloudflareCdnVerifyError extends Error {
	constructor(public readonly code: IntegrationErrorCode) {
		super(code);
		this.name = "CloudflareCdnVerifyError";
	}
}

export interface CloudflareCdnVerifyDeps {
	readonly fetch?: typeof fetch;
}

export function buildCloudflareTokenVerifyUrl(): string {
	return new URL(TOKEN_VERIFY_PATH, HOST).toString();
}

export function buildCloudflareZoneUrl(zoneId: string): string {
	return new URL(ZONES_PATH + encodeURIComponent(zoneId), HOST).toString();
}

export function buildCloudflareAuthHeader(apiToken: string): string {
	return `Bearer ${apiToken}`;
}

/**
 * Map an upstream Cloudflare API response to either `null` (success)
 * or an integration error code. Pure — relies only on `res.status`
 * and `res.ok`. Exported so tests pin the mapping independently of
 * the fetch wiring above.
 */
export function classifyCloudflareStatus(res: Response): IntegrationErrorCode | null {
	if (res.status === 401 || res.status === 403) {
		return "INTEGRATION_AUTH_REJECTED";
	}
	if (res.status === 404) {
		return "INTEGRATION_NOT_FOUND";
	}
	if (res.status === 429) {
		return "INTEGRATION_RATE_LIMITED";
	}
	if (res.ok) {
		return null;
	}
	return "INTEGRATION_VERIFY_FAILED";
}

export async function verifyCloudflareCdn(
	fields: CloudflareCdnFields,
	ctx: { signal: AbortSignal },
	deps: CloudflareCdnVerifyDeps = {},
): Promise<void> {
	const fetchImpl = deps.fetch ?? fetch;
	const init: RequestInit = {
		method: "GET",
		headers: { Authorization: buildCloudflareAuthHeader(fields.apiToken) },
		signal: ctx.signal,
	};
	const tokenRes = await fetchImpl(buildCloudflareTokenVerifyUrl(), init);
	const tokenCode = classifyCloudflareStatus(tokenRes);
	if (tokenCode !== null) {
		throw new CloudflareCdnVerifyError(tokenCode);
	}
	const zoneRes = await fetchImpl(buildCloudflareZoneUrl(fields.zoneId), init);
	const zoneCode = classifyCloudflareStatus(zoneRes);
	if (zoneCode !== null) {
		throw new CloudflareCdnVerifyError(zoneCode);
	}
}

export function registerCloudflareCdn(): RegisteredProvider<CloudflareCdnFields> {
	return registerCdnPurge<CloudflareCdnFields>({
		id: "cloudflare",
		label: "Cloudflare",
		fields: CLOUDFLARE_CDN_FIELDS,
		verify: verifyCloudflareCdn,
		defaultErrorCode: "INTEGRATION_VERIFY_FAILED",
	});
}

src/integrations/resolvers/newsletter-re.source:
/**
 * Resolve a newsletter configuration from the available sources.
 *
 * The runtime can find newsletter config in two places, in priority
 * order:
 *
 *   1. **Registry** — admin connected a Listmonk provider via the
 *      Phase 3/4 connect flow. Phase 2 unsealed the
 *      `{baseUrl, apiUser, apiKey}` triple from
 *      `connected_integrations`. Note that `listId` is NOT stored in
 *      the provider record — it is a per-deployment list-target, so
 *      it always comes from `LISTMONK_LIST_ID`.
 *   2. **Process env** — `LISTMONK_API_URL` / `LISTMONK_API_USERNAME` /
 *      `LISTMONK_API_PASSWORD` / `LISTMONK_LIST_ID`. All four must be
 *      set; partial config falls through to mock.
 *
 * `NEWSLETTER_DELIVERY_MODE=mock` always wins (forces mock for local
 * dev / CI even if env credentials happen to be set).
 *
 * The resolver is pure: it consumes a snapshot of all sources and
 * emits a tagged `ResolvedNewsletter` value. The newsletter adapter
 * branches on `kind`.
 */

export type NewsletterCredentialSource = "registry" | "env";

export type ResolvedNewsletter =
	| {
			readonly kind: "listmonk";
			readonly baseUrl: string;
			readonly apiUser: string;
			readonly apiKey: string;
			readonly listId: string;
			readonly credentialSource: NewsletterCredentialSource;
	  }
	| { readonly kind: "mock" }
	| { readonly kind: "misconfigured"; readonly reason: string };

export interface ResolveNewsletterInput {
	readonly registry?: {
		readonly baseUrl: string;
		readonly apiUser: string;
		readonly apiKey: string;
	} | null;
	readonly env?: {
		readonly NEWSLETTER_DELIVERY_MODE?: string;
		readonly LISTMONK_API_URL?: string;
		readonly LISTMONK_API_USERNAME?: string;
		readonly LISTMONK_API_PASSWORD?: string;
		readonly LISTMONK_LIST_ID?: string;
	} | null;
}

function nonEmpty(v: string | undefined | null): v is string {
	return typeof v === "string" && v.length > 0;
}

export function resolveNewsletter(input: ResolveNewsletterInput): ResolvedNewsletter {
	const env = input.env ?? {};
	if (env.NEWSLETTER_DELIVERY_MODE === "mock") {
		return { kind: "mock" };
	}
	const explicitListmonk = env.NEWSLETTER_DELIVERY_MODE === "listmonk";
	const listId = env.LISTMONK_LIST_ID;
	const registry = input.registry;
	if (!nonEmpty(listId)) {
		if (explicitListmonk) {
			return {
				kind: "misconfigured",
				reason: "LISTMONK_LIST_ID is required when NEWSLETTER_DELIVERY_MODE=listmonk",
			};
		}
		return { kind: "mock" };
	}
	if (registry) {
		return {
			kind: "listmonk",
			baseUrl: registry.baseUrl,
			apiUser: registry.apiUser,
			apiKey: registry.apiKey,
			listId,
			credentialSource: "registry",
		};
	}
	if (
		nonEmpty(env.LISTMONK_API_URL) &&
		nonEmpty(env.LISTMONK_API_USERNAME) &&
		nonEmpty(env.LISTMONK_API_PASSWORD)
	) {
		return {
			kind: "listmonk",
			baseUrl: env.LISTMONK_API_URL,
			apiUser: env.LISTMONK_API_USERNAME,
			apiKey: env.LISTMONK_API_PASSWORD,
			listId,
			credentialSource: "env",
		};
	}
	if (explicitListmonk) {
		return {
			kind: "misconfigured",
			reason: "Listmonk mode set but credentials are not fully configured",
		};
	}
	return { kind: "mock" };
}

src/integrations/webhooks/registry.ts.source:
/**
 * In-memory registry of inbound-webhook providers. Pairs with
 * `webhooks/inbound.ts` (the signature primitive) and the
 * `pages/api/webhooks/[provider].ts` Astro route layer.
 *
 * Each registered provider declares the static facts the route layer
 * needs to verify and dispatch a webhook:
 *
 *   - `signatureHeader`: which inbound header carries the HMAC
 *     (e.g. `X-Hub-Signature-256` for GitHub);
 *   - `algorithm`: which `InboundWebhookAlgorithm` to verify under;
 *   - `eventHeader` (optional): which header carries the event name,
 *     used by the route layer to dispatch into per-event handlers
 *     after signature verification succeeds.
 *
 * The secret used to verify HMACs is NOT held in the registry — it
 * comes from the connected-integration row for the same
 * `(domain, providerId)` pair, sealed via the Phase 2 envelope. The
 * registry is therefore safe to enumerate from the admin UI.
 */

import type { InboundWebhookAlgorithm } from "./inbound.js";

export interface InboundWebhookProviderDefinition {
	readonly id: string;
	readonly label: string;
	readonly signatureHeader: string;
	readonly algorithm: InboundWebhookAlgorithm;
	readonly eventHeader?: string;
}

export class InboundWebhookRegistryError extends Error {
	constructor(
		public readonly code: "DUPLICATE_PROVIDER",
		message: string,
	) {
		super(message);
		this.name = "InboundWebhookRegistryError";
	}
}

const registry = new Map<string, InboundWebhookProviderDefinition>();

export function registerInboundWebhookProvider(
	def: InboundWebhookProviderDefinition,
): InboundWebhookProviderDefinition {
	if (registry.has(def.id)) {
		throw new InboundWebhookRegistryError(
			"DUPLICATE_PROVIDER",
			`inbound webhook provider ${def.id} already registered`,
		);
	}
	registry.set(def.id, def);
	return def;
}

export function getInboundWebhookProvider(
	providerId: string,
): InboundWebhookProviderDefinition | undefined {
	return registry.get(providerId);
}

export function listInboundWebhookProviders(): readonly InboundWebhookProviderDefinition[] {
	return Array.from(registry.values());
}

export function _resetInboundWebhookRegistryForTests(): void {
	registry.clear();
}

src/media.ts.source:
import { stripTrailingSlashes } from "./path-helpers";
import { getCloudflareBindings, getStringRuntimeValue, isProductionRuntime } from "./runtime-env";

export interface MediaRecord {
	id: string;
	sourceUrl: string | null;
	localPath: string;
	r2Key: string | null;
}

interface MediaResolutionOptions {
	mode: "development" | "deployment";
	r2BaseUrl?: string;
}

export function resolveMediaUrl(record: MediaRecord, options: MediaResolutionOptions) {
	if (options.mode === "development") {
		return record.localPath;
	}

	if (!options.r2BaseUrl || !record.r2Key) {
		return record.localPath;
	}

	return `${stripTrailingSlashes(options.r2BaseUrl)}/${record.r2Key}`;
}

export function getRuntimeMediaResolutionOptions(
	locals?: App.Locals | null,
): MediaResolutionOptions {
	const bindings = getCloudflareBindings(locals);
	const r2BaseUrl = getStringRuntimeValue("PUBLIC_R2_BASE_URL", locals);
	const useDeploymentMode = Boolean(r2BaseUrl || bindings.MEDIA_BUCKET) || isProductionRuntime();
	return {
		mode: useDeploymentMode ? "deployment" : "development",
		r2BaseUrl,
	};
}

export function resolveRuntimeMediaUrl(record: MediaRecord, locals?: App.Locals | null) {
	return resolveMediaUrl(record, getRuntimeMediaResolutionOptions(locals));
}

src/persistence-commons.ts.source:
/**
 * Shared persistence helpers consumed by both the D1 adapter
 * (packages/astropress/src/d1-*.ts) and the SQLite runtime
 * (packages/astropress/src/sqlite-runtime/*). Dialect-specific SQL stays in
 * each adapter; this module holds only dialect-independent logic.
 */

import {
	AUDIT_TARGET_TYPES,
	CONTENT_STATUSES,
	type ContentStatus,
	DEFAULT_CONTENT_STATUS,
	SQL_LIST_ADMIN_USERS_WITH_INVITE as SQL_LIST_ADMIN_USERS_WITH_INVITE_DATA,
	SQL_LIST_AUDIT_EVENTS as SQL_LIST_AUDIT_EVENTS_DATA,
} from "./persistence-commons-data";
import type { AdminRole, AuditEvent, ContentOverride, ManagedAdminUser } from "./persistence-types";

export type { ContentStatus };

function isContentStatus(value: unknown): value is ContentStatus {
	return (CONTENT_STATUSES as readonly string[]).includes(value as string);
}

// ---------------------------------------------------------------------------
// Slug / path normalization
// ---------------------------------------------------------------------------

export function normalizeSlug(value: string) {
	return value
		.toLowerCase()
		.replace(/[^a-z0-9]/g, "-")
		.split("-")
		.filter(Boolean)
		.join("-");
}

/**
 * Redirect target normalization. Rejects protocol-relative URLs (`//evil/...`)
 * — open-redirect vector — by returning an empty string.
 */
export function normalizeRedirectTarget(value: string) {
	const trimmed = value.trim();
	if (!trimmed) return "";
	if (trimmed.startsWith("//")) return "";
	return trimmed.startsWith("/") ? trimmed : `/${trimmed}`;
}

export function normalizeContentStatus(input?: string | null): ContentStatus {
	return isContentStatus(input) ? input : DEFAULT_CONTENT_STATUS;
}

// ---------------------------------------------------------------------------
// ID list serialization (author_ids, category_ids, tag_ids columns)
// ---------------------------------------------------------------------------

export function parseIdList(value: string | null | undefined): number[] {
	let parsed: unknown;
	try {
		parsed = JSON.parse(value ?? "[]");
	} catch {
		return [];
	}
	if (!Array.isArray(parsed)) return [];
	return parsed
		.map((entry) => Number(entry))
		.filter((entry) => Number.isInteger(entry) && entry > 0);
}

export function serializeIdList(values: number[]): string {
	return JSON.stringify(
		values.filter((entry) => Number.isInteger(entry) && entry > 0).sort((a, b) => a - b),
	);
}

// ---------------------------------------------------------------------------
// Content record validation
// ---------------------------------------------------------------------------

export interface ContentRecordInput {
	slug?: unknown;
	title?: unknown;
	status?: unknown;
}

export function validateContentRecord(record: ContentRecordInput): {
	ok: boolean;
	error?: string;
} {
	if (typeof record.slug !== "string" || record.slug.trim() === "") {
		return { ok: false, error: "Content record requires a non-empty slug" };
	}
	if (typeof record.title !== "string" || record.title.trim() === "") {
		return { ok: false, error: "Content record requires a non-empty title" };
	}
	// typeof-string alone discriminates null/undefined/numbers from the set.
	if (typeof record.status === "string" && !isContentStatus(record.status)) {
		return { ok: false, error: `Invalid content status: ${record.status}` };
	}
	return { ok: true };
}

// ---------------------------------------------------------------------------
// Audit schema
// ---------------------------------------------------------------------------

/** Column list for the `audit_events` table, in insert order. */
export const auditSchemaFields = [
	"user_email",
	"action",
	"resource_type",
	"resource_id",
	"summary",
	"details",
] as const;

export interface AuditEntryInput {
	actor: { email: string };
	action: string;
	resourceType: string;
	resourceId?: string | null;
	summary: string;
	// audit-boundary: opaque-passthrough -- JSON column passthrough at persistence boundary
	details?: Record<string, unknown> | null;
}

export interface AuditEntryBindings {
	userEmail: string;
	action: string;
	resourceType: string;
	resourceId: string | null;
	summary: string;
	details: string | null;
}

export function buildAuditEntry(input: AuditEntryInput): AuditEntryBindings {
	return {
		userEmail: input.actor.email,
		action: input.action,
		resourceType: input.resourceType,
		resourceId: input.resourceId ?? null,
		summary: input.summary,
		details: input.details ? JSON.stringify(input.details) : null,
	};
}

// ---------------------------------------------------------------------------
// Row → domain mappers
// ---------------------------------------------------------------------------

export interface PersistedOverrideRow {
	title: string;
	status: ContentStatus;
	scheduled_at: string | null;
	body: string | null;
	seo_title: string;
	meta_description: string;
	excerpt: string | null;
	og_title: string | null;
	og_description: string | null;
	og_image: string | null;
	canonical_url_override: string | null;
	robots_directive: string | null;
	/** Optional — only the SQLite schema carries a free-form metadata JSON column. */
	metadata?: string | null;
}

export interface PersistedOverrideRecord extends ContentOverride {
	// audit-boundary: opaque-passthrough -- JSON column passthrough at persistence boundary
	metadata?: Record<string, unknown>;
}

// audit-boundary: opaque-passthrough -- JSON column passthrough at persistence boundary
type ParsedMetadata = Record<string, unknown>;

export function parseMetadataJson(raw: string | null | undefined): ParsedMetadata | undefined {
	let parsed: unknown;
	try {
		parsed = JSON.parse(raw ?? "null");
	} catch {
		return undefined;
	}
	if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
		return undefined;
	}
	// audit-boundary: opaque-passthrough -- JSON column passthrough at persistence boundary
	return parsed as Record<string, unknown>;
}

export function mapPersistedOverrideRow(
	row: PersistedOverrideRow | null | undefined,
): PersistedOverrideRecord | null {
	if (!row) return null;
	const metadata = parseMetadataJson(row.metadata);
	return {
		title: row.title,
		status: row.status,
		scheduledAt: row.scheduled_at ?? undefined,
		body: row.body ?? undefined,
		seoTitle: row.seo_title,
		metaDescription: row.meta_description,
		excerpt: row.excerpt ?? undefined,
		ogTitle: row.og_title ?? undefined,
		ogDescription: row.og_description ?? undefined,
		ogImage: row.og_image ?? undefined,
		canonicalUrlOverride: row.canonical_url_override ?? undefined,
		robotsDirective: row.robots_directive ?? undefined,
		...(metadata ? { metadata } : {}),
	};
}

export interface RedirectRuleInput {
	sourcePath: string;
	targetPath: string;
	statusCode: 301 | 302;
}

export function toRedirectRecord(rule: RedirectRuleInput) {
	return {
		id: rule.sourcePath,
		kind: "redirect" as const,
		slug: rule.sourcePath,
		status: "published" as const,
		title: rule.sourcePath,
		metadata: { targetPath: rule.targetPath, statusCode: rule.statusCode },
	};
}

export interface ContentStoreRecordInput {
	slug: string;
	kind?: string | null;
	title: string;
	body?: string;
	status: ContentStatus;
	seoTitle: string;
	metaDescription: string;
	updatedAt: string;
	legacyUrl: string;
	templateKey: string;
	summary?: string;
}

function mapContentRecordKind(record: { kind?: string | null }): "post" | "page" {
	return record.kind === "post" ? "post" : "page";
}

// ---------------------------------------------------------------------------
// Admin-store list queries (audit events + admin users with pending invites)
// ---------------------------------------------------------------------------
// Both D1 and the local SQLite runtime accept these statements verbatim
// (CURRENT_TIMESTAMP, datetime(), CASE WHEN, EXISTS — all in the shared SQLite
// dialect surface that D1 implements).

export const SQL_LIST_AUDIT_EVENTS = SQL_LIST_AUDIT_EVENTS_DATA;
export const SQL_LIST_ADMIN_USERS_WITH_INVITE = SQL_LIST_ADMIN_USERS_WITH_INVITE_DATA;

export interface PersistedAuditEventRow {
	id: number;
	user_email: string;
	action: string;
	resource_type: string;
	resource_id: string | null;
	summary: string;
	created_at: string;
}

function resolveAuditTargetType(value: string): AuditEvent["targetType"] {
	return AUDIT_TARGET_TYPES.has(value as AuditEvent["targetType"])
		? (value as AuditEvent["targetType"])
		: "auth";
}

/**
 * Map an `audit_events` row to an `AuditEvent`. The `idPrefix` distinguishes
 * the originating store (`d1-audit-` vs `sqlite-audit-`) so concurrent stores
 * never collide on synthesized IDs.
 */
export function mapPersistedAuditEvent(args: {
	row: PersistedAuditEventRow;
	idPrefix: string;
}): AuditEvent {
	const { row, idPrefix } = args;
	return {
		id: `${idPrefix}${row.id}`,
		action: row.action,
		actorEmail: row.user_email,
		actorRole: "admin",
		summary: row.summary,
		targetType: resolveAuditTargetType(row.resource_type),
		targetId: row.resource_id ?? `${row.id}`,
		createdAt: row.created_at,
	};
}

export interface PersistedAdminUserRow {
	id: number;
	email: string;
	role: AdminRole;
	name: string;
	active: number;
	created_at: string;
	has_pending_invite: number;
}

export function deriveAdminUserStatus(
	active: number,
	hasPendingInvite: number,
): ManagedAdminUser["status"] {
	if (active !== 1) return "suspended";
	if (hasPendingInvite === 1) return "invited";
	return "active";
}

export function mapPersistedAdminUserRow(row: PersistedAdminUserRow): ManagedAdminUser {
	return {
		id: row.id,
		email: row.email,
		role: row.role,
		name: row.name,
		active: row.active === 1,
		status: deriveAdminUserStatus(row.active, row.has_pending_invite),
		createdAt: row.created_at,
	};
}

export function toContentStoreRecord(record: ContentStoreRecordInput) {
	return {
		id: record.slug,
		kind: mapContentRecordKind(record),
		slug: record.slug,
		status: record.status === "review" ? "draft" : record.status,
		title: record.title,
		body: record.body ?? null,
		metadata: {
			seoTitle: record.seoTitle,
			metaDescription: record.metaDescription,
			updatedAt: record.updatedAt,
			legacyUrl: record.legacyUrl,
			templateKey: record.templateKey,
			summary: record.summary ?? "",
		},
	};
}

