src/provider-choice.ts.source:
import {
	type AstropressDeploymentSupportLevel,
	getAstropressDeploymentMatrixEntry,
	resolveAstropressDeploymentSupportLevel,
} from "./deployment-matrix";
import type {
	AstropressAppHostEnv,
	AstropressDataServicesEnv,
	AstropressDeployTargetEnv,
} from "./project-env";

export type AstropressProviderOpsComfort = "minimal" | "moderate" | "advanced";
export type AstropressExistingPlatform = "none" | "cloudflare" | "supabase" | "appwrite";

export interface AstropressProviderChoiceInput {
	existingPlatform?: AstropressExistingPlatform;
	wantsHostedAdmin?: boolean;
	wantsStaticMirror?: boolean;
	opsComfort?: AstropressProviderOpsComfort;
}

export interface AstropressProviderChoiceRecommendation {
	appHost: AstropressAppHostEnv;
	dataServices: AstropressDataServicesEnv;
	supportLevel: AstropressDeploymentSupportLevel;
	rationale: string;
	requiredEnvKeys: string[];
	deployTarget: AstropressDeployTargetEnv;
	canonicalProvider: "cloudflare" | "supabase" | "appwrite";
	publicDeployTarget: AstropressDeployTargetEnv;
}

function appHostToDeployTarget(appHost: AstropressAppHostEnv): AstropressDeployTargetEnv {
	return appHost === "cloudflare-pages" ? "cloudflare" : appHost;
}

function finalizeRecommendation(
	appHost: AstropressAppHostEnv,
	dataServices: AstropressDataServicesEnv,
	rationale: string,
): AstropressProviderChoiceRecommendation {
	const entry = getAstropressDeploymentMatrixEntry({ appHost, dataServices });
	const deployTarget = appHostToDeployTarget(appHost);
	return {
		appHost,
		dataServices,
		supportLevel: resolveAstropressDeploymentSupportLevel({
			appHost,
			dataServices,
		}),
		rationale: entry?.notes ? `${rationale} ${entry.notes}` : rationale,
		requiredEnvKeys: entry?.requiredEnvKeys ?? [],
		deployTarget,
		canonicalProvider:
			dataServices === "cloudflare" || dataServices === "supabase" || dataServices === "appwrite"
				? dataServices
				: "cloudflare",
		publicDeployTarget: deployTarget,
	};
}

/**
 * Analyze user preferences and return a recommended provider combination with
 * rationale and required environment keys.
 *
 * @example
 * ```ts
 * import { recommendAstropressProvider } from "@astropress-diy/astropress";
 *
 * const rec = recommendAstropressProvider({ existingPlatform: "supabase" });
 * console.log(rec.appHost);       // "vercel"
 * console.log(rec.dataServices);  // "supabase"
 * console.log(rec.supportLevel);  // "supported"
 * ```
 */
export function recommendAstropressProvider(
	input: AstropressProviderChoiceInput = {},
): AstropressProviderChoiceRecommendation {
	const existingPlatform = input.existingPlatform ?? "none";
	const wantsHostedAdmin = input.wantsHostedAdmin ?? true;
	const wantsStaticMirror = input.wantsStaticMirror ?? false;
	const opsComfort = input.opsComfort ?? "minimal";

	if (existingPlatform === "supabase") {
		return finalizeRecommendation(
			wantsStaticMirror ? "github-pages" : "vercel",
			"supabase",
			"Supabase is already the content-services platform, so Astropress should keep Supabase for data, auth, storage, and the Astropress service API while using a separate Astro app host.",
		);
	}

	if (existingPlatform === "appwrite") {
		return finalizeRecommendation(
			wantsStaticMirror ? "github-pages" : "render-web",
			"appwrite",
			"Appwrite is already the content-services platform, so Astropress should keep Appwrite for data, auth, media, and the Astropress service API while choosing a separate Astro app host.",
		);
	}

	if (existingPlatform === "cloudflare" || opsComfort === "advanced") {
		return finalizeRecommendation(
			wantsStaticMirror ? "github-pages" : "cloudflare-pages",
			"cloudflare",
			"Cloudflare is the best fit for teams already comfortable with its edge/runtime model and wanting one provider to cover app hosting plus content services.",
		);
	}

	if (!wantsHostedAdmin && wantsStaticMirror) {
		return finalizeRecommendation(
			"github-pages",
			"none",
			"GitHub Pages is the clearest low-ops choice when the project only needs static Astro output and no hosted Astropress admin backend.",
		);
	}

	if (!wantsHostedAdmin) {
		return finalizeRecommendation(
			"github-pages",
			"none",
			"A static Astro deployment keeps the public site simple when hosted Astropress services are not required.",
		);
	}

	return finalizeRecommendation(
		"cloudflare-pages",
		"cloudflare",
		"Cloudflare is still the default recommendation for most Astropress users because it keeps the app host and the content-services layer aligned under one operational model.",
	);
}

src/rate-limit-repository-factory.ts.source:
import type { RateLimitRepository } from "./persistence-types";

export interface AstropressRateLimitWindowRecord {
	count: number;
	windowStartMs: number;
	windowMs?: number;
}

export interface AstropressRateLimitRepositoryInput {
	now(): number;
	readRateLimitWindow(key: string): AstropressRateLimitWindowRecord | null | undefined;
	resetRateLimitWindow(key: string, now: number, windowMs: number): void;
	incrementRateLimitWindow(key: string): void;
}

export function createAstropressRateLimitRepository(
	input: AstropressRateLimitRepositoryInput,
): RateLimitRepository {
	return {
		checkRateLimit(key, max, windowMs) {
			const now = input.now();
			const row = input.readRateLimitWindow(key);

			if (!row || now - row.windowStartMs > windowMs) {
				input.resetRateLimitWindow(key, now, windowMs);
				return true;
			}

			if (row.count < max) {
				input.incrementRateLimitWindow(key);
				return true;
			}

			return false;
		},
		peekRateLimit(key, max, windowMs) {
			const now = input.now();
			const row = input.readRateLimitWindow(key);

			if (!row || now - row.windowStartMs > windowMs) {
				return true;
			}

			return row.count < max;
		},
		recordFailedAttempt(key, _max, windowMs) {
			const now = input.now();
			const row = input.readRateLimitWindow(key);

			if (!row || now - row.windowStartMs > windowMs) {
				input.resetRateLimitWindow(key, now, windowMs);
				return;
			}

			input.incrementRateLimitWindow(key);
		},
	};
}

src/runtime-actions-access.ts.source:
/**
 * Runtime helpers backing the /ap-admin/access form actions.
 *
 * Each helper dispatches via `withLocalStoreFallback` to either raw async D1
 * SQL (production) or the sync local sqlite store (dev/test). All writes
 * return `ActionResult<T>` so callers can short-circuit through the
 * `withAdminFormAction` redirect-on-failure flow.
 *
 * Last-admin safeguard: any operation that could lower the active admin
 * count must call `assertNotLastActiveAdmin(locals, targetEmail)` first.
 * The helper inspects `admin_users.is_admin AND active` on the target row
 * and refuses when removing them would leave zero break-glass admins.
 */

import { randomUUID } from "node:crypto";
import type {
	Condition,
	Effect,
	RolePolicyRecord,
	RoleRecord,
	UserPolicyRecord,
} from "./access/index";
import { getAdminDb, withLocalStoreFallback } from "./admin-store-dispatch";
import type { D1DatabaseLike } from "./d1-database";
import type { ActionResult } from "./platform-contracts";

interface AssignRoleInput {
	userId: number;
	roleId: string;
	grantedBy?: string;
}

interface DirectGrantInput {
	userId: number;
	effect: Effect;
	action: string;
	condition?: Condition | null;
	priority?: number;
	grantedBy?: string;
}

export async function assignRuntimeUserRole(
	locals: App.Locals | null | undefined,
	input: AssignRoleInput,
): Promise<ActionResult<{ userId: number; roleId: string }>> {
	return withLocalStoreFallback<ActionResult<{ userId: number; roleId: string }>>(
		locals,
		async (db) => {
			await db
				.prepare(
					"INSERT OR IGNORE INTO access_user_roles (user_id, role_id, granted_by) VALUES (?, ?, ?)",
				)
				.bind(input.userId, input.roleId, input.grantedBy ?? null)
				.run();
			return {
				ok: true as const,
				data: { userId: input.userId, roleId: input.roleId },
			};
		},
		async () => ({
			ok: false as const,
			error:
				"Local admin store does not yet expose access role assignment. Wire the access surface to enable role management in dev.",
		}),
	);
}

export async function revokeRuntimeUserRole(
	locals: App.Locals | null | undefined,
	input: { userId: number; roleId: string },
): Promise<ActionResult<{ userId: number; roleId: string }>> {
	return withLocalStoreFallback<ActionResult<{ userId: number; roleId: string }>>(
		locals,
		async (db) => {
			await db
				.prepare("DELETE FROM access_user_roles WHERE user_id = ? AND role_id = ?")
				.bind(input.userId, input.roleId)
				.run();
			return {
				ok: true as const,
				data: { userId: input.userId, roleId: input.roleId },
			};
		},
		async () => ({
			ok: false as const,
			error:
				"Local admin store does not yet expose access role assignment. Wire the access surface to enable role management in dev.",
		}),
	);
}

export async function addRuntimeUserDirectGrant(
	locals: App.Locals | null | undefined,
	input: DirectGrantInput,
): Promise<ActionResult<UserPolicyRecord>> {
	const id = randomUUID();
	const conditionJson = input.condition ? JSON.stringify(input.condition) : null;
	const priority = input.priority ?? 0;
	return withLocalStoreFallback<ActionResult<UserPolicyRecord>>(
		locals,
		async (db) => {
			await db
				.prepare(
					"INSERT INTO access_user_policies (id, user_id, effect, action, condition_json, priority, granted_by) VALUES (?, ?, ?, ?, ?, ?, ?)",
				)
				.bind(
					id,
					input.userId,
					input.effect,
					input.action,
					conditionJson,
					priority,
					input.grantedBy ?? null,
				)
				.run();
			return {
				ok: true as const,
				data: {
					id,
					userId: input.userId,
					effect: input.effect,
					action: input.action,
					condition: input.condition ?? null,
					priority,
					grantedBy: input.grantedBy ?? null,
				},
			};
		},
		async () => ({
			ok: false as const,
			error: "Local admin store does not yet expose direct user grants.",
		}),
