import { peekCmsConfig } from "../config";
import { buildAuditEntry } from "../persistence-commons";
import type { AstropressSqliteDatabaseLike } from "./utils";

// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
type AuditDetails = Record<string, unknown>;

function parseDetailsJson(value: string | null): AuditDetails | null {
	if (!value) return null;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	return JSON.parse(value) as Record<string, unknown>;
}

export interface AuditEventRecord {
	id: number;
	userEmail: string;
	action: string;
	resourceType: string;
	resourceId: string | null;
	summary: string;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	details: Record<string, unknown> | null;
	createdAt: string;
}

export interface RecordAuditEventInput {
	userEmail: string;
	action: string;
	resourceType: string;
	resourceId?: string | null;
	summary: string;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	details?: Record<string, unknown> | null;
}

export function recordAudit(
	db: AstropressSqliteDatabaseLike,
	actor: { email: string },
	action: string,
	summary: string,
	resourceType: string,
	resourceId: string,
): void {
	recordAuditEvent(db, {
		userEmail: actor.email,
		action,
		resourceType,
		resourceId,
		summary,
	});
}

export function recordAuditEvent(
	db: AstropressSqliteDatabaseLike,
	input: RecordAuditEventInput,
): void {
	const entry = buildAuditEntry({
		actor: { email: input.userEmail },
		action: input.action,
		resourceType: input.resourceType,
		resourceId: input.resourceId,
		summary: input.summary,
		details: input.details,
	});
	db.prepare(
		`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary, details)
     VALUES (?, ?, ?, ?, ?, ?)`,
	).run(
		entry.userEmail,
		entry.action,
		entry.resourceType,
		entry.resourceId,
		entry.summary,
		entry.details,
	);

	const retentionDays = peekCmsConfig()?.auditRetentionDays ?? 90;
	if (retentionDays > 0) {
		db.prepare(
			`DELETE FROM audit_events WHERE created_at < datetime('now', '-' || ? || ' days')`,
		).run(retentionDays);
	}
}

export function listAuditEvents(
	db: AstropressSqliteDatabaseLike,
	options: { limit?: number; offset?: number; resourceId?: string } = {},
): AuditEventRecord[] {
	const limit = options.limit ?? 50;
	const offset = options.offset ?? 0;

	// audit-boundary: opaque-passthrough -- raw rows from driver; mapped below at row-shape boundary
	let rows: unknown[];
	if (options.resourceId) {
		rows = db
			.prepare(
				`SELECT id, user_email, action, resource_type, resource_id, summary, details, created_at
         FROM audit_events
         WHERE resource_id = ?
         ORDER BY created_at DESC
         LIMIT ? OFFSET ?`,
			)
			.all(options.resourceId, limit, offset);
	} else {
		rows = db
			.prepare(
				`SELECT id, user_email, action, resource_type, resource_id, summary, details, created_at
         FROM audit_events
         ORDER BY created_at DESC
         LIMIT ? OFFSET ?`,
			)
			.all(limit, offset);
	}

	return (
		rows as Array<{
			id: number;
			user_email: string;
			action: string;
			resource_type: string;
			resource_id: string | null;
			summary: string;
			details: string | null;
			created_at: string;
		}>
	).map((row) => ({
		id: row.id,
		userEmail: row.user_email,
		action: row.action,
		resourceType: row.resource_type,
		resourceId: row.resource_id,
		summary: row.summary,
		details: parseDetailsJson(row.details),
		createdAt: row.created_at,
	}));
}

src/sqlite-runtime/content-submissions.t.source:
import { createAstropressSubmissionRepository } from "../submission-repository-factory";
import type { AstropressSqliteDatabaseLike } from "./utils";

export function createSqliteSubmissionStore(getDb: () => AstropressSqliteDatabaseLike) {
	function getContactSubmissions() {
		const rows = getDb()
			.prepare(
				"SELECT id, name, email, message, submitted_at FROM contact_submissions ORDER BY datetime(submitted_at) DESC, id DESC",
			)
			.all() as Array<{
			id: string;
			name: string;
			email: string;
			message: string;
			submitted_at: string;
		}>;

		return rows.map((row) => ({
			id: row.id,
			name: row.name,
			email: row.email,
			message: row.message,
			submittedAt: row.submitted_at,
		}));
	}

	const sqliteSubmissionRepository = createAstropressSubmissionRepository({
		getContactSubmissions,
		insertContactSubmission(submission) {
			getDb()
				.prepare(
					"INSERT INTO contact_submissions (id, name, email, message, submitted_at) VALUES (?, ?, ?, ?, ?)",
				)
				.run(
					submission.id,
					submission.name,
					submission.email,
					submission.message,
					submission.submittedAt,
				);
		},
	});

	const sqliteSchedulingRepository = {
		schedulePublish(id: string, scheduledAt: string): void {
			getDb()
				.prepare("UPDATE content_overrides SET scheduled_at = ?, status = 'draft' WHERE slug = ?")
				.run(scheduledAt, id);
			getDb()
				.prepare(
					`INSERT INTO content_overrides (slug, scheduled_at, status, title, seo_title, meta_description, updated_at, updated_by)
           SELECT ce.slug, ?, 'draft', ce.title, ce.title, '', CURRENT_TIMESTAMP, 'scheduler'
           FROM content_entries ce WHERE ce.slug = ?
           AND NOT EXISTS (SELECT 1 FROM content_overrides co WHERE co.slug = ?)`,
				)
				.run(scheduledAt, id, id);
		},

		listScheduled(): Array<{
			id: string;
			slug: string;
			title: string;
			scheduledAt: string;
		}> {
			const now = new Date().toISOString();
			const rows = getDb()
				.prepare(
					`SELECT co.slug AS id, co.slug, COALESCE(co.title, ce.title, co.slug) AS title, co.scheduled_at
           FROM content_overrides co LEFT JOIN content_entries ce ON ce.slug = co.slug
           WHERE co.scheduled_at IS NOT NULL AND co.scheduled_at > ? ORDER BY co.scheduled_at ASC`,
				)
				.all(now) as Array<{
				id: string;
				slug: string;
				title: string;
				scheduled_at: string;
			}>;
			return rows.map((r) => ({
				id: r.slug,
				slug: r.slug,
				title: r.title,
				scheduledAt: r.scheduled_at,
			}));
		},

		cancelScheduledPublish(id: string): void {
			getDb().prepare("UPDATE content_overrides SET scheduled_at = NULL WHERE slug = ?").run(id);
		},

		runScheduledPublishes(): number {
			const now = new Date().toISOString();
			const result = getDb()
				.prepare(
					`UPDATE content_overrides SET status = 'published', scheduled_at = NULL WHERE scheduled_at IS NOT NULL AND scheduled_at <= ?`,
				)
				.run(now);
			return result.changes as number;
		},
	};

	return { sqliteSubmissionRepository, sqliteSchedulingRepository };
}

src/sqlite-runtime/search.ts.source:
import type { ContentRecord } from "../persistence-types";
import type { AstropressSqliteDatabaseLike } from "./utils";

/**
 * Search content_overrides using the FTS5 virtual table.
 * Requires ensureFts5SearchIndex to have been called at boot.
 */
export function searchContentOverrides(
	db: AstropressSqliteDatabaseLike,
	query: string,
): ContentRecord[] {
	return db
		.prepare(
			`SELECT co.* FROM content_overrides co
       WHERE co.rowid IN (SELECT rowid FROM content_fts(?) ORDER BY rank)`,
		)
		.all(query) as ContentRecord[];
}

src/translation-repository-factory.ts.source:
import type { Actor, TranslationRepository } from "./persistence-types";
import {
	normalizeTranslationState,
	type TranslationState,
	translationStates,
} from "./translation-state";

export interface AstropressTranslationRepositoryInput {
	readTranslationState(route: string): string | null | undefined;
	persistTranslationState(route: string, state: TranslationState, actor: Actor): void;
	recordTranslationAudit(input: { actor: Actor; route: string; state: TranslationState }): void;
}

export function createAstropressTranslationRepository(
	input: AstropressTranslationRepositoryInput,
): TranslationRepository {
	return {
		updateTranslationState(route, state, actor) {
			const normalizedState = normalizeTranslationState(state, "__invalid__" as TranslationState);
			if (!(translationStates as readonly string[]).includes(normalizedState)) {
				return {
					ok: false as const,
					error: `Invalid translation state. Must be one of: ${translationStates.join(", ")}`,
				};
			}

			input.persistTranslationState(route, normalizedState, actor);
			input.recordTranslationAudit({
				actor,
				route,
				state: normalizedState,
			});

			return { ok: true as const };
		},
		getEffectiveTranslationState(route, fallback) {
			// normalizeTranslationState's own fallback is "not_started"; pass
			// the caller-supplied fallback through only if provided, otherwise
			// let normalize use its default to avoid an equivalent default-arg
			// string literal.
			const normalized = fallback === undefined ? undefined : normalizeTranslationState(fallback);
			return normalizeTranslationState(input.readTranslationState(route), normalized);
		},
	};
}

src/vite-integration.ts.source:
import {
	type AstropressViteAlias,
	type AstropressVitePlugin,
	type AstropressViteRuntimeAliasOptions,
	createAstropressLocalRuntimeModulePlugin,
	createAstropressPackageResolverPlugin,
	createAstropressViteAliases,
} from "./vite-runtime-alias";

export type AstropressViteIntegration = {
	plugins: AstropressVitePlugin[];
	aliases: AstropressViteAlias[];
};

export function createAstropressViteIntegration(
	options: AstropressViteRuntimeAliasOptions,
): AstropressViteIntegration {
	const plugins: AstropressVitePlugin[] = [
		createAstropressLocalRuntimeModulePlugin(options.localRuntimeModulesPath),
	];
	if (options.astropressPackageRoot) {
		plugins.push(createAstropressPackageResolverPlugin(options.astropressPackageRoot));
	}
	return {
		plugins,
		aliases: createAstropressViteAliases(options),
	};
}

src/webhook-validation.ts.source:
import type { WebhookEvent } from "./platform-contracts";
import { WEBHOOK_EVENTS } from "./webhook-validation-data";

/**
 * Shared validation for webhook creation. Both the admin form action
 * (`pages/ap-admin/actions/webhook-create.ts`) and the token-authenticated
 * REST API (`pages/ap-api/v1/webhooks.ts`) run callers' input through this
 * one layer, so a `webhooks:manage` token can never persist a webhook the
 * admin UI would reject (issue #141). The stored URL is later handed to
 * `fetch()` by the dispatcher, so the scheme check here is the gate that
 * keeps arbitrary callback targets out of the store.
 */

export interface WebhookCreateInput {
	url: string;
	events: WebhookEvent[];
}

export type WebhookValidationResult =
	| { ok: true; value: WebhookCreateInput }
	| { ok: false; error: string };

/** Narrowing guard for a single event name against the canonical allowlist. */
export function isWebhookEvent(value: unknown): value is WebhookEvent {
	return typeof value === "string" && (WEBHOOK_EVENTS as readonly string[]).includes(value);
}

/** Human-readable allowlist for error messages — derived, never hand-typed. */
function supportedEventsList(): string {
	return WEBHOOK_EVENTS.join(", ");
}

/**
 * Validate raw, untrusted webhook-creation input. Returns the normalised
 * `{ url, events }` on success or a single user-facing error string.
 *
 * Invalid/unsupported event names are *rejected*, not silently dropped: a
 * caller asking for an event we do not support is a mistake worth surfacing,
 * and silently persisting a partial subset hides it. The error never echoes
 * the caller's rejected strings back — it lists the supported events instead,
 * so nothing user-controlled is reflected into the admin page or API body.
 */
export function validateWebhookCreateInput(input: {
	url: unknown;
	events: unknown;
}): WebhookValidationResult {
	const url = typeof input.url === "string" ? input.url.trim() : "";
	if (!url) return { ok: false, error: "Webhook URL is required." };
	if (!url.startsWith("https://") && !url.startsWith("http://"))
		return { ok: false, error: "URL must start with http:// or https://" };

	const rawEvents = Array.isArray(input.events) ? input.events : [];
	if (rawEvents.length === 0) return { ok: false, error: "At least one event is required." };

	if (!rawEvents.every(isWebhookEvent))
		return {
			ok: false,
			error: `One or more events are not supported. Valid events: ${supportedEventsList()}.`,
		};

	return { ok: true, value: { url, events: rawEvents as WebhookEvent[] } };
}

