				},
			],
			archives: [
				{
					title: "Blog",
					kind: "posts",
					slug: "blog",
					legacyUrl: "/blog",
					listingItems: [],
				},
			],
			translationStatus: [
				{
					route: "/es/about",
					translationState: "not_started",
					englishSourceUrl: "/about",
					locale: "es",
				},
			],
		});

		// Seed a structured page route for /es/about so localizedEditHref is populated
		const settings = JSON.stringify({
			templateKey: "content",
			alternateLinks: [],
		});
