			createdAt: new Date().toISOString(),
			// No actorId, no summary
			snapshot: {
				// No ogTitle, ogDescription, ogImage, canonicalUrlOverride, robotsDirective, excerpt
				// No scheduledAt, no body (uses ?? null fallbacks)
				// No authorIds, categoryIds, tagIds (uses ?? [] fallbacks)
				title: "Rev Append",
				status: "published",
				seoTitle: "Rev Append",
				metaDescription: "Rev Append",
			} as Parameters<typeof adapter.revisions.append>[0]["snapshot"],
		});
		expect(revision.id).toBe("ra-1");
		db.close();
	});

	it("revisions.append uses record ID as fallback title when title fields are absent from snapshot", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		await adapter.content.save({
			id: "notitle-post",
			kind: "post",
			slug: "notitle-post",
			status: "published",
			title: "Has Title",
		});
		// Snapshot with NO title, NO seoTitle, NO metaDescription → all fall back to revision.recordId
		const revision = await adapter.revisions.append({
			id: "ra-notitle",
			recordId: "notitle-post",
			createdAt: new Date().toISOString(),
			snapshot: {
				status: "published",
				// deliberately omit title, seoTitle, metaDescription
			} as Parameters<typeof adapter.revisions.append>[0]["snapshot"],
		});
		expect(revision.id).toBe("ra-notitle");
		db.close();
	});

	it("content.save page preserves existing title and body when update omits them", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		// First save with title so existing?.title is available
		await adapter.content.save({
			id: "no-title-page",
			kind: "page",
			slug: "no-title-page",
			status: "published",
			title: "Original",
		});
		// Second save WITHOUT title or body → triggers record.title ?? existing?.title ?? slug (arm 0 for record.title)
		const updated = await adapter.content.save({
			id: "no-title-page",
			kind: "page",
			slug: "no-title-page",
			status: "published",
		} as Parameters<typeof adapter.content.save>[0]);
		expect(updated.slug).toBe("no-title-page");
		db.close();
	});

	it("content.save new page uses slug as title when no title is provided", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		// Save a brand-new page WITHOUT title → no existing → existing?.title is undefined → slug used
		const saved = await adapter.content.save({
			id: "slug-only-page",
			kind: "page",
			slug: "slug-only-page",
			status: "published",
		} as Parameters<typeof adapter.content.save>[0]);
		expect(saved.slug).toBe("slug-only-page");
		expect(saved.title).toBe("slug-only-page"); // title fell back to slug
		db.close();
	});

	it("content.save new post stores templateKey from metadata", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const saved = await adapter.content.save({
			id: "post-with-template",
			kind: "post",
			slug: "post-with-template",
			status: "published",
			title: "Templated Post",
			metadata: {
				templateKey: "custom-post-template",
				legacyUrl: "/old/post-with-template",
			},
		});
		expect(saved.slug).toBe("post-with-template");
		db.close();
	});

	it("media.put uses filename as title and empty string for altText when metadata is absent", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		// No metadata at all → asset.metadata?.altText → undefined → ?? "" and asset.metadata?.title → undefined → ?? filename
		const asset = await adapter.media.put({
			id: "bare-meta-asset",
			filename: "bare.png",
			mimeType: "image/png",
		} as Parameters<typeof adapter.media.put>[0]);
		expect(asset.id).toBe("bare-meta-asset");
		// L313: `metadata?.title ?? asset.filename` must fall back to filename when
		// metadata is absent. A `&&` mutant would store "undefined" instead of "bare.png".
		const row = db
			.prepare("SELECT title, alt_text FROM media_assets WHERE id = 'bare-meta-asset'")
			.get() as { title: string; alt_text: string };
		expect(row.title).toBe("bare.png");
		expect(row.alt_text).toBe("");
		db.close();
	});

	it("media.put with null bytes covers the else arm (bytes != null → false)", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		// bytes = null → null != null is false → file_size stored as null
		const asset = await adapter.media.put({
			id: "null-bytes-asset",
			filename: "nullbytes.png",
			mimeType: "image/png",
			bytes: null as unknown as Uint8Array,
		});
		expect(asset.id).toBe("null-bytes-asset");
		db.close();
	});

	it("media.put with actual bytes covers the then arm (bytes != null → true)", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		// bytes is a real Uint8Array → bytes != null is true → file_size = bytes.byteLength
		const bytes = new Uint8Array([0x89, 0x50, 0x4e, 0x47]);
		await adapter.media.put({
			id: "real-bytes-asset",
			filename: "real.png",
			mimeType: "image/png",
			bytes,
			metadata: { altText: "a png", title: "Real Bytes" },
		});
		// media.put returns its input, not the DB row — query directly to verify file_size was stored
		const row = db
			.prepare("SELECT file_size FROM media_assets WHERE id = 'real-bytes-asset'")
			.get() as { file_size: number };
		expect(row.file_size).toBe(4); // Uint8Array([0x89, 0x50, 0x4e, 0x47]).byteLength === 4
		db.close();
	});

	it("media.get uses asset id as title when title is an empty string", async () => {
		const db = makeDb();
		// Insert media asset with empty title directly so asset.title is falsy
		db.prepare(
			`INSERT INTO media_assets (id, source_url, local_path, mime_type, alt_text, title, uploaded_by)
       VALUES (?, 'https://cdn/empty-title.png', '/media/empty-title.png', 'image/png', '', '', 'admin@example.com')`,
		).run("empty-title-media");
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const got = await adapter.media.get("empty-title-media");
		expect(got?.filename).toBe("empty-title-media"); // title is "" → falsy → falls back to id
		db.close();
	});

	it("revisions.list returns empty array for an unknown recordId", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const revisions = await adapter.revisions.list("slug-that-never-existed");
		expect(revisions).toEqual([]);
		expect(revisions.length).toBe(0);
		db.close();
	});
});

describe("cloudflare adapter — surviving mutant coverage (phase-3a lift)", () => {
	it("active user maps to status='published' (kills L176 'published' StringLiteral mutant)", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const users = await adapter.content.list("user");
		const active = users.find((u) => u.metadata?.email === "admin@example.com");
		expect(active).toBeDefined();
		// Strict equality on the exact "published" literal to kill StringLiteral mutants
		// (e.g. "" or "archived") at cloudflare.ts:176:27.
		expect(active?.status).toBe("published");
		db.close();
	});

	it("settings record exposes kind='settings', slug='site-settings', status='published' verbatim", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const settings = await adapter.content.list("settings");
		expect(settings).toHaveLength(1);
		// Strict equality on each string literal in cloudflare.ts:189-194 so
		// StringLiteral mutants ("settings"→"", "site-settings"→"", "published"→"")
		// all fail at least one assertion.
		expect(settings[0].id).toBe("site-settings");
		expect(settings[0].kind).toBe("settings");
		expect(settings[0].slug).toBe("site-settings");
		expect(settings[0].status).toBe("published");
		db.close();
	});

	it("media list entries carry the full metadata object (kills L206 ObjectLiteral)", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const media = await adapter.content.list("media");
		const entry = media.find((m) => m.id === "cloudflare-media-1");
		expect(entry).toBeDefined();
		// Empty-object mutant ({}) at L206 would drop every metadata field below.
		expect(entry?.metadata?.sourceUrl).toBe("https://cdn.example.com/cloudflare.png");
		expect(entry?.metadata?.localPath).toBe("/media/cloudflare.png");
		expect(entry?.metadata?.mimeType).toBe("image/png");
		expect(entry?.metadata?.altText).toBe("Cloudflare alt");
		expect(typeof entry?.metadata?.uploadedAt).toBe("string");
		db.close();
	});

	it("comment with non-null submittedAt preserves the value (kills L165 LogicalOperator ??→&&)", async () => {
		const db = await createSeededCloudflareDatabase();
		db.prepare(
			`INSERT INTO comments (id, route, author, email, body, status, policy, submitted_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		).run(
			"comment-submitted",
			"/post",
			"Carol",
			"carol@example.com",
			"Has submitted_at",
			"approved",
			"open-moderated",
			"2026-02-03T04:05:06.000Z",
		);
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const comments = await adapter.content.list("comment");
		const c = comments.find((x) => x.id === "comment-submitted");
		// With ?? : truthy submittedAt is preserved as-is.
		// With && : the operator short-circuits to null whenever submittedAt is truthy
		// (truthy && null → null), so a stored timestamp would surface as null.
		expect(c?.metadata?.submittedAt).toBe("2026-02-03T04:05:06.000Z");
		db.close();
	});

	it("content.get matches a user record by id OR by slug (kills L279 LogicalOperator/Conditional mutants)", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const users = await adapter.content.list("user");
		const u = users.find((x) => x.metadata?.email === "admin@example.com");
		expect(u).toBeDefined();
		const idStr = u?.id as string;
		const slug = u?.slug as string;
		// id and slug differ for user records (id = numeric pk string, slug = email).
		expect(idStr).not.toBe(slug);

		// `find((r) => r.id === normalizedId || r.slug === normalizedId)`:
		// matching by id only is observable distinct from matching by slug only,
		// so a `||→&&` mutant or either conditional-flipped mutant fails one path.
		const byId = await adapter.content.get(idStr);
		expect(byId?.id).toBe(idStr);
		expect(byId?.slug).toBe(slug);

		const bySlug = await adapter.content.get(slug);
		expect(bySlug?.id).toBe(idStr);
		expect(bySlug?.slug).toBe(slug);
		db.close();
	});

	it("content.get trims whitespace around the id (kills L275 MethodExpression .trim removal)", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		// "  admin@example.com  " must trim to a real slug match.
		// Without .trim(), find() would compare " admin@example.com " to "admin@example.com" → no match → null.
		const got = await adapter.content.get("  admin@example.com  ");
		expect(got).not.toBeNull();
		expect(got?.slug).toBe("admin@example.com");
		db.close();
	});

	it("content.delete archives a page record (kills L292 'page' StringLiteral mutant)", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		await adapter.content.save({
			id: "delete-me-page",
			kind: "page",
			slug: "delete-me-page",
			status: "published",
			title: "Page To Delete",
		});
		await adapter.content.delete("delete-me-page");
		const after = await adapter.content.get("delete-me-page");
		// With "page"→"" mutant, the page would fall through to no-op → status stays "published".
		expect(after?.status).toBe("archived");
		db.close();
	});

	it("media.put stores '/media/<filename>' local_path when publicUrl is absent (kills L309 StringLiteral)", async () => {
		const db = makeDb();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		await adapter.media.put({
			id: "no-url-readback",
			filename: "no-url.png",
			mimeType: "image/png",
			metadata: { altText: "x", title: "x" },
		} as Parameters<typeof adapter.media.put>[0]);
		const row = db
			.prepare("SELECT local_path, source_url FROM media_assets WHERE id = 'no-url-readback'")
			.get() as { local_path: string; source_url: string | null };
		// L308: source_url = publicUrl ?? null → null. L309: local_path = publicUrl ?? `/media/${filename}` → "/media/no-url.png".
		// A "/media/" → "" mutant would store "no-url.png" without the prefix.
		expect(row.source_url).toBeNull();
		expect(row.local_path).toBe("/media/no-url.png");
		db.close();
	});
});

describe("cloudflare adapter — session expiry", () => {
	it("returns null session when last_active_at is not a parseable date", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Create a real session
		const session = await adapter.auth.signIn("admin@example.com", "password");
		expect(session).not.toBeNull();

		// Corrupt last_active_at to a non-parseable string.
		// Lexicographically > any ISO date, so SQL cleanup skips it.
		// Date.parse() returns NaN → hits the !Number.isFinite() branch.
		db.prepare(
			"UPDATE admin_sessions SET last_active_at = 'not-a-date' WHERE revoked_at IS NULL",
		).run();

		expect(await adapter.auth.getSession(session?.id)).toBeNull();
		db.close();
	});

	it("returns null for a session whose last_active_at is older than 12 hours", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Sign in to get a real session
		const session = await adapter.auth.signIn("admin@example.com", "password");
		expect(session).not.toBeNull();

		// Backdate the session's last_active_at so it appears expired
		db.prepare(
			"UPDATE admin_sessions SET last_active_at = datetime('now', '-13 hours') WHERE revoked_at IS NULL",
		).run();

		// getSession should now return null (expired session)
		expect(await adapter.auth.getSession(session?.id)).toBeNull();

		db.close();
	});
});

