			db,
		);
		const row = db
			.prepare("SELECT target_path, status_code FROM redirect_rules WHERE source_path = '/old'")
			.get() as { target_path: string; status_code: number };
		expect(row.target_path).toBe("/v2");
		expect(row.status_code).toBe(302);
	});
});

