	it("nulls missing details", () => {
		const entry = buildAuditEntry({
			actor: { email: "e@example.com" },
			action: "x",
			resourceType: "y",
			summary: "z",
		});
		expect(entry.details).toBeNull();
	});
	it("nulls explicit-null details", () => {
		const entry = buildAuditEntry({
			actor: { email: "e@example.com" },
			action: "x",
			resourceType: "y",
			summary: "z",
			details: null,
		});
