describe("requestOptedOutOfTracking", () => {
	function makeRequest(headers: Record<string, string> = {}) {
		return new Request("https://example.com/", { headers });
	}

	it("returns false when neither DNT nor Sec-GPC is set", () => {
		expect(requestOptedOutOfTracking(makeRequest())).toBe(false);
	});

	it("returns true when DNT: 1 is set", () => {
		expect(requestOptedOutOfTracking(makeRequest({ DNT: "1" }))).toBe(true);
	});

	it("returns true when Sec-GPC: 1 is set", () => {
		expect(requestOptedOutOfTracking(makeRequest({ "Sec-GPC": "1" }))).toBe(true);
	});

	it("returns false when DNT is 0", () => {
		expect(requestOptedOutOfTracking(makeRequest({ DNT: "0" }))).toBe(false);
	});
});

describe("resolveAnalyticsSnippetConsentAware", () => {
	function makeRequest(headers: Record<string, string> = {}) {
		return new Request("https://example.com/", { headers });
	}

	const umamiConfig: AnalyticsConfig = {
		type: "umami",
		mode: "snippet",
		snippetSrc: "https://analytics.example.com/script.js",
		siteId: "test-site-id",
	};

	it("returns snippet when no opt-out header", () => {
		const snippet = resolveAnalyticsSnippetConsentAware(umamiConfig, makeRequest());
		expect(snippet).toContain("analytics.example.com");
	});

	it("returns empty string when DNT: 1", () => {
		const snippet = resolveAnalyticsSnippetConsentAware(umamiConfig, makeRequest({ DNT: "1" }));
		expect(snippet).toBe("");
	});

	it("returns empty string when Sec-GPC: 1", () => {
		const snippet = resolveAnalyticsSnippetConsentAware(
			umamiConfig,
			makeRequest({ "Sec-GPC": "1" }),
		);
		expect(snippet).toBe("");
	});

	it("returns empty string when config is null", () => {
		const snippet = resolveAnalyticsSnippetConsentAware(null, makeRequest());
		expect(snippet).toBe("");
	});
});

describe("localeFromAcceptLanguage", () => {
	it("returns first locale when Accept-Language is null (no config registered)", () => {
		// No registerCms() call — should fall back to ["en","es"] default
		expect(localeFromAcceptLanguage(null)).toBe("en");
	});

	it("matches exact locale tag", () => {
		expect(localeFromAcceptLanguage("es")).toBe("es");
	});

	it("matches language prefix (fr-CH → 'en' when only en/es configured)", () => {
		expect(localeFromAcceptLanguage("fr-CH, fr;q=0.9, en;q=0.8")).toBe("en");
	});

	it("respects q-weight ordering — picks higher quality value first", () => {
		expect(localeFromAcceptLanguage("en;q=0.5, es;q=0.9")).toBe("es");
	});

	it("returns first configured locale when no tag matches", () => {
		expect(localeFromAcceptLanguage("zh, ja")).toBe("en");
	});

	it("matches region-qualified tag (es-MX) against 'es' locale", () => {
		expect(localeFromAcceptLanguage("es-MX")).toBe("es");
	});
});

describe("resolveAnalyticsSnippet", () => {
	it("returns empty string for null/undefined config", () => {
		expect(resolveAnalyticsSnippet(null)).toBe("");
		expect(resolveAnalyticsSnippet(undefined)).toBe("");
	});

	it("umami: produces script tag with data-website-id", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "umami",
			mode: "snippet-only",
			snippetSrc: "https://analytics.example.com/script.js",
			siteId: "abc-123",
		});
		expect(snippet).toContain("<script");
		expect(snippet).toContain('data-website-id="abc-123"');
		expect(snippet).toContain('src="https://analytics.example.com/script.js"');
	});

	it("plausible: produces script tag with data-domain", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "plausible",
			mode: "snippet-only",
			snippetSrc: "https://plausible.io/js/script.js",
			siteId: "example.com",
		});
		expect(snippet).toContain('data-domain="example.com"');
		expect(snippet).toContain('src="https://plausible.io/js/script.js"');
	});

	it("matomo: produces tracker script with site ID (url with trailing slash)", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "matomo",
			mode: "snippet-only",
			url: "https://matomo.example.com/",
			siteId: "5",
		});
		expect(snippet).toContain("matomo.php");
		expect(snippet).toContain("'5'");
		expect(snippet).toContain("matomo.example.com");
	});

	it("matomo: appends trailing slash when url lacks one", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "matomo",
			mode: "snippet-only",
			url: "https://matomo.example.com",
			siteId: "7",
		});
		expect(snippet).toContain("matomo.example.com/");
		expect(snippet).toContain("'7'");
	});

	it("posthog: produces posthog init script", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "posthog",
			mode: "snippet-only",
			snippetSrc: "https://app.posthog.com",
			siteId: "phc_testkey",
		});
		expect(snippet).toContain("posthog.init");
		expect(snippet).toContain("phc_testkey");
	});

	it("custom: passes snippet through as-is", () => {
		const custom = "<script>window.myAnalytics = true;</script>";
		const snippet = resolveAnalyticsSnippet({
			type: "custom",
			mode: "snippet-only",
			snippetSrc: custom,
		});
		expect(snippet).toBe(custom);
	});

	it("umami: returns empty string when siteId is missing", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "umami",
			mode: "snippet-only",
			snippetSrc: "https://analytics.example.com/script.js",
		});
		expect(snippet).toBe("");
	});

	it("HTML-encodes attribute values to prevent XSS (non-custom types)", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "umami",
			mode: "snippet-only",
			snippetSrc: "https://example.com/script.js",
			siteId: 'abc"<>',
		});
		expect(snippet).not.toContain('"<>');
		expect(snippet).toContain("&quot;&lt;&gt;");
	});

	it("umami: returns empty string when snippetSrc is missing", () => {
		expect(
			resolveAnalyticsSnippet({
				type: "umami",
				mode: "snippet-only",
				siteId: "abc-123",
			}),
		).toBe("");
	});

	it("plausible: returns empty string when snippetSrc is missing", () => {
		expect(
			resolveAnalyticsSnippet({
				type: "plausible",
				mode: "snippet-only",
				siteId: "example.com",
			}),
		).toBe("");
	});

	it("plausible: returns empty string when siteId is missing", () => {
		expect(
			resolveAnalyticsSnippet({
				type: "plausible",
				mode: "snippet-only",
				snippetSrc: "https://plausible.io/js/script.js",
			}),
		).toBe("");
	});

	it("posthog: returns empty string when snippetSrc is missing", () => {
		expect(
			resolveAnalyticsSnippet({
				type: "posthog",
				mode: "snippet-only",
				siteId: "phc_key",
			}),
		).toBe("");
	});

	it("matomo: returns empty string when url is missing", () => {
		expect(
			resolveAnalyticsSnippet({
				type: "matomo",
				mode: "snippet-only",
				siteId: "5",
			}),
		).toBe("");
	});

	it("custom: returns empty string when snippetSrc is absent", () => {
		expect(resolveAnalyticsSnippet({ type: "custom", mode: "snippet-only" })).toBe("");
	});

	it("unknown type falls through to default and returns empty string", () => {
		// Defensive branch for forward-compatible configs from a newer schema version
		expect(
			resolveAnalyticsSnippet({
				type: "unknown-future-type" as never,
				mode: "link",
			}),
		).toBe("");
	});

	it("matomo: snippet contains all expected script lines + newline join", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "matomo",
			mode: "snippet-only",
			url: "https://stats.example.com",
			siteId: "5",
		});
		expect(snippet).toContain("<script>");
		expect(snippet).toContain("var _paq = window._paq");
		expect(snippet).toContain("_paq.push(['trackPageView']);");
		expect(snippet).toContain("_paq.push(['enableLinkTracking']);");
		expect(snippet).toContain("(function() {");
		expect(snippet).toContain("g.async=true");
		expect(snippet).toContain("matomo.js");
		expect(snippet).toContain("})();");
		expect(snippet).toContain("</script>");
		expect(snippet).toContain("\n");
	});

	it("matomo: snippet contains the document-script discovery line (pins L38 StringLiteral)", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "matomo",
			mode: "snippet-only",
			url: "https://stats.example.com",
			siteId: "5",
		});
		// Pins the L38 'var d=document, g=d.createElement(...)' line — the
		// bootstrap that finds an existing <script> for insertBefore.
		expect(snippet).toContain("var d=document");
		expect(snippet).toContain("d.createElement('script')");
		expect(snippet).toContain("d.getElementsByTagName('script')[0]");
	});

	it("posthog: snippet contains every line of the IIFE bootstrap and joins them with newlines (pins L48-L53 + L56 join)", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "posthog",
			mode: "snippet-only",
			snippetSrc: "https://app.posthog.com",
			siteId: "phc_key",
			url: "https://us.posthog.com",
		});
		// One distinguishing substring per generator line. Each StringLiteral
		// mutation would replace the entire line with '' — losing the substring.
		expect(snippet).toContain("e.__SV||(window.posthog=e,e._i=[]");
		expect(snippet).toContain('"2==o.length"'.replace(/"/g, "") || "2==o.length"); // L49
		expect(snippet).toContain('p.async=!0,p.src=s.api_host+"/static/array.js"');
		expect(snippet).toContain(
			'(r=t.getElementsByTagName("script")[0]).parentNode.insertBefore(p,r)',
		);
		expect(snippet).toContain("getActiveMatchingSurveys");
		expect(snippet).toContain("e._i.push([i,s,a])");
		// Pins L56 join("\\n") — both opening <script> and ! function ... lines
		// must be separated by a real newline, not concatenated.
		expect(snippet).toMatch(/<script>\n!function/);
	});

	it("posthog: default api_host is https://app.posthog.com when url is omitted (pins L54 StringLiteral default)", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "posthog",
			mode: "snippet-only",
			snippetSrc: "https://app.posthog.com",
			siteId: "phc_key",
		});
		expect(snippet).toContain("api_host:'https://app.posthog.com'");
	});

	it("escAttr converts & to &amp; in HTML attributes (pins L107 StringLiteral)", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "umami",
			mode: "snippet-only",
			snippetSrc: "https://example.com/script.js?a=1&b=2",
			siteId: "abc",
		});
		// The snippetSrc contains an `&`; escAttr must emit `&amp;` so the
		// resulting HTML attribute is valid.
		expect(snippet).toContain("a=1&amp;b=2");
		expect(snippet).not.toMatch(/a=1&b=2(?!a)/);
	});

	it("escJs escapes backslash, apostrophe, and newline inside posthog init (pins L115 StringLiteral chain)", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "posthog",
			mode: "snippet-only",
			snippetSrc: "https://app.posthog.com",
			// Embedded backslash, apostrophe, and newline — each escape chains
			// through escJs and the mutated chain would let one of them through.
			siteId: "phc\\test'one\ntwo",
		});
		// Backslash → double backslash; apostrophe → \'; newline → \n.
		expect(snippet).toContain("phc\\\\test\\'one\\ntwo");
	});

	it("posthog: snippet contains all expected script lines", () => {
		const snippet = resolveAnalyticsSnippet({
			type: "posthog",
			mode: "snippet-only",
			snippetSrc: "https://app.posthog.com",
			siteId: "ph_test",
			url: "https://app.posthog.com",
		});
		expect(snippet).toContain("<script>");
		expect(snippet).toContain("window.posthog");
		expect(snippet).toContain("posthog.init");
		expect(snippet).toContain("ph_test");
		expect(snippet).toContain("api_host");
		expect(snippet).toContain("</script>");
	});
});

