	it("converts consent boolean to 1/0 numeric for SQLite", () => {
		expect(testimonialInputBindParams("t-1", baseInput)[8]).toBe(1);
		expect(
			testimonialInputBindParams("t-2", {
				...baseInput,
				consentToPublish: false,
