/**
 * Privacy invariant tests — structural checks that enforce Astropress's privacy-by-design
 * properties at the code level. These tests catch changes that would violate GDPR Article 25
 * (data protection by design and by default) or the California Consumer Privacy Act (CCPA).
 *
 * The philosophy: if PII is never stored in recoverable form, GDPR obligations (right of
 * access, right to erasure, data portability) become trivially satisfiable. These tests
 * enforce the architectural choices that make compliance tooling unnecessary.
 */

import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { findRepoRoot } from "./_helpers/repo-root";

// Source-text invariants — read canonical repo source, not the Stryker-instrumented
// sandbox copy.
const srcRoot = path.join(findRepoRoot(), "packages/astropress/src");
const schemaPath = path.resolve(srcRoot, "sqlite-schema.sql");
const bootstrapPath = path.resolve(srcRoot, "sqlite-bootstrap.ts");
const securityMiddlewarePath = path.resolve(srcRoot, "security-middleware.ts");
const analyticsPath = path.resolve(srcRoot, "analytics.ts");

const schema = readFileSync(schemaPath, "utf8");
const bootstrap = readFileSync(bootstrapPath, "utf8");
const securityMiddleware = readFileSync(securityMiddlewarePath, "utf8");

// ---------------------------------------------------------------------------
// Schema invariants
// ---------------------------------------------------------------------------

describe("schema privacy invariants", () => {
	it("comments table does not store IP addresses", () => {
		// Extract just the comments table definition
		const commentsTable =
			schema.match(/CREATE TABLE IF NOT EXISTS comments \([\s\S]*?\);/)?.[0] ?? "";
		expect(commentsTable, "comments table must not have an ip_address column").not.toMatch(
			/ip_address/i,
		);
		expect(commentsTable, "comments table must not have an ip_addr column").not.toMatch(
			/\bip_addr\b/i,
		);
		expect(commentsTable, "comments table must not have a submitter_ip column").not.toMatch(
			/submitter_ip/i,
		);
	});

	it("contact_submissions table does not store IP addresses", () => {
		const contactTable =
			schema.match(/CREATE TABLE IF NOT EXISTS contact_submissions \([\s\S]*?\);/)?.[0] ?? "";
		expect(contactTable, "contact_submissions must not store IP addresses").not.toMatch(
			/ip_address|ip_addr|submitter_ip/i,
		);
	});

	it("admin_sessions IP and user-agent columns are nullable (opt-in, not required)", () => {
		const sessionsTable =
			schema.match(/CREATE TABLE IF NOT EXISTS admin_sessions \([\s\S]*?\);/)?.[0] ?? "";
		// ip_address and user_agent may exist only if they are nullable (no NOT NULL constraint)
		if (sessionsTable.includes("ip_address")) {
			expect(
				sessionsTable,
				"admin_sessions.ip_address must be nullable — it is opt-in session metadata, not required PII",
			).not.toMatch(/ip_address\s+TEXT\s+NOT NULL/i);
		}
		if (sessionsTable.includes("user_agent")) {
			expect(
				sessionsTable,
				"admin_sessions.user_agent must be nullable — it is opt-in session metadata, not required PII",
			).not.toMatch(/user_agent\s+TEXT\s+NOT NULL/i);
		}
	});

	it("api_tokens are hashed at rest", () => {
		const apiTokensTable =
			schema.match(/CREATE TABLE IF NOT EXISTS api_tokens \([\s\S]*?\);/)?.[0] ?? "";
		// Raw token must not be stored — only the hash
		expect(apiTokensTable, "api_tokens must store token_hash, not raw token").toContain(
			"token_hash",
		);
		expect(apiTokensTable, "api_tokens must not have a raw_token column").not.toMatch(
			/\braw_token\b/i,
		);
		expect(apiTokensTable, "api_tokens must not have a token_value column").not.toMatch(
			/\btoken_value\b/i,
		);
		expect(
			apiTokensTable,
			"api_tokens must not have a plain token column without hash suffix",
		).not.toMatch(/\btoken\s+TEXT/i);
	});

	it("webhook secrets are hashed at rest", () => {
		const webhooksTable =
			schema.match(/CREATE TABLE IF NOT EXISTS webhooks \([\s\S]*?\);/)?.[0] ?? "";
		// As documented in the schema comment, secret is stored under secret_hash for backwards compat
		expect(
			webhooksTable,
			"webhooks must not expose a plaintext secret column named 'secret' without indication of hashing",
		).not.toMatch(/\bsecret\s+TEXT\s+NOT NULL/);
	});

	it("password hashes — no plaintext password columns in any table", () => {
		// Find all column definitions that look like they store passwords in plain text
		const suspiciousColumns = schema.match(/\bpassword\s+TEXT\b/gi) ?? [];
		expect(
			suspiciousColumns,
			"No table should have a plain 'password TEXT' column — passwords must be hashed (use password_hash)",
		).toHaveLength(0);
	});

	it("no new tables introduce ip_address as NOT NULL", () => {
		// Any new table that stores IP addresses must make them nullable (opt-in)
		const notNullIp = schema.match(/ip_address\s+TEXT\s+NOT\s+NULL/gi) ?? [];
		expect(
			notNullIp,
			"IP address columns must be nullable — IP logging is opt-in, not required",
		).toHaveLength(0);
	});
});

// ---------------------------------------------------------------------------
// Analytics: must be opt-in only
// ---------------------------------------------------------------------------

describe("analytics privacy invariants", () => {
	it("analytics module does not auto-inject scripts without explicit operator opt-in", () => {
		const analytics = readFileSync(analyticsPath, "utf8");

		// The analytics module must not unconditionally inject script tags or import remote scripts
		// It must check a config or feature flag before doing anything
		expect(
			analytics,
			"analytics.ts must check a config flag before injecting scripts — analytics must be opt-in",
		).not.toMatch(/new\s+URL\s*\(\s*["']https?:/);

		// Must not reference any hardcoded third-party analytics domains as unconditional imports
		const thirdPartyAnalytics = [
			"google-analytics.com",
			"googletagmanager.com",
			"mixpanel.com",
			"amplitude.com",
			"heap.io",
		];
		for (const domain of thirdPartyAnalytics) {
			expect(analytics, `analytics.ts must not unconditionally reference ${domain}`).not.toContain(
				domain,
			);
		}
	});

	it("security middleware does not inject analytics scripts on public pages without consent check", () => {
		// The security middleware runs on every request. If it injects analytics, it must be
		// gated behind an explicit operator configuration check, not unconditional.
		const analyticsKeywords = ["gtag(", "ga('send", "_gaq.push", "fbq('track"];
		for (const keyword of analyticsKeywords) {
			expect(
				securityMiddleware,
				`security-middleware.ts must not inject ${keyword} — that belongs in an opt-in analytics component`,
			).not.toContain(keyword);
		}
	});
});

// ---------------------------------------------------------------------------
// Third-party scripts: public pages must not load external tracking
// ---------------------------------------------------------------------------

describe("third-party script invariants", () => {
	it("security middleware does not set headers that load third-party tracking pixels", () => {
		// Tracking pixels loaded via Link: preload or similar would bypass CSP review
		expect(
			securityMiddleware,
			"security-middleware must not add tracking pixel Link headers",
		).not.toMatch(/Link.*\.(gif|png|jpg)\?.*tracking/i);
	});

	it("security headers do not allowlist known tracking domains in CSP", () => {
		const securityHeaders = readFileSync(path.resolve(srcRoot, "security-headers.ts"), "utf8");
		const trackingDomains = [
			"google-analytics.com",
			"googletagmanager.com",
			"connect.facebook.net",
			"platform.twitter.com",
			"snap.licdn.com",
		];
		for (const domain of trackingDomains) {
			expect(
				securityHeaders,
				`security-headers.ts must not allowlist ${domain} in default CSP — tracking scripts must be opt-in`,
			).not.toContain(domain);
		}
	});
});

// ---------------------------------------------------------------------------
// Data minimization: no unnecessary PII fields should be added to public-facing forms
// ---------------------------------------------------------------------------

describe("data minimization invariants", () => {
	it("comment submission does not collect phone numbers or physical addresses", () => {
		const commentTable =
			schema.match(/CREATE TABLE IF NOT EXISTS comments \([\s\S]*?\);/)?.[0] ?? "";
		expect(commentTable, "comments table must not collect phone numbers").not.toMatch(
			/\bphone\b|\btel\b|\bmobile\b/i,
		);
		expect(commentTable, "comments table must not collect physical addresses").not.toMatch(
			/\baddress\b|\bpostcode\b|\bzip\b/i,
		);
	});

	it("contact_submissions does not collect phone numbers or physical addresses", () => {
		const contactTable =
			schema.match(/CREATE TABLE IF NOT EXISTS contact_submissions \([\s\S]*?\);/)?.[0] ?? "";
		expect(contactTable, "contact_submissions must not collect phone numbers").not.toMatch(
			/\bphone\b|\btel\b|\bmobile\b/i,
		);
		expect(contactTable, "contact_submissions must not collect physical addresses").not.toMatch(
			/\baddress\b|\bpostcode\b|\bzip\b/i,
		);
	});

	it("bootstrap seeder does not log email addresses to stdout or console", () => {
		// Logging PII to stdout risks leaking it into log aggregators
		const emailLogPattern = /console\.(log|info|warn|error)\s*\([^)]*email[^)]*\)/i;
		expect(
			bootstrap,
			"sqlite-bootstrap.ts must not log email addresses via console — use structured logger with PII redaction",
		).not.toMatch(emailLogPattern);
	});
});

// ---------------------------------------------------------------------------
// Session security: sessions must be revocable and time-limited
// ---------------------------------------------------------------------------

describe("session security invariants", () => {
	it("admin_sessions table has a revoked_at column for server-side revocation", () => {
		const sessionsTable =
			schema.match(/CREATE TABLE IF NOT EXISTS admin_sessions \([\s\S]*?\);/)?.[0] ?? "";
		expect(
			sessionsTable,
			"admin_sessions must support server-side revocation via revoked_at",
		).toContain("revoked_at");
	});

	it("admin_sessions table has a last_active_at column for TTL enforcement", () => {
		const sessionsTable =
			schema.match(/CREATE TABLE IF NOT EXISTS admin_sessions \([\s\S]*?\);/)?.[0] ?? "";
		expect(sessionsTable, "admin_sessions must track last_active_at for TTL enforcement").toContain(
			"last_active_at",
		);
	});

	it("session store enforces TTL on getSessionUser", () => {
		const authStore = readFileSync(path.resolve(srcRoot, "sqlite-runtime/auth.ts"), "utf8");
		expect(
			authStore,
			"getSessionUser must check TTL — sessions must expire, not be held indefinitely",
		).toMatch(/last_active_at|ttl|expires|expired/i);
	});
});

// ---------------------------------------------------------------------------
// Right-to-erasure readiness: deletions must cascade
// ---------------------------------------------------------------------------

describe("right-to-erasure schema readiness", () => {
	it("admin_sessions deletes cascade when admin_user is deleted", () => {
		const sessionsTable =
			schema.match(/CREATE TABLE IF NOT EXISTS admin_sessions \([\s\S]*?\);/)?.[0] ?? "";
		expect(
			sessionsTable,
			"admin_sessions must CASCADE on user deletion — deleting a user must also delete their sessions",
		).toMatch(/ON DELETE CASCADE/i);
	});

	it("content_revisions deletes cascade when content_overrides is deleted", () => {
		const revisionsTable =
			schema.match(/CREATE TABLE IF NOT EXISTS content_revisions \([\s\S]*?\);/)?.[0] ?? "";
		expect(revisionsTable, "content_revisions must CASCADE on content deletion").toMatch(
			/ON DELETE CASCADE/i,
		);
	});
});

// ---------------------------------------------------------------------------
// Email hashing: comment author emails must be hashed before storage
// ---------------------------------------------------------------------------

import { vi } from "vitest";
import {
	createAstropressCommentRepository,
	hashCommentEmail,
} from "../src/comment-repository-factory";

describe("comment author email hashing", () => {
	it("hashCommentEmail produces a 64-char KMAC256 hex digest", async () => {
		const digest = await hashCommentEmail("author@example.com", "test-salt");
		expect(digest).toMatch(/^[a-f0-9]{64}$/);
	});

	it("hashCommentEmail is deterministic for the same email and salt", async () => {
		const a = await hashCommentEmail("author@example.com", "my-salt");
		const b = await hashCommentEmail("author@example.com", "my-salt");
		expect(a).toBe(b);
	});

	it("hashCommentEmail produces different digests for different emails", async () => {
		const a = await hashCommentEmail("alice@example.com", "salt");
		const b = await hashCommentEmail("bob@example.com", "salt");
		expect(a).not.toBe(b);
	});

	it("hashCommentEmail produces different digests for different salts", async () => {
		const a = await hashCommentEmail("author@example.com", "salt1");
		const b = await hashCommentEmail("author@example.com", "salt2");
		expect(a).not.toBe(b);
	});

	it("submitPublicComment stores a hashed email (64-char hex) when sessionSalt is provided", async () => {
		const insertedComments: Array<{ email?: string }> = [];
		const repository = createAstropressCommentRepository({
			getComments: vi.fn(() => []),
			getCommentRoute: vi.fn(() => null),
			updateCommentStatus: vi.fn(() => true),
			insertPublicComment: vi.fn((c) => {
				insertedComments.push({ email: c.email });
				return new Date().toISOString();
			}),
			recordCommentAudit: vi.fn(),
			sessionSalt: "site-secret-salt",
		});

		const result = await repository.submitPublicComment({
			author: "Alice",
			email: "alice@example.com",
			body: "Great post",
			route: "/blog/hello",
			submittedAt: new Date().toISOString(),
		});

		expect(result.ok).toBe(true);
		// The stored email must be a deterministic keyed digest, never the raw address
		expect(insertedComments[0]?.email).toMatch(/^[a-f0-9]{64}$/);
		expect(insertedComments[0]?.email).not.toContain("alice");
	});

	it("schema has no column named author_email_plain (no plaintext email column)", () => {
		expect(schema).not.toMatch(/author_email_plain/i);
	});
});

tests/runtime-actions-users-extra.test.t.source:
// Extra coverage for runtime-actions-users.ts beyond the smoke tests in
// runtime-actions-users.test.ts: audit-event content, exact error strings,
// regex boundaries on the email validator, ttl arithmetic on the invite
// expiry, and the local-store fallback wiring for every export.
import type { DatabaseSync } from "node:sqlite";
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { registerCms } from "../src/config";
import {
	consumeRuntimeInviteToken,
	createRuntimePasswordResetToken,
	getRuntimeInviteRequest,
	inviteRuntimeAdminUser,
	suspendRuntimeAdminUser,
	unsuspendRuntimeAdminUser,
} from "../src/runtime-actions-users.js";
import { makeDb, STANDARD_ACTOR, STANDARD_CMS_CONFIG } from "./helpers/make-db.js";
import { makeLocals } from "./helpers/make-locals.js";

const { fakeLocalStore, mockLoadLocalAdminStore } = vi.hoisted(() => ({
	fakeLocalStore: {
		inviteAdminUser: vi.fn(),
		getInviteRequest: vi.fn(),
		consumeInviteToken: vi.fn(),
		suspendAdminUser: vi.fn(),
		unsuspendAdminUser: vi.fn(),
		createPasswordResetToken: vi.fn(),
	},
	mockLoadLocalAdminStore: vi.fn(),
}));

vi.mock("../src/local-runtime-modules", () => ({
	loadLocalAdminStore: mockLoadLocalAdminStore,
}));
vi.mock("../src/local-runtime-modules.js", () => ({
	loadLocalAdminStore: mockLoadLocalAdminStore,
}));

const actor = STANDARD_ACTOR;
let db: DatabaseSync;
let locals: App.Locals;

beforeEach(() => {
	db = makeDb();
	locals = makeLocals(db);
	registerCms(STANDARD_CMS_CONFIG);
	db.prepare(
		"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?, ?, ?, 1, 1)",
	).run("admin@test.local", "hash", "Test Admin");
	db.prepare(
		"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?, ?, ?, 1, 0)",
	).run("editor@test.local", "hash", "Test Editor");
	for (const m of Object.values(fakeLocalStore)) m.mockReset();
	mockLoadLocalAdminStore.mockReset();
	mockLoadLocalAdminStore.mockResolvedValue(fakeLocalStore);
});

afterEach(() => {
	vi.clearAllMocks();
});

afterAll(() => {
	vi.resetModules();
});

async function inviteAndExtractToken(email = "new@test.local", role = "editor") {
	const result = (await inviteRuntimeAdminUser({ name: "New", email, role }, actor, locals)) as {
		inviteUrl: string;
	};
	const raw = result.inviteUrl.split("token=")[1];
	return decodeURIComponent(raw);
}

describe("inviteRuntimeAdminUser — error strings, audit, edge cases", () => {
	it("returns the exact 'name/email/role required' error when name is whitespace", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "  ", email: "x@test.local", role: "editor" },
			actor,
			locals,
		);
		expect(result).toEqual({ ok: false, error: "Name, email, and role are required." });
	});

	it("returns the exact 'name/email/role required' error when role is unrecognised", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "X", email: "x@test.local", role: "superuser" },
			actor,
			locals,
		);
		expect(result).toEqual({ ok: false, error: "Name, email, and role are required." });
	});

	it("returns the exact 'valid email' error for a malformed address (no dot)", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "X", email: "no-at-symbol", role: "editor" },
			actor,
			locals,
		);
		expect(result).toEqual({ ok: false, error: "Enter a valid email address." });
	});

	it("rejects an address missing the local part (anchored ^ in the regex)", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "X", email: "@host.tld", role: "editor" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: false, error: "Enter a valid email address." });
	});

	it("rejects an address missing the TLD (anchored $ in the regex)", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "X", email: "user@host", role: "editor" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: false, error: "Enter a valid email address." });
	});

	it("returns the exact 'already belongs to an admin user' error for a duplicate email", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "Dup", email: "editor@test.local", role: "editor" },
			actor,
			locals,
		);
		expect(result).toEqual({
			ok: false,
			error: "That email address already belongs to an admin user.",
		});
	});

	it("admin role is stored as is_admin=1, editor as is_admin=0", async () => {
		await inviteRuntimeAdminUser(
			{ name: "Adm", email: "admin2@test.local", role: "admin" },
			actor,
			locals,
		);
		await inviteRuntimeAdminUser(
			{ name: "Ed", email: "editor2@test.local", role: "editor" },
			actor,
			locals,
		);
		const adminRow = db
			.prepare("SELECT is_admin FROM admin_users WHERE email = 'admin2@test.local'")
			.get() as { is_admin: number };
		const editorRow = db
			.prepare("SELECT is_admin FROM admin_users WHERE email = 'editor2@test.local'")
			.get() as { is_admin: number };
		expect(adminRow.is_admin).toBe(1);
		expect(editorRow.is_admin).toBe(0);
	});

	it("invite id starts with 'invite-' and expires roughly 7 days from now", async () => {
		await inviteRuntimeAdminUser(
			{ name: "E", email: "e@test.local", role: "editor" },
			actor,
			locals,
		);
		const row = db
			.prepare("SELECT id, expires_at, invited_by FROM user_invites ORDER BY id DESC LIMIT 1")
			.get() as { id: string; expires_at: string; invited_by: string };
		expect(row.id.startsWith("invite-")).toBe(true);
		expect(row.invited_by).toBe(actor.email);
		const expiresMs = Date.parse(row.expires_at);
		const expectedMs = Date.now() + 7 * 24 * 60 * 60 * 1000;
		expect(Math.abs(expiresMs - expectedMs)).toBeLessThan(30_000);
		// Pin: must be at least 6 days in the future (kills any operator mutation that reduces TTL)
		expect(expiresMs).toBeGreaterThan(Date.now() + 6 * 24 * 60 * 60 * 1000);
	});

	it("records a user.invite audit event with the role and email in the summary", async () => {
		await inviteRuntimeAdminUser(
			{ name: "Adit", email: "audit@test.local", role: "admin" },
			actor,
			locals,
		);
		const row = db
			.prepare(
				"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
			)
			.get() as Record<string, string>;
		expect(row).toEqual({
			user_email: actor.email,
			action: "user.invite",
			resource_type: "auth",
			resource_id: "audit@test.local",
			summary: "Invited audit@test.local as an admin user.",
		});
	});

	it("forwards to localStore.inviteAdminUser when no D1 binding is present", async () => {
		fakeLocalStore.inviteAdminUser.mockResolvedValue({ ok: true, inviteUrl: "/local" });
		const input = { name: "X", email: "x@test.local", role: "editor" };
		const result = await inviteRuntimeAdminUser(input, actor, undefined);
		expect(fakeLocalStore.inviteAdminUser).toHaveBeenCalledWith(input, actor);
		expect(result).toEqual({ ok: true, inviteUrl: "/local" });
	});
});

describe("getRuntimeInviteRequest — token state branches and fallback", () => {
	it("returns null for an invite that has already been accepted", async () => {
		const token = await inviteAndExtractToken();
		db.prepare(
			"UPDATE user_invites SET accepted_at = CURRENT_TIMESTAMP WHERE accepted_at IS NULL",
		).run();
		const request = await getRuntimeInviteRequest(token, locals);
		expect(request).toBeNull();
	});

	it("returns null for an invite whose user has been deactivated", async () => {
		const token = await inviteAndExtractToken("inactive@test.local");
		db.prepare("UPDATE admin_users SET active = 0 WHERE email = 'inactive@test.local'").run();
		const request = await getRuntimeInviteRequest(token, locals);
		expect(request).toBeNull();
	});

	it("returns null for an expired invite token", async () => {
		const token = await inviteAndExtractToken();
		db.prepare(
			"UPDATE user_invites SET expires_at = '2000-01-01T00:00:00.000Z' WHERE accepted_at IS NULL",
		).run();
		const request = await getRuntimeInviteRequest(token, locals);
		expect(request).toBeNull();
	});

	it("forwards to localStore.getInviteRequest when no D1 binding is present", async () => {
		fakeLocalStore.getInviteRequest.mockResolvedValue({
			email: "x",
			name: "X",
			role: "editor",
			expiresAt: "x",
		});
		const result = await getRuntimeInviteRequest("rt", undefined);
		expect(fakeLocalStore.getInviteRequest).toHaveBeenCalledWith("rt");
		expect(result).toEqual({ email: "x", name: "X", role: "editor", expiresAt: "x" });
	});
});

describe("consumeRuntimeInviteToken — error strings, audit, branches", () => {
	it("returns the exact short-password error when the trimmed password is below 12 chars", async () => {
		const token = await inviteAndExtractToken();
		const result = await consumeRuntimeInviteToken(token, "    short    ", locals);
		expect(result).toEqual({ ok: false, error: "Password must be at least 12 characters." });
	}, 15000);

	it("accepts a password whose trimmed length is exactly 12", async () => {
		const token = await inviteAndExtractToken();
		const result = await consumeRuntimeInviteToken(token, "a".repeat(12), locals);
		expect(result).toMatchObject({ ok: true });
	}, 15000);

	it("returns the user object on success and records an auth.invite_accept audit event", async () => {
		const token = await inviteAndExtractToken("acceptor@test.local", "admin");
		const result = (await consumeRuntimeInviteToken(token, "newpassword123", locals)) as {
			ok: true;
			user: { email: string; role: string; name: string };
		};
		expect(result.ok).toBe(true);
		expect(result.user).toEqual({ email: "acceptor@test.local", role: "admin", name: "New" });
		const auditRow = db
			.prepare(
				"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
			)
			.get() as Record<string, string>;
		expect(auditRow).toEqual({
			user_email: "acceptor@test.local",
			action: "auth.invite_accept",
			resource_type: "auth",
			resource_id: "acceptor@test.local",
			summary: "acceptor@test.local accepted an admin invitation.",
		});
	}, 15000);

	it("forwards to localStore.consumeInviteToken when no D1 binding is present", async () => {
		fakeLocalStore.consumeInviteToken.mockResolvedValue({ ok: true });
		const result = await consumeRuntimeInviteToken("rt", "pw", undefined);
		expect(fakeLocalStore.consumeInviteToken).toHaveBeenCalledWith("rt", "pw");
		expect(result).toEqual({ ok: true });
	});
});

describe("suspendRuntimeAdminUser — error strings, audit, fallback", () => {
	it("returns the exact 'email required' error for a blank email", async () => {
		const result = await suspendRuntimeAdminUser("   ", actor, locals);
		expect(result).toEqual({ ok: false, error: "Email is required." });
	});

	it("returns the exact 'cannot suspend own account' error", async () => {
		const result = await suspendRuntimeAdminUser("admin@test.local", actor, locals);
		expect(result).toEqual({
			ok: false,
			error: "You cannot suspend the account you are currently using.",
		});
	});

	it("returns the exact 'could not be suspended' error for an unknown user", async () => {
		const result = await suspendRuntimeAdminUser("nobody@test.local", actor, locals);
		expect(result).toEqual({ ok: false, error: "That admin user could not be suspended." });
	});

	it("records a user.suspend audit event with the suspended email", async () => {
		await suspendRuntimeAdminUser("editor@test.local", actor, locals);
		const row = db
			.prepare(
				"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
			)
			.get() as Record<string, string>;
		expect(row).toEqual({
			user_email: actor.email,
			action: "user.suspend",
			resource_type: "auth",
			resource_id: "editor@test.local",
			summary: "Suspended editor@test.local.",
		});
	});

	it("forwards to localStore.suspendAdminUser when no D1 binding is present", async () => {
		fakeLocalStore.suspendAdminUser.mockResolvedValue({ ok: true });
		const result = await suspendRuntimeAdminUser("x@y.z", actor, undefined);
		expect(fakeLocalStore.suspendAdminUser).toHaveBeenCalledWith("x@y.z", actor);
		expect(result).toEqual({ ok: true });
	});
});

describe("unsuspendRuntimeAdminUser — error strings, audit, fallback", () => {
	it("returns the exact 'email required' error for a blank email", async () => {
		const result = await unsuspendRuntimeAdminUser("   ", actor, locals);
		expect(result).toEqual({ ok: false, error: "Email is required." });
	});

	it("returns the exact 'could not be restored' error for an already-active user", async () => {
		const result = await unsuspendRuntimeAdminUser("editor@test.local", actor, locals);
		expect(result).toEqual({ ok: false, error: "That admin user could not be restored." });
	});

	it("records a user.restore audit event with the restored email", async () => {
		db.prepare("UPDATE admin_users SET active = 0 WHERE email = 'editor@test.local'").run();
		await unsuspendRuntimeAdminUser("editor@test.local", actor, locals);
		const row = db
			.prepare(
				"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
			)
			.get() as Record<string, string>;
		expect(row).toEqual({
			user_email: actor.email,
			action: "user.restore",
			resource_type: "auth",
			resource_id: "editor@test.local",
			summary: "Restored editor@test.local.",
		});
	});

	it("forwards to localStore.unsuspendAdminUser when no D1 binding is present", async () => {
		fakeLocalStore.unsuspendAdminUser.mockResolvedValue({ ok: true });
		const result = await unsuspendRuntimeAdminUser("x@y.z", actor, undefined);
		expect(fakeLocalStore.unsuspendAdminUser).toHaveBeenCalledWith("x@y.z", actor);
		expect(result).toEqual({ ok: true });
	});
});

describe("createRuntimePasswordResetToken — re-export wiring", () => {
	it("is re-exported from runtime-actions-users and reaches localStore on the no-DB path", async () => {
		fakeLocalStore.createPasswordResetToken.mockResolvedValue({ ok: true, resetUrl: "/x" });
		const result = await createRuntimePasswordResetToken("e@test.local", actor, undefined);
		expect(fakeLocalStore.createPasswordResetToken).toHaveBeenCalledWith("e@test.local", actor);
		expect(result).toEqual({ ok: true, resetUrl: "/x" });
	});
});

