	});

	it("creates Appwrite and PocketBase hosted adapters with package-owned remote api defaults", async () => {
		const appwriteConfig = readDirectAppwriteHostedConfig({
			APPWRITE_ENDPOINT: "https://cloud.appwrite.io/v1",
