	it("reads hosted provider config from env maps", () => {
		expect(
			readAstropressSupabaseHostedConfig({
				SUPABASE_URL: "https://example.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "service",
			}),
		).toEqual({
			url: "https://example.supabase.co",
