		expect(
			readAstropressNhostHostedConfig({
				NHOST_SUBDOMAIN: "abcdefgh",
				NHOST_REGION: "eu-central-1",
				NHOST_ADMIN_SECRET: "secret",
			}),
		).toEqual({
			subdomain: "abcdefgh",
			region: "eu-central-1",
			adminSecret: "secret",
			apiBaseUrl: "https://abcdefgh.eu-central-1.nhost.run/v1/functions/astropress",
