import { describe, expect, it } from "vitest";
import { createAstropressCloudflareViteIntegration } from "../src/cloudflare-vite-integration";

describe("cloudflare vite integration helper", () => {
	it("creates stub aliases and a pre-resolution plugin", () => {
		const integration = createAstropressCloudflareViteIntegration(
			"/tmp/site/src/astropress/local-runtime-modules.ts",
		);

		expect(integration.aliases).toHaveLength(13);
		expect(integration.aliases[0]).toEqual({
			find: "astropress/local-image-storage",
			replacement: "astropress/cloudflare-local-image-storage-stub",
		});
		expect(integration.aliases[1]).toEqual({
			find: /^.*\/local-image-storage(?:\.[cm]?[jt]s)?$/,
			replacement: "astropress/cloudflare-local-image-storage-stub",
		});
		expect(integration.aliases[2]).toEqual({
			find: "astropress/local-media-storage",
			replacement: "astropress/cloudflare-local-media-storage-stub",
		});
		expect(integration.aliases[3]).toEqual({
			find: /^.*\/local-media-storage(?:\.[cm]?[jt]s)?$/,
			replacement: "astropress/cloudflare-local-media-storage-stub",
		});
		expect(integration.aliases[4]).toEqual({
			find: "astropress/adapters/sqlite",
			replacement: "astropress/cloudflare-sqlite-adapter-stub",
		});
		expect(integration.aliases[5]).toEqual({
			find: /^.*\/adapters\/sqlite(?:\.[cm]?[jt]s)?$/,
			replacement: "astropress/cloudflare-sqlite-adapter-stub",
		});
		expect(integration.aliases[6]).toEqual({
			find: "astropress/sqlite-admin-runtime",
			replacement: "astropress/cloudflare-sqlite-admin-runtime-stub",
		});
		expect(integration.aliases[7]).toEqual({
			find: /^.*\/sqlite-admin-runtime(?:\.[cm]?[jt]s)?$/,
			replacement: "astropress/cloudflare-sqlite-admin-runtime-stub",
		});
		expect(integration.aliases[8]).toEqual({
			find: "astropress/sqlite-bootstrap",
			replacement: "astropress/cloudflare-sqlite-bootstrap-stub",
		});
		expect(integration.aliases[9]).toEqual({
			find: /^.*\/sqlite-bootstrap(?:\.[cm]?[jt]s)?$/,
			replacement: "astropress/cloudflare-sqlite-bootstrap-stub",
		});
		expect(integration.aliases[12]?.replacement).toBe("astropress/cloudflare-local-runtime-stubs");
		expect(integration.plugin.name).toBe("astropress-cloudflare-local-runtime-stubs");
		expect(integration.plugin.resolveId("./local-runtime-modules")).toBe(
			"astropress/cloudflare-local-runtime-stubs",
		);
		expect(integration.plugin.resolveId("astropress/local-image-storage")).toBe(
			"astropress/cloudflare-local-image-storage-stub",
		);
		expect(
			integration.plugin.resolveId("/workspace/packages/astropress/src/local-image-storage.ts"),
		).toBe("astropress/cloudflare-local-image-storage-stub");
		expect(integration.plugin.resolveId("astropress/local-media-storage")).toBe(
			"astropress/cloudflare-local-media-storage-stub",
		);
		expect(
			integration.plugin.resolveId("/workspace/packages/astropress/src/local-media-storage.ts"),
		).toBe("astropress/cloudflare-local-media-storage-stub");
		expect(integration.plugin.resolveId("astropress/adapters/sqlite")).toBe(
			"astropress/cloudflare-sqlite-adapter-stub",
		);
		expect(integration.plugin.resolveId("astropress/sqlite-admin-runtime")).toBe(
			"astropress/cloudflare-sqlite-admin-runtime-stub",
		);
		expect(integration.plugin.resolveId("astropress/sqlite-bootstrap")).toBe(
			"astropress/cloudflare-sqlite-bootstrap-stub",
		);

		// line 115: non-matching ID returns null
		expect(
			integration.plugin.resolveId("/workspace/packages/astropress/src/some-other-module.ts"),
		).toBeNull();

		// lines 23-24: file:// URL normalization (decodeURIComponent + file:// strip)
		expect(
			integration.plugin.resolveId(
				"file:///workspace/packages/astropress/src/local-image-storage.ts",
			),
		).toBe("astropress/cloudflare-local-image-storage-stub");

		// lines 26-27: Windows-style path after file:// stripping (/C:/... → C:/...)
		expect(
			integration.plugin.resolveId(
				"file:///C:/workspace/packages/astropress/src/local-image-storage.ts",
			),
		).toBe("astropress/cloudflare-local-image-storage-stub");
	});

	it("resolves every literal variant of './local-runtime-modules' (with/without leading './' and '.ts')", () => {
		const integration = createAstropressCloudflareViteIntegration("/tmp/site/lrm.ts");
		for (const id of [
			"./local-runtime-modules",
			"./local-runtime-modules.ts",
			"local-runtime-modules",
			"local-runtime-modules.ts",
		]) {
			expect(integration.plugin.resolveId(id)).toBe("astropress/cloudflare-local-runtime-stubs");
		}
	});

	it("matches the exact localRuntimeModulesPath supplied at construction time", () => {
		const integration = createAstropressCloudflareViteIntegration("/abs/path/lrm.ts");
		expect(integration.plugin.resolveId("/abs/path/lrm.ts")).toBe(
			"astropress/cloudflare-local-runtime-stubs",
		);
	});

	it("matches IDs ending in '/local-runtime-modules' or '/local-runtime-modules.ts'", () => {
		const integration = createAstropressCloudflareViteIntegration("/tmp/site/lrm.ts");
		expect(integration.plugin.resolveId("/some/path/local-runtime-modules")).toBe(
			"astropress/cloudflare-local-runtime-stubs",
		);
		expect(integration.plugin.resolveId("/some/path/local-runtime-modules.ts")).toBe(
			"astropress/cloudflare-local-runtime-stubs",
		);
	});

	it("matches every variant of local-image-storage / local-media-storage", () => {
		const integration = createAstropressCloudflareViteIntegration("/tmp/site/lrm.ts");
		for (const id of [
			"astropress/local-image-storage",
			"/a/b/local-image-storage",
			"/a/b/local-image-storage.ts",
			"/a/b/local-image-storage.js",
		]) {
			expect(integration.plugin.resolveId(id)).toBe(
				"astropress/cloudflare-local-image-storage-stub",
			);
		}
		for (const id of [
			"astropress/local-media-storage",
			"/a/b/local-media-storage",
			"/a/b/local-media-storage.ts",
			"/a/b/local-media-storage.js",
		]) {
			expect(integration.plugin.resolveId(id)).toBe(
				"astropress/cloudflare-local-media-storage-stub",
			);
		}
	});

	it("matches every variant of sqlite-admin-runtime / sqlite-adapter / sqlite-bootstrap", () => {
		const integration = createAstropressCloudflareViteIntegration("/tmp/site/lrm.ts");
		for (const id of [
			"astropress/sqlite-admin-runtime",
			"/a/b/sqlite-admin-runtime",
			"/a/b/sqlite-admin-runtime.ts",
			"/a/b/sqlite-admin-runtime.js",
		]) {
			expect(integration.plugin.resolveId(id)).toBe(
				"astropress/cloudflare-sqlite-admin-runtime-stub",
			);
		}
		for (const id of [
			"astropress/adapters/sqlite",
			"/a/b/adapters/sqlite",
			"/a/b/adapters/sqlite.ts",
			"/a/b/adapters/sqlite.js",
		]) {
			expect(integration.plugin.resolveId(id)).toBe("astropress/cloudflare-sqlite-adapter-stub");
		}
		for (const id of [
			"astropress/sqlite-bootstrap",
			"/a/b/sqlite-bootstrap",
			"/a/b/sqlite-bootstrap.ts",
			"/a/b/sqlite-bootstrap.js",
		]) {
			expect(integration.plugin.resolveId(id)).toBe("astropress/cloudflare-sqlite-bootstrap-stub");
		}
	});

	it("honours every user-supplied option override for stub paths", () => {
		const integration = createAstropressCloudflareViteIntegration("/lrm.ts", {
			cloudflareLocalImageStorageStubPath: "custom-image",
			cloudflareLocalMediaStorageStubPath: "custom-media",
			cloudflareSqliteAdapterStubPath: "custom-adapter",
			cloudflareSqliteAdminRuntimeStubPath: "custom-admin-runtime",
			cloudflareSqliteBootstrapStubPath: "custom-bootstrap",
			cloudflareLocalRuntimeStubsPath: "custom-lrm",
		});
		expect(integration.plugin.resolveId("astropress/local-image-storage")).toBe("custom-image");
		expect(integration.plugin.resolveId("astropress/local-media-storage")).toBe("custom-media");
		expect(integration.plugin.resolveId("astropress/adapters/sqlite")).toBe("custom-adapter");
		expect(integration.plugin.resolveId("astropress/sqlite-admin-runtime")).toBe(
			"custom-admin-runtime",
		);
		expect(integration.plugin.resolveId("astropress/sqlite-bootstrap")).toBe("custom-bootstrap");
		expect(integration.plugin.resolveId("./local-runtime-modules")).toBe("custom-lrm");
	});

	it("normalizes Windows backslashes to forward slashes before matching", () => {
		const integration = createAstropressCloudflareViteIntegration("/lrm.ts");
		expect(integration.plugin.resolveId("C:\\workspace\\src\\local-image-storage.ts")).toBe(
			"astropress/cloudflare-local-image-storage-stub",
		);
	});

	it("strips file:// URL prefix before matching (pins L148 startsWith('file://'))", () => {
		// Mutating `startsWith('file://')` to `endsWith('file://')` (false for any
		// real URL), `if (true)` (always strip — also corrupts non-file paths),
		// or `if (false)` (never strip) all change the resolveId outcome for a
		// file:// URL. Original strips the scheme so endsWith fallback matches.
		const integration = createAstropressCloudflareViteIntegration("/lrm.ts");
		expect(integration.plugin.resolveId("file:///workspace/site/src/local-image-storage.ts")).toBe(
			"astropress/cloudflare-local-image-storage-stub",
		);
	});

	it("integration exposes plugin.enforce = 'pre' verbatim (kills L215 StringLiteral)", () => {
		const integration = createAstropressCloudflareViteIntegration("/lrm.ts");
		// Strict equality — "pre"→"" mutant changes the vite hook ordering.
		expect(integration.plugin.enforce).toBe("pre");
	});

	it("aliases[10] and aliases[11] expose both local-runtime-modules regex patterns verbatim", () => {
		const integration = createAstropressCloudflareViteIntegration("/lrm.ts");
		// L59-62 entry — narrow regex matching only './local-runtime-modules[.ts]'
		expect(integration.aliases[10]).toEqual({
			find: /^\.\/local-runtime-modules(?:\.ts)?$/,
			replacement: "astropress/cloudflare-local-runtime-stubs",
		});
		// L63-66 entry — broader regex matching '<anything>/local-runtime-modules[.ts]'.
		// This kills the L63-66 ObjectLiteral, Regex, and StringLiteral mutants
		// (no other entry catches '/some/path/local-runtime-modules' style ids).
		expect(integration.aliases[11]).toEqual({
			find: /^.*\/local-runtime-modules(?:\.ts)?$/,
			replacement: "astropress/cloudflare-local-runtime-stubs",
		});
	});

	it("does NOT decode URI-encoded ids that lack a file:// prefix (kills L148 'if(true)' and StringLiteral '')", () => {
		// Mutants `if (true)` and `startsWith("")` would always enter the decode block.
		// Decoding `%2E` to `.` would make `/a/b/local-image-storage%2Ets` become
		// `/a/b/local-image-storage.ts` which matches; the original leaves the id alone
		// so the endsWith fallback never fires.
		const integration = createAstropressCloudflareViteIntegration("/lrm.ts");
		expect(integration.plugin.resolveId("/a/b/local-image-storage%2Ets")).toBeNull();
	});

	it("file:// strip is required for exact localRuntimeModulesPath match when the path has no '/local-runtime-modules' suffix", () => {
		// Use a custom lrm path that does NOT end in '/local-runtime-modules[.ts]'.
		// That makes the endsWith fallback miss; only the file:// strip → exact match
		// path succeeds. Kills:
		//   148:6 ConditionalExpression `if (false)`
		//   148:6 MethodExpression .startsWith → .endsWith
		//   148:40 BlockStatement (empty if body)
		//   149:71 StringLiteral "/" → ""  (without the leading slash, exact-match fails)
		const integration = createAstropressCloudflareViteIntegration("/my/custom/path.ts");
		expect(integration.plugin.resolveId("file:///my/custom/path.ts")).toBe(
			"astropress/cloudflare-local-runtime-stubs",
		);
		// Sanity: same id without file:// also matches via direct exact equality.
		expect(integration.plugin.resolveId("/my/custom/path.ts")).toBe(
			"astropress/cloudflare-local-runtime-stubs",
		);
	});

	it("file:// strip handles 2-slash file:// URLs (kills L149 Regex '?' removal)", () => {
		// Original `/^file:\/\/\/?/` matches both `file://` (2 slashes) and `file:///` (3).
		// Mutant `/^file:\/\/\//` (no `?`) requires 3 slashes. With a 2-slash URL the
		// mutant leaves the prefix in place and exact-match fails.
		const integration = createAstropressCloudflareViteIntegration("/my/custom/path.ts");
		expect(integration.plugin.resolveId("file://my/custom/path.ts")).toBe(
			"astropress/cloudflare-local-runtime-stubs",
		);
	});

	it("Windows '/X:/' slice(1) is required for exact lrm match (kills L152/L153 slice mutants)", () => {
		// Custom lrm path begins with 'C:/' (no leading slash). After file:// strip the
		// normalized id is '/C:/...' and the slice(1) is necessary to recover the
		// exact-match path. Kills:
		//   152:6 ConditionalExpression `if (false)`
		//   152:6 Regex `[^a-zA-Z]` (no longer matches /C:/)
		//   152:41 BlockStatement (empty if body)
		//   153:10 MethodExpression .slice(1) → .slice() / identity
		const integration = createAstropressCloudflareViteIntegration("C:/win/path.ts");
		expect(integration.plugin.resolveId("file:///C:/win/path.ts")).toBe(
			"astropress/cloudflare-local-runtime-stubs",
		);
	});
});

tests/sqlite-admin-runtime-auth.test.ts.source:
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createKmacDigest } from "../src/crypto-primitives.js";
import { hashPassword, isLegacyHash, verifyPassword } from "../src/crypto-utils.js";
import { createAstropressSqliteAdminRuntime } from "../src/sqlite-admin-runtime.js";
import { makeDb } from "./helpers/make-db.js";
import {
	createRuntimeFixture,
	makePasswordHash,
	type RuntimeFixture,
} from "./helpers/sqlite-admin-runtime-fixture.js";

let fixture: RuntimeFixture;

beforeAll(() => {
	fixture = createRuntimeFixture();
});

afterAll(() => {
	fixture.db.close();
});

// ─── Factory option defaults ──────────────────────────────────────────────────

describe("factory option defaults", () => {
	it("creates runtime with default sessionTtlMs, now, and randomId", () => {
		const rt = createAstropressSqliteAdminRuntime({
			getDatabase: () => fixture.db,
		});
		expect(rt.sqliteAdminStore).toBeDefined();
		expect(rt.sqliteCmsRegistryModule).toBeDefined();
		expect(rt.authenticatePersistedAdminUser).toBeInstanceOf(Function);
	});
});

// ─── Auth ─────────────────────────────────────────────────────────────────────

describe("auth", () => {
	it("returns null for empty email", async () => {
		expect(await fixture.runtime.authenticatePersistedAdminUser("", "correct-password")).toBeNull();
	});

	it("returns null for malformed password hash (verifyPasswordSync malformed-hash branch)", async () => {
		expect(
			await fixture.runtime.authenticatePersistedAdminUser("malformed@test.local", "any-password"),
		).toBeNull();
	});

	it("returns null for wrong password", async () => {
		expect(
			await fixture.runtime.authenticatePersistedAdminUser("admin@test.local", "wrong-password"),
		).toBeNull();
	});

	it("returns user for correct password", async () => {
		const user = await fixture.runtime.authenticatePersistedAdminUser(
			"admin@test.local",
			"correct-password",
		);
		expect(user?.email).toBe("admin@test.local");
		expect(user?.role).toBe("admin");
	});

	it("getSessionUser returns null for null/empty token", () => {
		expect(fixture.store.auth.getSessionUser(null as unknown as string)).toBeNull();
		expect(fixture.store.auth.getSessionUser("")).toBeNull();
	});

	it("getCsrfToken returns null for empty token", () => {
		expect(fixture.store.auth.getCsrfToken("")).toBeNull();
	});

	it("session lifecycle: create → get → getCsrfToken → revoke", async () => {
		const user = await fixture.runtime.authenticatePersistedAdminUser(
			"admin@test.local",
			"correct-password",
		);
		const sessionToken = fixture.store.auth.createSession(user as NonNullable<typeof user>, {
			ipAddress: "127.0.0.1",
		});
		expect(typeof sessionToken).toBe("string");

		const sessionUser = fixture.store.auth.getSessionUser(sessionToken);
		expect(sessionUser?.email).toBe("admin@test.local");

		const csrf = fixture.store.auth.getCsrfToken(sessionToken);
		expect(typeof csrf).toBe("string");

		fixture.store.auth.revokeSession(sessionToken);
		expect(fixture.store.auth.getSessionUser(sessionToken)).toBeNull();
	});

	it("revokeSession with null token is a no-op", () => {
		expect(() => fixture.store.auth.revokeSession(null as unknown as string)).not.toThrow();
	});

	it("getSessionUser returns null for expired session (sessionTtlMs branch)", async () => {
		const expiredDb = makeDb();
		expiredDb
			.prepare(
				"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, 1, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
			)
			.run("expired@test.local", makePasswordHash("password"), "admin", "Expired");
		let clockOffset = 0;
		const expiredRuntime = createAstropressSqliteAdminRuntime({
			getDatabase: () => expiredDb,
			sessionTtlMs: 1,
			now: () => Date.now() + clockOffset,
		});
		const user = await expiredRuntime.authenticatePersistedAdminUser(
			"expired@test.local",
			"password",
		);
		const token = expiredRuntime.sqliteAdminStore.auth.createSession(
			user as NonNullable<typeof user>,
			{},
		);
		// Session created under real clock; now advance past the 1ms TTL
		clockOffset = 100_000;
		expect(expiredRuntime.sqliteAdminStore.auth.getSessionUser(token)).toBeNull();
		expiredDb.close();
	});

	it("createPasswordResetToken: unknown user without actor returns ok:true with null resetUrl", () => {
		const result = fixture.store.auth.createPasswordResetToken("nobody@test.local", null);
		expect(result).toMatchObject({ ok: true, resetUrl: null });
	});

	it("createPasswordResetToken: known user returns ok:true with resetUrl", () => {
		const result = fixture.store.auth.createPasswordResetToken("admin@test.local", fixture.actor);
		expect(result.ok).toBe(true);
		if (!result.ok) throw new Error("unreachable");
		expect(result.resetUrl).toContain("token=");
	});

	it("createPasswordResetToken: unknown user with actor returns ok:false", () => {
		const result = fixture.store.auth.createPasswordResetToken("nobody@test.local", fixture.actor);
		expect(result).toMatchObject({ ok: false });
	});

	it("createPasswordResetToken: empty email returns ok:false", () => {
		expect(fixture.store.auth.createPasswordResetToken("", fixture.actor)).toMatchObject({
			ok: false,
		});
	});

	it("getPasswordResetRequest: empty token returns null", () => {
		expect(fixture.store.auth.getPasswordResetRequest("")).toBeNull();
	});

	it("getPasswordResetRequest: invalid token returns null", () => {
		expect(fixture.store.auth.getPasswordResetRequest("invalid-token")).toBeNull();
	});

	it("getInviteRequest: empty token returns null", () => {
		expect(fixture.store.auth.getInviteRequest("")).toBeNull();
	});

	it("getInviteRequest: invalid token returns null", () => {
		expect(fixture.store.auth.getInviteRequest("not-a-real-token")).toBeNull();
	});

	it("consumeInviteToken: short password returns error", () => {
		expect(fixture.store.auth.consumeInviteToken("any-token", "short")).toMatchObject({
			ok: false,
		});
	});

	it("consumeInviteToken: invalid token returns error", () => {
		expect(
			fixture.store.auth.consumeInviteToken("not-a-real-token", "long-enough-password"),
		).toMatchObject({ ok: false });
	});

	it("consumePasswordResetToken: short password returns error", () => {
		expect(fixture.store.auth.consumePasswordResetToken("any-token", "short")).toMatchObject({
			ok: false,
		});
	});

	it("consumePasswordResetToken: invalid token returns error", () => {
		expect(
			fixture.store.auth.consumePasswordResetToken("not-a-real-token", "long-enough-password"),
		).toMatchObject({ ok: false });
	});

	it("full password reset flow: issue, get request, consume", () => {
		const issued = fixture.store.auth.createPasswordResetToken("admin@test.local", fixture.actor);
		expect(issued.ok).toBe(true);
		if (!issued.ok) throw new Error("unreachable");

		const rawToken = decodeURIComponent(issued.resetUrl?.split("token=")[1]);
		const request = fixture.store.auth.getPasswordResetRequest(rawToken);
		expect(request?.email).toBe("admin@test.local");

		const consumed = fixture.store.auth.consumePasswordResetToken(
			rawToken,
			"new-long-password-123",
		);
		expect(consumed.ok).toBe(true);

		expect(fixture.store.auth.getPasswordResetRequest(rawToken)).toBeNull();
	});

	it("full invite flow: create invite, get request, consume", async () => {
		fixture.store.users.inviteAdminUser(
			{ email: "invite-flow@test.local", role: "editor", name: "Invite Flow" },
			fixture.actor,
		);

		const inviteRawToken = "test-invite-raw-token-xyz";
		const tokenHash = createKmacDigest(
			inviteRawToken,
			"astropress-dev-root-secret",
			"sqlite-opaque-token",
		);
		const invitedUserId = (
			fixture.db
				.prepare("SELECT id FROM admin_users WHERE email = 'invite-flow@test.local'")
				.get() as { id: number }
		).id;
		fixture.db
			.prepare(
				"INSERT INTO user_invites (id, user_id, token_hash, expires_at, invited_by) VALUES (?, ?, ?, datetime('now', '+7 days'), ?)",
			)
			.run("invite-flow-1", invitedUserId, tokenHash, "admin@test.local");

		const inviteRequest = fixture.store.auth.getInviteRequest(inviteRawToken);
		expect(inviteRequest?.email).toBe("invite-flow@test.local");

		const consumed = fixture.store.auth.consumeInviteToken(
			inviteRawToken,
			"my-new-secure-password",
		);
		expect(consumed.ok).toBe(true);

		expect(fixture.store.auth.getInviteRequest(inviteRawToken)).toBeNull();
	});

	it("recordSuccessfulLogin records an auth audit event", () => {
		expect(() => fixture.store.auth.recordSuccessfulLogin(fixture.actor)).not.toThrow();
	});

	it("recordLogout records an auth audit event", () => {
		expect(() => fixture.store.auth.recordLogout(fixture.actor)).not.toThrow();
	});

	it("getCsrfToken returns null for expired session", { timeout: 60_000 }, async () => {
		const expiredDb = makeDb();
		expiredDb
			.prepare(
				"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, 1, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
			)
			.run("expired2@test.local", makePasswordHash("password"), "admin", "Expired2");
		let clockOffset = 0;
		const expiredRuntime = createAstropressSqliteAdminRuntime({
			getDatabase: () => expiredDb,
			sessionTtlMs: 1,
			now: () => Date.now() + clockOffset,
		});
		const user = await expiredRuntime.authenticatePersistedAdminUser(
			"expired2@test.local",
			"password",
		);
		const token = expiredRuntime.sqliteAdminStore.auth.createSession(
			user as NonNullable<typeof user>,
			{},
		);
		// Session created under real clock; now advance past the 1ms TTL
		clockOffset = 100_000;
		expect(expiredRuntime.sqliteAdminStore.auth.getCsrfToken(token)).toBeNull();
		expiredDb.close();
	});
});

// ─── Auth additional branches ─────────────────────────────────────────────────

describe("auth additional branches", () => {
	it("getCsrfToken returns null for revoked session (getSessionUser !row branch)", () => {
		const token = fixture.store.auth.createSession(
			{ email: "admin@test.local", role: "admin" as const, name: "Test Admin" },
			{},
		);
		fixture.store.auth.revokeSession(token);
		expect(fixture.store.auth.getCsrfToken(token)).toBeNull();
	});

	it("createSession throws for unknown user email", () => {
		expect(() =>
			fixture.store.auth.createSession(
				{
					email: "nobody-at-all@test.local",
					role: "admin" as const,
					name: "Nobody",
				},
				{},
			),
		).toThrow();
	});
});

// ─── Password hashing — Argon2id with explicit legacy cutoff ─────────────────

// Use reduced iterations in tests to keep run time under 5 s while still exercising
// the same code paths. The stored format embeds the iteration count, so verifyPassword
// reads it back and uses the same value — the round-trip is still fully verified.
const TEST_ITERATIONS = 1;

describe("password hashing", () => {
	it("hashPassword produces an Argon2id-prefixed hash", async () => {
		const hash = await hashPassword("my-secret-password", 32, TEST_ITERATIONS);
		expect(hash.startsWith("v3:argon2id$")).toBe(true);
	});

	it("hashPassword encodes the work factor in the stored string", async () => {
		const hash = await hashPassword("password", 32, TEST_ITERATIONS);
		const [, iters] = hash.split("$");
		expect(Number(iters)).toBe(TEST_ITERATIONS);
	});

	it("isLegacyHash returns false for an Argon2id hash", async () => {
		const hash = await hashPassword("password", 32, TEST_ITERATIONS);
		expect(isLegacyHash(hash)).toBe(false);
	});

	it("isLegacyHash returns true for a pre-Argon2 password format", () => {
		const legacyHash = "600000$c2FsdA==$aGFzaA==";
		expect(isLegacyHash(legacyHash)).toBe(true);
	});

	it("verifyPassword returns true for a correct Argon2id password", async () => {
		const hash = await hashPassword("correct-password", 32, TEST_ITERATIONS);
		expect(await verifyPassword("correct-password", hash)).toBe(true);
	});

	it("verifyPassword returns false for a wrong Argon2id password", async () => {
		const hash = await hashPassword("correct-password", 32, TEST_ITERATIONS);
		expect(await verifyPassword("wrong-password", hash)).toBe(false);
	});

	it("verifyPassword returns false for a legacy pre-Argon2 password", async () => {
		const legacyHash = "600000$c2FsdA==$aGFzaA==";
		expect(await verifyPassword("wrong-password", legacyHash)).toBe(false);
	});

	it("verifyPassword returns false for a malformed hash string", async () => {
		expect(await verifyPassword("any-password", "not-a-valid-hash")).toBe(false);
	});
});

