import { describe, expect, it, vi } from "vitest";

import { verifyMlDsaMessage } from "../src/crypto-primitives.js";
import type { WebhookEvent, WebhookRecord, WebhookStore } from "../src/platform-contracts";
import { createWebhookStore } from "../src/sqlite-runtime/webhooks.js";
import { makeDb } from "./helpers/make-db.js";

const { loggerErrorSpy } = vi.hoisted(() => ({ loggerErrorSpy: vi.fn() }));

vi.mock("../src/runtime-logger", () => ({
	createLogger: () => ({
		info: vi.fn(),
		warn: vi.fn(),
		error: loggerErrorSpy,
	}),
}));

describe("WebhookRecord shape", () => {
	it("has all required fields", () => {
		const record: WebhookRecord = {
			id: "wh_01",
			url: "https://example.com/hook",
			events: ["content.published"],
			active: true,
			createdAt: new Date().toISOString(),
		};

		expect(record.id).toBe("wh_01");
		expect(record.url).toBe("https://example.com/hook");
		expect(record.active).toBe(true);
		expect(record.lastFiredAt).toBeUndefined();
	});

	it("supports all defined webhook events", () => {
		const allEvents: WebhookEvent[] = [
			"content.published",
			"content.updated",
			"content.deleted",
			"media.uploaded",
			"media.deleted",
		];
		const record: WebhookRecord = {
			id: "wh_02",
			url: "https://example.com/hook",
			events: allEvents,
			active: true,
			createdAt: new Date().toISOString(),
		};
		expect(record.events).toHaveLength(5);
	});
});

describe("WebhookStore SQLite implementation", () => {
	it("create: returns a one-time ML-DSA verification bundle", async () => {
		const db = makeDb();
		const store = createWebhookStore(db, fetch);

		const { record, verification } = await store.create({
			url: "https://example.com/hook",
			events: ["content.published"],
		});

		expect(verification.algorithm).toBe("ML-DSA-65");
		expect(verification.keyId).toBe(record.id);
		expect(verification.publicKey.length).toBeGreaterThan(100);
		expect(record.url).toBe("https://example.com/hook");
		expect(record.events).toEqual(["content.published"]);
		expect(record.active).toBe(true);

		// The private signing key is stored server-side; the public key is returned once.
		const row = db.prepare("SELECT secret_hash FROM webhooks WHERE id = ?").get(record.id) as {
			secret_hash: string;
		};
		expect(row.secret_hash).not.toBe(verification.publicKey);
	});

	it("list: returns only active (non-deleted) webhooks", async () => {
		const db = makeDb();
		const store = createWebhookStore(db, fetch);

		const { record: r1 } = await store.create({
			url: "https://a.com/hook",
			events: ["content.published"],
		});
		const { record: r2 } = await store.create({
			url: "https://b.com/hook",
			events: ["media.uploaded"],
		});
		await store.delete(r1.id);

		const active = await store.list();
		expect(active.some((w) => w.id === r2.id)).toBe(true);
		expect(active.some((w) => w.id === r1.id)).toBe(false);
	});

	it("delete: soft-deletes so the webhook is gone from list", async () => {
		const db = makeDb();
		const store = createWebhookStore(db, fetch);
		const { record } = await store.create({
			url: "https://c.com/hook",
			events: ["content.deleted"],
		});

		await store.delete(record.id);

		const row = db.prepare("SELECT deleted_at FROM webhooks WHERE id = ?").get(record.id) as {
			deleted_at: string | null;
		};
		expect(row.deleted_at).not.toBeNull();
	});

	it("dispatch: sends POST with ML-DSA-65 signature headers", async () => {
		const db = makeDb();
		let capturedRequest: Request | undefined;
		const mockFetch = async (req: Request) => {
			capturedRequest = req;
			return new Response("ok", { status: 200 });
		};

		const store = createWebhookStore(db, mockFetch as typeof fetch);
		const { record, verification } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		const payload = { id: "post-1", status: "published" };
		await store.dispatch("content.published", payload);

		expect(capturedRequest).toBeDefined();
		expect(capturedRequest?.method).toBe("POST");

		const sig = capturedRequest?.headers.get("x-astropress-signature");
		expect(sig).toBeTruthy();
		expect(capturedRequest?.headers.get("x-astropress-signature-alg")).toBe("ML-DSA-65");
		expect(capturedRequest?.headers.get("x-astropress-key-id")).toBe(record.id);

		const body = await capturedRequest?.clone().text();
		expect(verifyMlDsaMessage(body, sig as string, verification.publicKey)).toBe(true);
	});

	it("dispatch: partial failure does not throw", async () => {
		const db = makeDb();
		let callCount = 0;
		const mockFetch = async () => {
			callCount++;
			if (callCount === 1) throw new Error("Network error");
			return new Response("ok", { status: 200 });
		};

		const store = createWebhookStore(db, mockFetch as typeof fetch);
		await store.create({
			url: "https://fail.example.com/hook",
			events: ["content.updated"],
		});
		await store.create({
			url: "https://ok.example.com/hook",
			events: ["content.updated"],
		});

		await expect(store.dispatch("content.updated", { test: true })).resolves.not.toThrow();
		expect(callCount).toBe(2);
	});

	it("dispatch: skips webhooks not subscribed to the event", async () => {
		const db = makeDb();
		let callCount = 0;
		const mockFetch = async () => {
			callCount++;
			return new Response("ok", { status: 200 });
		};

		const store = createWebhookStore(db, mockFetch as typeof fetch);
		await store.create({
			url: "https://media.example.com/hook",
			events: ["media.uploaded"],
		});

		await store.dispatch("content.published", { id: "x" });
		expect(callCount).toBe(0);
	});
});

describe("WebhookStore mutation pins", () => {
	function insertWebhookRow(
		db: ReturnType<typeof makeDb>,
		row: { id: string; url: string; active: number },
	) {
		db.prepare(
			"INSERT INTO webhooks (id, url, events, secret_hash, active) VALUES (?, ?, ?, ?, ?)",
		).run(row.id, row.url, JSON.stringify(["content.published"]), "secret", row.active);
	}

	it("list: maps the active column to a boolean (kills L27 ConditionalExpression true/false & EqualityOperator)", async () => {
		// rowToRecord computes `active: row.active === 1`. Mutants that force the
		// result to true/false, or flip `===` to `!==`, are only observable when
		// list() returns both an active (1) and an inactive (0) non-deleted row.
		const db = makeDb();
		insertWebhookRow(db, { id: "wh_on", url: "https://on.example.com", active: 1 });
		insertWebhookRow(db, { id: "wh_off", url: "https://off.example.com", active: 0 });
		const store = createWebhookStore(db, fetch);

		const list = await store.list();
		expect(list.find((w) => w.id === "wh_on")?.active).toBe(true);
		expect(list.find((w) => w.id === "wh_off")?.active).toBe(false);
	});

	it("list: maps last_fired_at to lastFiredAt after a dispatch (kills L29 LogicalOperator ?? → &&)", async () => {
		// `lastFiredAt: row.last_fired_at ?? null`. With `&&` the mapping yields
		// null even when the column holds a timestamp.
		const db = makeDb();
		const mockFetch = async () => new Response("ok", { status: 200 });
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});
		await store.dispatch("content.published", { id: "x" });

		const listed = (await store.list()).find((w) => w.id === record.id);
		expect(typeof listed?.lastFiredAt).toBe("string");
		expect(listed?.lastFiredAt).toBeTruthy();
	});

	it("dispatch: request body carries the event, payload, and a timestamp (kills L87 ObjectLiteral {})", async () => {
		const db = makeDb();
		let capturedRequest: Request | undefined;
		const mockFetch = async (req: Request) => {
			capturedRequest = req;
			return new Response("ok", { status: 200 });
		};
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "post-7", status: "published" });

		const body = JSON.parse((await capturedRequest?.clone().text()) ?? "{}") as {
			event?: string;
			payload?: { id?: string; status?: string };
			timestamp?: string;
		};
		expect(body.event).toBe("content.published");
		expect(body.payload).toEqual({ id: "post-7", status: "published" });
		expect(typeof body.timestamp).toBe("string");
	});

	it("dispatch: sends an application/json Content-Type header (kills L102 StringLiteral '')", async () => {
		const db = makeDb();
		let capturedRequest: Request | undefined;
		const mockFetch = async (req: Request) => {
			capturedRequest = req;
			return new Response("ok", { status: 200 });
		};
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "x" });
		expect(capturedRequest?.headers.get("content-type")).toBe("application/json");
	});

	it("dispatch: successful delivery records last_fired_at (kills L118 StringLiteral '')", async () => {
		const db = makeDb();
		const mockFetch = async () => new Response("ok", { status: 200 });
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "x" });
		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).not.toBeNull();
	});

	it("dispatch: failed delivery leaves last_fired_at NULL and logs the error (kills L111 BlockStatement, L112 StringLiteral & ObjectLiteral)", async () => {
		// The catch block logs and `return`s before the last_fired_at UPDATE.
		// Emptying it (BlockStatement {}) would let the UPDATE run on a failed
		// delivery; blanking the log message or its meta object drops the error
		// context.
		loggerErrorSpy.mockClear();
		const db = makeDb();
		const mockFetch = async () => {
			throw new Error("Network error");
		};
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://fail.example.com/hook",
			events: ["content.updated"],
		});

		await store.dispatch("content.updated", { id: "x" });

		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).toBeNull();

		expect(loggerErrorSpy).toHaveBeenCalledTimes(1);
		const [message, meta] = loggerErrorSpy.mock.calls[0] as [string, { error?: unknown }];
		expect(message).toContain("content.updated");
		expect(message).toContain("https://fail.example.com/hook");
		expect(meta.error).toBeInstanceOf(Error);
	});
});

// Type-level smoke test
function assertWebhookStoreShape(store: WebhookStore) {
	const _list = store.list;
	const _create = store.create;
	const _delete = store.delete;
	const _dispatch = store.dispatch;
	return { _list, _create, _delete, _dispatch };
}

void assertWebhookStoreShape;

tests/project-launch.test.ts.source:
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { createAstropressProjectLaunchPlan } from "../src/project-launch.js";

describe("project launch", () => {
	it("builds a local launch plan with static hosting and no hosted data-services by default", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-launch-local-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "github-pages",
				ASTROPRESS_DATA_SERVICES: "none",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "admin.sqlite"),
			},
		});

		expect(plan.runtime.mode).toBe("local");
		expect(plan.provider).toBe("sqlite");
		expect(plan.appHost).toBe("github-pages");
		expect(plan.dataServices).toBe("none");
		expect(plan.requiresLocalSeed).toBe(true);
		expect(plan.recommendation.appHost).toBe("github-pages");
		expect(plan.recommendation.dataServices).toBe("none");

		await rm(workspace, { recursive: true, force: true });
	});

	it("builds a hosted launch plan that separates the app host from the service layer", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_APP_HOST: "vercel",
				ASTROPRESS_DATA_SERVICES: "supabase",
				ASTROPRESS_HOSTED_PROVIDER: "supabase",
				SUPABASE_URL: "https://runtime.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "service",
			},
			hosted: {
				content: {
					async list() {
						return [];
					},
					async get() {
						return null;
					},
					async save(record) {
						return record;
					},
					async delete() {},
				},
				media: {
					async put(asset) {
						return asset;
					},
					async get() {
						return null;
					},
					async delete() {},
				},
				revisions: {
					async list() {
						return [];
					},
					async append(revision) {
						return revision;
					},
				},
				auth: {
					async signIn(email) {
						return { id: "runtime-session", email, role: "admin" as const };
					},
					async signOut() {},
					async getSession(sessionId) {
						return {
							id: sessionId,
							email: "admin@example.com",
							role: "admin" as const,
						};
					},
				},
			},
		});

		expect(plan.runtime.mode).toBe("hosted");
		expect(plan.provider).toBe("supabase");
		expect(plan.appHost).toBe("vercel");
		expect(plan.dataServices).toBe("supabase");
		expect(plan.requiresLocalSeed).toBe(false);
		expect(plan.recommendation.appHost).toBe("vercel");
		expect(plan.recommendation.dataServices).toBe("supabase");
		expect(plan.deployTarget).toBe("vercel");
	});

	it("dataServices=cloudflare flows Cloudflare to recommendation.existingPlatform (kills L30 branch mutants)", async () => {
		// Local mode keeps adapter setup minimal; the recommendation engine
		// reads runtime.env.dataServices independently of the runtime mode.
		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-launch-cf-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "cloudflare-pages",
				ASTROPRESS_DATA_SERVICES: "cloudflare",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "admin.sqlite"),
			},
		});
		expect(plan.recommendation.dataServices).toBe("cloudflare");
		await rm(workspace, { recursive: true, force: true });
	});

	it("dataServices=appwrite flows Appwrite to recommendation.existingPlatform (kills L32 branch mutants)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-launch-aw-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "render-web",
				ASTROPRESS_DATA_SERVICES: "appwrite",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "admin.sqlite"),
			},
		});
		expect(plan.recommendation.dataServices).toBe("appwrite");
		await rm(workspace, { recursive: true, force: true });
	});

	it("an unknown dataServices string maps to existingPlatform='none' (kills L36 default-string mutant)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "github-pages",
				ASTROPRESS_DATA_SERVICES: "none",
			},
		});
		// dataServices=none → existingPlatform=none + wantsHostedAdmin=false
		// + wantsStaticMirror=true (github-pages) → rec.dataServices="none".
		expect(plan.recommendation.dataServices).toBe("none");
	});

	it("local mode + gitlab-pages app host triggers wantsStaticMirror=true (kills L58 LogicalOperator mutant)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "gitlab-pages",
				ASTROPRESS_DATA_SERVICES: "none",
			},
		});
		// Static mirror path: rec.appHost is "github-pages" (per
		// recommendAstropressProvider's wantsStaticMirror=true branch when
		// existingPlatform=none and wantsHostedAdmin=false).
		expect(plan.recommendation.appHost).toBe("github-pages");
	});

	it("provider mirrors runtime.env.localProvider in local mode (kills L44 mode-branch mutant)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-launch-prov-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_LOCAL_PROVIDER: "supabase",
				ASTROPRESS_APP_HOST: "github-pages",
				ASTROPRESS_DATA_SERVICES: "none",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "admin.sqlite"),
			},
		});
		// Local mode → provider must come from env.localProvider, not hostedProvider.
		expect(plan.provider).toBe("supabase");
		expect(plan.requiresLocalSeed).toBe(true);
		await rm(workspace, { recursive: true, force: true });
	});

	it("cloudflare + github-pages routes wantsStaticMirror=true through L100 cloudflare branch (kills L26 cloudflare-eq, L26:23 StringLiteral, L49:5 LogicalOperator &&, L49:29 StringLiteral, L49:5 ConditionalExpression:false)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-pl-cf-static-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "github-pages",
				ASTROPRESS_DATA_SERVICES: "cloudflare",
			},
			local: { workspaceRoot: workspace, dbPath: join(workspace, "admin.sqlite") },
		});
		// cloudflare + wantsStaticMirror=true → L100 returns "github-pages","cloudflare".
		// Any mutant that suppresses existingPlatform="cloudflare" or wantsStaticMirror=true
		// causes the default fallback "cloudflare-pages" → observable appHost diverges.
		expect(plan.recommendation.appHost).toBe("github-pages");
		expect(plan.recommendation.dataServices).toBe("cloudflare");
		await rm(workspace, { recursive: true, force: true });
	});

	it("supabase + gitlab-pages routes wantsStaticMirror through L84 supabase branch (kills L49:47 ConditionalExpression, L49:71 StringLiteral, L49:5 LogicalOperator)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_APP_HOST: "gitlab-pages",
				ASTROPRESS_DATA_SERVICES: "supabase",
				ASTROPRESS_HOSTED_PROVIDER: "supabase",
				SUPABASE_URL: "https://x.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "test",
			},
		});
		// gitlab-pages flips wantsStaticMirror=true via the right disjunct.
		// Original: L84 supabase + wantsStaticMirror=true → recommendation.appHost = "github-pages".
		// Mutants that break the gitlab-pages disjunct → wantsStaticMirror=false → "vercel".
		expect(plan.recommendation.appHost).toBe("github-pages");
		expect(plan.recommendation.dataServices).toBe("supabase");
	});

	it("hosted mode with appwrite picks hostedProvider over localProvider=sqlite (kills L37:3 ConditionalExpression:false, L37:20 StringLiteral)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_APP_HOST: "render-web",
				ASTROPRESS_DATA_SERVICES: "appwrite",
				ASTROPRESS_HOSTED_PROVIDER: "appwrite",
				APPWRITE_ENDPOINT: "https://appwrite.example",
				APPWRITE_PROJECT_ID: "proj",
				APPWRITE_API_KEY: "key",
			},
			hosted: {
				content: {
					async list() {
						return [];
					},
					async get() {
						return null;
					},
					async save(record) {
						return record;
					},
					async delete() {},
				},
				media: {
					async put(asset) {
						return asset;
					},
					async get() {
						return null;
					},
					async delete() {},
				},
				revisions: {
					async list() {
						return [];
					},
					async append(revision) {
						return revision;
					},
				},
				auth: {
					async signIn(email) {
						return { id: "runtime-session", email, role: "admin" as const };
					},
					async signOut() {},
					async getSession(sessionId) {
						return {
							id: sessionId,
							email: "admin@example.com",
							role: "admin" as const,
						};
					},
				},
			},
		});
		// dataServices=appwrite → localProvider falls through to "sqlite" (not "supabase").
		// Original (mode=hosted): plan.provider = hostedProvider = "appwrite".
		// L37 mutants that flip the ternary always-false: plan.provider = localProvider = "sqlite".
		expect(plan.provider).toBe("appwrite");
	});

	it("unrecognized dataServices='pocketbase' + wantsStaticMirror=false flows to default cloudflare-pages (kills L50:22 ConditionalExpression:false)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "vercel",
				ASTROPRESS_DATA_SERVICES: "pocketbase",
			},
		});
		// dataServices="pocketbase" (valid env value, not in [none|cloudflare|supabase|appwrite])
		//   → existingPlatform="none" via the fallback.
		//   → wantsHostedAdmin = (pocketbase !== "none") = true (original).
		//   → wantsStaticMirror = false (vercel ∉ {github-pages, gitlab-pages}).
		// Recommendation routes to final default ("cloudflare-pages","cloudflare").
		// L50:22 ConditionalExpression:false flips wantsHostedAdmin to false →
		//   recommendation routes to L116 → ("github-pages","none"). Observable diff.
		expect(plan.recommendation.appHost).toBe("cloudflare-pages");
		expect(plan.recommendation.dataServices).toBe("cloudflare");
	});

	it("dataServices !== 'none' sets wantsHostedAdmin=true on the recommendation input (kills L60 mutant)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_APP_HOST: "vercel",
				ASTROPRESS_DATA_SERVICES: "supabase",
				ASTROPRESS_HOSTED_PROVIDER: "supabase",
				SUPABASE_URL: "https://x.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "test",
			},
		});
		// dataServices="supabase" (!== "none") → wantsHostedAdmin=true.
		// Combined with existingPlatform="supabase" → rec routes to supabase.
		expect(plan.recommendation.dataServices).toBe("supabase");
	});
});

