/**
 * runtime-page-store mutation pins.
 *
 * Targets survivors in runtime-page-store.ts that aren't covered by the
 * thinner monitoring/content-search suites: getSeededContentRecords' .map
 * callback, the searchRuntimeContentStates config-gate paths,
 * getRuntimeContentStateByPath's normalize-and-find logic, and the
 * getRuntimeTranslationState body.
 */

import { afterEach, describe, expect, it, vi } from "vitest";

import type { SeededContentRecord } from "../src/runtime-page-store-helpers.js";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

function setCmsConfig(extra: Record<string, unknown> = {}) {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = {
		siteName: "Test Site",
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [],
		...extra,
	};
}

function clearCmsConfig() {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = null;
}

vi.mock("../src/admin-store-dispatch.js", async () => {
	const actual = await vi.importActual<typeof import("../src/admin-store-dispatch.js")>(
		"../src/admin-store-dispatch.js",
	);
	return {
		...actual,
		// Force the static-read-store fallback path so seedPages drives the store.
		safeLoadLocalAdminStore: vi.fn(async () => null),
	};
});

const seededRecord: SeededContentRecord = {
	slug: "about",
	legacyUrl: "/about",
	title: "About",
	status: "published",
	body: "<p>about</p>",
	listingItems: [],
	paginationLinks: [],
	updatedAt: "2026-01-01T00:00:00Z",
	updatedBy: "admin@example.com",
	// audit-boundary: opaque-passthrough -- seeded test fixture; satisfies SeededContentRecord at runtime
} as unknown as SeededContentRecord;

afterEach(() => {
	clearCmsConfig();
	vi.restoreAllMocks();
});

describe("searchRuntimeContentStates — peekCmsConfig safety", () => {
	it("returns [] without throwing when peekCmsConfig() resolves to null (kills L153 OptionalChaining mutants)", async () => {
		clearCmsConfig();
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		// Original: peekCmsConfig() === null → null?.search → undefined → falsy → returns [].
		// Mutants removing optional chaining: null.search throws TypeError. This asserts no-throw.
		await expect(searchRuntimeContentStates("anything")).resolves.toEqual([]);
		expect(warnSpy).toHaveBeenCalled();
	});

	it("with search.enabled=true delegates to the local admin store (kills L153:6 ConditionalExpression:true)", async () => {
		setCmsConfig({ search: { enabled: true } });
		const searchSpy = vi.fn(async (q: string) => [
			{ slug: `hit-${q}`, legacyUrl: `/hit/${q}`, title: q } as never,
		]);
		const dispatch = await import("../src/admin-store-dispatch.js");
		(dispatch.safeLoadLocalAdminStore as unknown as ReturnType<typeof vi.fn>).mockResolvedValueOnce(
			{
				searchContentStates: searchSpy,
			} as never,
		);

		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const results = await searchRuntimeContentStates("hello");
		// Mutated `if (true)` short-circuits to [] regardless of config — assertion catches it.
		expect(results).toHaveLength(1);
		expect(searchSpy).toHaveBeenCalledWith("hello");
	});
});

describe("searchRuntimeContentStates — additional pin survivors", () => {
	it("with config missing the entire `search` key falls through gracefully (kills L153:7 OptionalChaining peekCmsConfig()?.search.enabled)", async () => {
		setCmsConfig({}); // no `search` property at all
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		// Original: cfg.search is undefined → cfg?.search?.enabled → undefined → falsy →
		//   returns []. Mutant removing the second `?`: cfg.search.enabled throws TypeError on
		//   undefined.enabled. Assertion asserts no-throw.
		await expect(searchRuntimeContentStates("q")).resolves.toEqual([]);
		expect(warnSpy).toHaveBeenCalled();
	});

	it("when search.enabled=true and the admin store is missing entirely, falls through without throwing (kills L160:6 ConditionalExpression:true and OptionalChaining store.searchContentStates)", async () => {
		setCmsConfig({ search: { enabled: true } });
		const dispatch = await import("../src/admin-store-dispatch.js");
		(dispatch.safeLoadLocalAdminStore as unknown as ReturnType<typeof vi.fn>).mockResolvedValueOnce(
			null,
		);
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		// Original: store is null → store?.searchContentStates → undefined → falsy → checks db
		//   (none) → final warn-and-return-[].
		// Mutant L160:6 ConditionalExpression:true: enters the branch unconditionally → null.searchContentStates() throws.
		// Mutant L160:6 OptionalChaining store.searchContentStates: null.searchContentStates throws.
		await expect(searchRuntimeContentStates("q")).resolves.toEqual([]);
		expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining("no FTS-capable store"));
	});
});

describe("getRuntimeContentStateByPath — path normalization & lookup", () => {
	it("finds a seeded record by exact /-prefixed pathname (kills L171 BlockStatement, L172:25 endsWith, L174 LogicalOperator/ArrowFunction, L16:3 ArrowFunction)", async () => {
		setCmsConfig({ seedPages: [{ ...seededRecord }] });
		const { getRuntimeContentStateByPath } = await import("../src/runtime-page-store.js");
		// Original: startsWith("/") true → normalizedPath="/about" → finds record.
		// L172:25 MethodExpression endsWith: "/about".endsWith("/")=false →
		//   normalizedPath="/" + "/about" = "//about" → no match → null.
		// L171 BlockStatement {}: returns undefined → assertion fails.
		// L174 LogicalOperator &&: returns null when record found.
		// L174 ArrowFunction () => undefined: find returns undefined → returns null.
		// L16 ArrowFunction () => undefined: seededContentRecords contains undefined entries →
		//   record.legacyUrl access throws TypeError on .find().
		const found = await getRuntimeContentStateByPath("/about");
		expect(found).not.toBeNull();
		expect(found?.legacyUrl).toBe("/about");
	});

	it("picks the legacyUrl-matching record from a multi-record list (kills L174:34 ConditionalExpression:true)", async () => {
		const other: SeededContentRecord = {
			...seededRecord,
			slug: "other",
			legacyUrl: "/other",
			title: "Other",
		} as SeededContentRecord;
		// Order matters: 'other' first, 'about' second. Mutant find(record => true) returns the first.
		setCmsConfig({ seedPages: [other, { ...seededRecord }] });
		const { getRuntimeContentStateByPath } = await import("../src/runtime-page-store.js");
		const found = await getRuntimeContentStateByPath("/about");
		// Original predicate filters to legacyUrl="/about" → seededRecord.
		// Mutant `find(() => true)` returns 'other' (index 0).
		expect(found?.legacyUrl).toBe("/about");
		expect(found?.slug).toBe("about");
	});

	it("prepends '/' to a bare pathname before lookup (kills L172:45 StringLiteral)", async () => {
		setCmsConfig({ seedPages: [{ ...seededRecord }] });
		const { getRuntimeContentStateByPath } = await import("../src/runtime-page-store.js");
		// Original: startsWith("/") false → normalizedPath="/about" → finds.
		// L172:45 StringLiteral "": startsWith("") true → normalizedPath="about" (no slash) →
		//   no match against legacyUrl="/about" → null.
		const found = await getRuntimeContentStateByPath("about");
		expect(found?.legacyUrl).toBe("/about");
	});
});

describe("getSeededContentRecords — narrowing ternaries", () => {
	it("propagates string-typed kind/scheduledAt through the narrowing ternaries (kills L19/L23 ConditionalExpression:false, EqualityOperator !==, StringLiteral)", async () => {
		const fullyTyped = {
			...seededRecord,
			kind: "post",
			scheduledAt: "2026-01-01T00:00:00Z",
		} as unknown as SeededContentRecord;
		setCmsConfig({ seedPages: [fullyTyped] });
		const { listRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const records = await listRuntimeContentStates();
		const r = records[0];
		// Original (typeof === "string"): both fields preserved as strings.
		// Mutants ConditionalExpression:false / EqualityOperator !== / StringLiteral "":
		// flip the narrowing to the undefined branch → both fields become undefined.
		expect(r.kind).toBe("post");
		expect(r.scheduledAt).toBe("2026-01-01T00:00:00Z");
	});

	it("non-string kind/scheduledAt are scrubbed to undefined (kills L19/L23 ConditionalExpression:true)", async () => {
		const mistyped = {
			...seededRecord,
			kind: 42 as unknown as string,
			scheduledAt: { not: "a string" } as unknown as string,
		} as unknown as SeededContentRecord;
		setCmsConfig({ seedPages: [mistyped] });
		const { listRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const records = await listRuntimeContentStates();
		const r = records[0];
		// Original: typeof !== "string" → undefined.
		// Mutant ConditionalExpression:true: always returns the raw page.kind / page.scheduledAt →
		//   the non-string values leak through, failing strict-undefined assertion.
		expect(r.kind).toBeUndefined();
		expect(r.scheduledAt).toBeUndefined();
	});
});

describe("searchRuntimeContentStates — D1 search delegation", () => {
	it("delegates to searchD1ContentStates when search is enabled and a D1 binding is present (kills L164:6 ConditionalExpression:false)", async () => {
		setCmsConfig({ search: { enabled: true } });
		const fakeRow = { slug: "d1-hit" } as never;
		const d1 = await import("../src/d1-store-content.js");
		const spy = vi.spyOn(d1, "searchD1ContentStates").mockResolvedValueOnce([fakeRow]);
		const locals = {
			runtime: { env: { DB: { prepare: () => ({}) } } },
		} as unknown as App.Locals;
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const results = await searchRuntimeContentStates("query", locals);
		// Original enters the `if (db)` branch and calls searchD1ContentStates.
		// Mutant L164:6 ConditionalExpression:false skips → warn-and-return-[].
		expect(spy).toHaveBeenCalledWith(expect.anything(), "query");
		expect(results).toEqual([fakeRow]);
	});
});

describe("getRuntimeTranslationState — fallback path body", () => {
	it("returns the fallback string from the static read store (kills L185 BlockStatement)", async () => {
		setCmsConfig();
		const { getRuntimeTranslationState } = await import("../src/runtime-page-store.js");
		// Static read store's getEffectiveTranslationState(route, fallback) returns the
		// `fallback` argument verbatim. L185 mutated body returns undefined → assertion fails.
		const state = await getRuntimeTranslationState("/some/route", "in_progress");
		expect(state).toBe("in_progress");
	});
});

tests/locale-links.test.ts.source:
import {
	canonicalUrlForRoute,
	getAlternateLinksForEnglishRoute,
	getLocaleSwitchTargets,
	registerCms,
	sanitizeCanonicalUrl,
} from "@astropress-diy/astropress";
import { beforeEach, describe, expect, it } from "vitest";

beforeEach(() => {
	registerCms({
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [
			{
				route: "/es/impacto",
				locale: "es",
				englishSourceUrl: "/impact",
				translationState: "published",
			},
			{
				route: "/es",
				locale: "es",
				englishSourceUrl: "/",
				translationState: "published",
			},
			{
				route: "/es/paisajes-comestibles",
				locale: "es",
				englishSourceUrl: "/en/edible-landscapes",
				translationState: "published",
			},
			{
				route: "/es/contacto",
				locale: "es",
				englishSourceUrl: "/en/contact",
				translationState: "published",
			},
		],
	});
});

describe("canonicalUrlForRoute()", () => {
	it("returns the full absolute URL for a given route", () => {
		expect(canonicalUrlForRoute("/impact")).toBe("https://example.com/impact/");
	});

	it("handles the root route without double slash", () => {
		expect(canonicalUrlForRoute("/")).toBe("https://example.com/");
	});

	it("appends a trailing slash to non-root routes", () => {
		expect(canonicalUrlForRoute("/en/education")).toBe("https://example.com/en/education/");
	});
});

describe("getAlternateLinksForEnglishRoute()", () => {
	it("returns EN + ES alternates for a known translated route (/impact → /es/impacto)", () => {
		const links = getAlternateLinksForEnglishRoute("/impact");
		expect(links).toHaveLength(2);
		const hreflangs = links.map((l) => l.hreflang);
		expect(hreflangs).toContain("en");
		expect(hreflangs).toContain("es");
		const esLink = links.find((l) => l.hreflang === "es");
		expect(esLink?.href).toContain("/es/impacto");
	});

	it("returns EN + ES alternates for the root route (/ → /es)", () => {
		const links = getAlternateLinksForEnglishRoute("/");
		expect(links).toHaveLength(2);
		const esLink = links.find((l) => l.hreflang === "es");
		expect(esLink?.href).toContain("/es");
	});

	it("returns EN + ES alternates for a core service route", () => {
		const links = getAlternateLinksForEnglishRoute("/en/edible-landscapes");
		expect(links).toHaveLength(2);
		const esLink = links.find((l) => l.hreflang === "es");
		expect(esLink?.href).toContain("/es/paisajes-comestibles");
	});

	it("returns empty array for an unknown route", () => {
		const links = getAlternateLinksForEnglishRoute("/non-existent-page");
		expect(links).toHaveLength(0);
	});

	it("filters out non-'es' locale entries (pins L21 locale === 'es' check)", () => {
		registerCms({
			siteUrl: "https://example.com",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [
				{
					route: "/fr/impact",
					locale: "fr",
					englishSourceUrl: "/impact",
					translationState: "published",
				},
			],
		});
		const links = getAlternateLinksForEnglishRoute("/impact");
		expect(links).toHaveLength(0);
	});

	it("filters out non-published translation states (pins L22 isPublished check)", () => {
		registerCms({
			siteUrl: "https://example.com",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [
				{
					route: "/es/impacto-draft",
					locale: "es",
					englishSourceUrl: "/impact",
					translationState: "draft",
				},
			],
		});
		const links = getAlternateLinksForEnglishRoute("/impact");
		expect(links).toHaveLength(0);
	});
});

describe("sanitizeCanonicalUrl()", () => {
	it("returns absolute URL for a known route when no override is provided", () => {
		const url = sanitizeCanonicalUrl(undefined, "/en/impact");
		expect(url).toBe("https://example.com/en/impact/");
	});

	it("strips query string and hash from an override URL", () => {
		const url = sanitizeCanonicalUrl(
			"https://example.com/en/impact?utm_source=test#section",
			"/en/impact",
		);
		expect(url).not.toContain("utm_source");
		expect(url).not.toContain("#section");
		expect(url).toContain("example.com/en/impact");
	});

	it("normalizes trailing slash on override URL", () => {
		const url = sanitizeCanonicalUrl("https://example.com/en/impact", "/en/impact");
		expect(url).toMatch(/\/en\/impact\/$/);
	});

	it("preserves '/' without adding extra slash when override URL is the site root", () => {
		// Covers the `parsed.pathname === "/"` ternary true branch on line 46
		const url = sanitizeCanonicalUrl("https://example.com/", "/");
		expect(url).toBe("https://example.com/");
	});

	it("returns fallback canonical when value is undefined (pins L42 !value check)", () => {
		const url = sanitizeCanonicalUrl(undefined, "/fallback-route");
		expect(url).toContain("/fallback-route");
	});

	it("returns fallback canonical when value is empty string (pins L42 !value check)", () => {
		const url = sanitizeCanonicalUrl("", "/fallback-route");
		expect(url).toContain("/fallback-route");
	});
});

describe("getLocaleSwitchTargets isLocalePath survivors", () => {
	it("uses currentPath when lang='es' and path is exactly '/es' (pins L66 path === '/es')", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es",
		});
		expect(targets.es).toBe("/es");
	});

	it("uses currentPath when lang='es' and path starts with '/es/' (pins L66 startsWith)", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es/sobre/",
		});
		expect(targets.es).toBe("/es/sobre/");
	});

	it("does NOT use currentPath when lang='es' but path is in EN-space (e.g. '/about')", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/about",
		});
		// Default fallback to /es because /about is not an es-prefixed path.
		expect(targets.es).toBe("/es");
	});

	it("does NOT use currentPath when lang='es' and path is '/es-mx' (similar prefix but not '/es' or '/es/')", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es-mx/about",
		});
		expect(targets.es).toBe("/es");
	});
});

describe("getLocaleSwitchTargets()", () => {
	it("uses explicit alternate links for reviewed EN/ES route pairs", () => {
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/contact",
			alternateLinks: [
				{ hreflang: "en", href: "https://example.com/en/contact/" },
				{ hreflang: "es", href: "https://example.com/es/contacto/" },
			],
		});

		expect(targets).toEqual({
			en: "/en/contact/",
			es: "/es/contacto/",
		});
	});

	it("falls back to locale homes when no reviewed alternate exists", () => {
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/about",
			alternateLinks: [],
		});

		expect(targets).toEqual({
			en: "/en/about",
			es: "/es",
		});
	});

	it("sets the current path for the es locale when on an es route (isLocalePath es branch)", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es/impacto",
			alternateLinks: [],
		});
		expect(targets.es).toBe("/es/impacto");
		expect(targets.en).toBe("/en");
	});

	it("uses empty array fallback when alternateLinks is omitted (?? [] branch)", () => {
		const targets = getLocaleSwitchTargets({ lang: "en" });
		expect(targets).toEqual({ en: "/en", es: "/es" });
	});

	it("redirects root path '/' to '/en' when viewed from es locale", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es/inicio",
			alternateLinks: [{ hreflang: "en", href: "https://example.com/" }],
		});
		expect(targets.en).toBe("/en");
	});

	it("skips alternate links with non-standard hreflang (fr is ignored)", () => {
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/about",
			alternateLinks: [
				{ hreflang: "fr", href: "https://example.com/fr/about/" },
				{ hreflang: "es", href: "https://example.com/es/sobre/" },
			],
		});
		// fr link ignored; es link used
		expect(targets.es).toBe("/es/sobre/");
		expect(targets).not.toHaveProperty("fr");
	});

	it("preserves a non-empty override URL distinct from the fallback (pins L42 !value → true)", () => {
		// Mutating `if (!value)` to `if (true)` would discard the override URL
		// and always return the fallback canonical. With value="/override" and
		// fallback="/fallback", the original keeps the override.
		const url = sanitizeCanonicalUrl("https://example.com/override", "/fallback");
		expect(url).toContain("/override");
		expect(url).not.toContain("/fallback");
	});

	it("keeps targets.en at /en when lang='en' and currentPath is an es-prefixed path (pins L69 startsWith→endsWith)", () => {
		// For path "/es/foo": startsWith("/es/") is true → isLocalePath("/es/foo", "en")
		// returns false → currentPath is NOT used for targets.en. Mutating
		// startsWith to endsWith inverts the check ("/es/foo" doesn't end with "/es/")
		// so isLocalePath would wrongly return true and assign /es/foo to targets.en.
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/es/foo",
		});
		expect(targets.en).toBe("/en");
	});

	it("does not rewrite targets.en to /en when hreflang='en' but path is not '/' (pins L93 path === '/' clause)", () => {
		// path === "/" replaced with `true` would make any en alternate href rewrite
		// to "/en" regardless of path. The original keeps the actual path "/en/contact/".
		const targets = getLocaleSwitchTargets({
			lang: "es",
			alternateLinks: [{ hreflang: "en", href: "https://example.com/en/contact/" }],
		});
		expect(targets.en).toBe("/en/contact/");
	});

	it("does not rewrite targets.en to /en when lang='en' (pins L93 input.lang === 'es' clause)", () => {
		// input.lang === "es" replaced with `true` would fire the rewrite even on
		// an EN page viewing root. Original keeps targets.en as the raw path "/".
		const targets = getLocaleSwitchTargets({
			lang: "en",
			alternateLinks: [{ hreflang: "en", href: "https://example.com/" }],
		});
		expect(targets.en).toBe("/");
	});

	it("does not rewrite targets.es to /en when hreflang='es' and lang='es' (pins L93 hreflang === 'en' clause + first &&)", () => {
		// Mutating `hreflang === "en"` to `true` would fire the /en rewrite even
		// for an ES alternate link, and mutating the first `&&` to `||` would
		// short-circuit to /en when hreflang is "en" regardless of path/lang.
		// With hreflang="es", path="/", lang="es": original target.es is "/"; the
		// mutants would set target.es to "/en".
		const targets = getLocaleSwitchTargets({
			lang: "es",
			alternateLinks: [{ hreflang: "es", href: "https://example.com/" }],
		});
		expect(targets.es).toBe("/");
	});

	it("falls back to returning href as-is when URL parse fails (pathFromHref catch branch)", () => {
		const badHref = "http://[invalid-host]/path/";
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/about",
			alternateLinks: [{ hreflang: "es", href: badHref }],
		});
		// The catch branch returns the raw href string as the path
		expect(targets.es).toBe(badHref);
	});
});

tests/sqlite-runtime-settings.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { beforeEach, describe, expect, it } from "vitest";
import type { Actor } from "../src/persistence-types";
import { createSqliteSettingsStore } from "../src/sqlite-runtime/settings";
import type { AstropressSqliteDatabaseLike } from "../src/sqlite-runtime/utils";
import { makeDb, STANDARD_ACTOR } from "./helpers/make-db.js";

const actor: Actor = STANDARD_ACTOR;

let db: DatabaseSync;
let store: ReturnType<typeof createSqliteSettingsStore>;

beforeEach(() => {
	db = makeDb();
	store = createSqliteSettingsStore(() => db as unknown as AstropressSqliteDatabaseLike);
});

function latestAudit(action: string) {
	return db
		.prepare(
			"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events WHERE action = ? ORDER BY id DESC LIMIT 1",
		)
		.get(action) as Record<string, unknown> | undefined;
}

// ---------------------------------------------------------------------------
// Redirect repository
// ---------------------------------------------------------------------------

describe("createSqliteSettingsStore — redirect repository", () => {
	it("createRedirectRule writes an active row and emits a 'redirect.create' audit with resource_type='redirect' and the source-path target_id", async () => {
		const result = await store.sqliteRedirectRepository.createRedirectRule(
			{ sourcePath: "/old", targetPath: "/new", statusCode: 301 },
			actor,
		);
		expect(result).toEqual({
			ok: true,
			rule: { sourcePath: "/old", targetPath: "/new", statusCode: 301 },
		});

		const row = db
			.prepare(
				"SELECT source_path, target_path, status_code, deleted_at, created_by FROM redirect_rules WHERE source_path = '/old'",
			)
			.get() as Record<string, unknown>;
		expect(row).toMatchObject({
			source_path: "/old",
			target_path: "/new",
			status_code: 301,
			deleted_at: null,
			created_by: actor.email,
		});

		const audit = latestAudit("redirect.create");
		expect(audit).toMatchObject({
			user_email: actor.email,
			action: "redirect.create",
			resource_type: "redirect",
			resource_id: "/old",
			summary: "Created redirect /old -> /new (301).",
		});
	});

	it("getRedirectRules returns only non-deleted rows", async () => {
		await store.sqliteRedirectRepository.createRedirectRule(
			{ sourcePath: "/keep", targetPath: "/k", statusCode: 301 },
			actor,
		);
		await store.sqliteRedirectRepository.createRedirectRule(
			{ sourcePath: "/drop", targetPath: "/d", statusCode: 301 },
			actor,
		);
		await store.sqliteRedirectRepository.deleteRedirectRule("/drop", actor);

		const rules = await store.sqliteRedirectRepository.getRedirectRules();
		expect(rules.map((r) => r.sourcePath)).toEqual(["/keep"]);
	});

	it("deleteRedirectRule soft-deletes the row, returns ok, and emits a 'redirect.delete' audit", async () => {
		await store.sqliteRedirectRepository.createRedirectRule(
			{ sourcePath: "/old", targetPath: "/new", statusCode: 301 },
			actor,
		);
		const result = await store.sqliteRedirectRepository.deleteRedirectRule("/old", actor);
		expect(result).toEqual({ ok: true });

		const audit = latestAudit("redirect.delete");
		expect(audit).toMatchObject({
			action: "redirect.delete",
			resource_type: "redirect",
			resource_id: "/old",
			summary: "Deleted redirect /old.",
		});

		const row = db
			.prepare("SELECT deleted_at FROM redirect_rules WHERE source_path = '/old'")
			.get() as { deleted_at: string | null };
		expect(row.deleted_at).not.toBeNull();
	});

	it("deleteRedirectRule returns ok=false and emits NO audit when the rule is absent", async () => {
		const result = await store.sqliteRedirectRepository.deleteRedirectRule("/never", actor);
		expect(result).toEqual({ ok: false });
		expect(latestAudit("redirect.delete")).toBeUndefined();
	});
});

// ---------------------------------------------------------------------------
// Comment repository
// ---------------------------------------------------------------------------

describe("createSqliteSettingsStore — comment repository", () => {
	it("submitPublicComment persists the comment row with email/body NULL when omitted", async () => {
		const result = await store.sqliteCommentRepository.submitPublicComment({
			author: "Anon",
			route: "/post-a",
		});
		expect(result.ok).toBe(true);

		const row = db
			.prepare("SELECT author, email, body, route, status, policy FROM comments WHERE id = ?")
			.get(result.ok ? result.comment.id : "x") as Record<string, unknown>;
		expect(row).toMatchObject({
			author: "Anon",
			email: null,
			body: null,
			route: "/post-a",
			status: "pending",
			policy: "open-moderated",
		});
	});

	it("submitPublicComment uses caller-provided submittedAt and returns it on the comment", async () => {
		const ts = "2026-04-01T00:00:00.000Z";
		const result = await store.sqliteCommentRepository.submitPublicComment({
			author: "Anon",
			route: "/r",
			submittedAt: ts,
		});
		expect(result.ok).toBe(true);
		if (result.ok) expect(result.comment.submittedAt).toBe(ts);
	});

	it("getComments returns email/body as undefined (not null) for NULL DB rows", async () => {
		await store.sqliteCommentRepository.submitPublicComment({ author: "Anon", route: "/r" });
		const all = await store.sqliteCommentRepository.getComments();
		expect(all).toHaveLength(1);
		expect(all[0]?.email).toBeUndefined();
		expect(all[0]?.body).toBeUndefined();
	});

	it("moderateComment changes status, returns ok, and emits a 'comment.moderate' audit with resource_type='comment'", async () => {
		const submission = await store.sqliteCommentRepository.submitPublicComment({
			author: "Anon",
			route: "/post-x",
			body: "hi",
		});
		expect(submission.ok).toBe(true);
		if (!submission.ok) return;

		const result = await store.sqliteCommentRepository.moderateComment(
			submission.comment.id,
			"approved",
			actor,
		);
		expect(result).toEqual({ ok: true });

		const row = db
			.prepare("SELECT status FROM comments WHERE id = ?")
			.get(submission.comment.id) as { status: string };
		expect(row.status).toBe("approved");

		const audit = latestAudit("comment.moderate");
		expect(audit).toMatchObject({
			action: "comment.moderate",
			resource_type: "comment",
			resource_id: submission.comment.id,
			summary: "Marked /post-x as approved.",
		});
	});

	it("moderateComment returns ok=false and emits NO audit when the comment id is absent", async () => {
		const result = await store.sqliteCommentRepository.moderateComment(
			"no-such",
			"approved",
			actor,
		);
		expect(result).toMatchObject({ ok: false });
		expect(latestAudit("comment.moderate")).toBeUndefined();
	});
});

// ---------------------------------------------------------------------------
// Translation repository
// ---------------------------------------------------------------------------

describe("createSqliteSettingsStore — translation repository", () => {
	it("updateTranslationState persists state and emits 'translation.update' audit with resource_type='content' and the documented summary", async () => {
		const result = await store.sqliteTranslationRepository.updateTranslationState(
			"/es/about",
			"published",
			actor,
		);
		expect(result).toEqual({ ok: true });

		const row = db
			.prepare("SELECT state, updated_by FROM translation_overrides WHERE route = '/es/about'")
			.get() as Record<string, unknown>;
		expect(row).toMatchObject({
			state: "published",
			updated_by: actor.email,
		});

		const audit = latestAudit("translation.update");
		expect(audit).toMatchObject({
			action: "translation.update",
			resource_type: "content",
			resource_id: "/es/about",
			summary: "Updated translation state for /es/about to published.",
		});
	});

	it("getEffectiveTranslationState returns the persisted state when present", async () => {
		await store.sqliteTranslationRepository.updateTranslationState("/es/about", "reviewed", actor);
		expect(store.sqliteTranslationRepository.getEffectiveTranslationState("/es/about")).toBe(
			"reviewed",
		);
	});
});

// ---------------------------------------------------------------------------
// Settings repository
// ---------------------------------------------------------------------------

describe("createSqliteSettingsStore — settings repository", () => {
	it("getSettings returns defaultSiteSettings when no row exists", async () => {
		const settings = await store.sqliteSettingsRepository.getSettings();
		expect(settings).toBeDefined();
		expect(settings.adminSlug).toBe("ap-admin");
	});

	it("saveSettings upserts a row and emits 'settings.update' audit with resource_type='auth' and resource_id='site-settings'", async () => {
		const result = await store.sqliteSettingsRepository.saveSettings(
			{
				siteTitle: "Astro",
				siteTagline: "Press",
				donationUrl: "https://example.com/donate",
				newsletterEnabled: true,
				commentsDefaultPolicy: "open-moderated",
				adminSlug: "secret-admin",
			},
			actor,
		);
		expect(result.ok).toBe(true);

		const row = db
			.prepare(
				"SELECT site_title, site_tagline, donation_url, newsletter_enabled, comments_default_policy, admin_slug, updated_by FROM site_settings WHERE id = 1",
			)
			.get() as Record<string, unknown>;
		expect(row).toMatchObject({
			site_title: "Astro",
			site_tagline: "Press",
			donation_url: "https://example.com/donate",
			newsletter_enabled: 1,
			comments_default_policy: "open-moderated",
			admin_slug: "secret-admin",
			updated_by: actor.email,
		});

		const audit = latestAudit("settings.update");
		expect(audit).toMatchObject({
			action: "settings.update",
			resource_type: "auth",
			resource_id: "site-settings",
			summary: "Updated site settings.",
		});
	});

	it("saveSettings persists newsletterEnabled=false as 0 (boolean → 1/0 round-trip)", async () => {
		await store.sqliteSettingsRepository.saveSettings(
			{
				siteTitle: "X",
				siteTagline: "Y",
				donationUrl: "",
				newsletterEnabled: false,
				commentsDefaultPolicy: "disabled",
				adminSlug: "ap-admin",
			},
			actor,
		);
		const row = db.prepare("SELECT newsletter_enabled FROM site_settings WHERE id = 1").get() as {
			newsletter_enabled: number;
		};
		expect(row.newsletter_enabled).toBe(0);

		const settings = await store.sqliteSettingsRepository.getSettings();
		expect(settings.newsletterEnabled).toBe(false);
	});

	it("getSettings reads back exactly the persisted shape (round-trip)", async () => {
		await store.sqliteSettingsRepository.saveSettings(
			{
				siteTitle: "Astro",
				siteTagline: "Press",
				donationUrl: "https://example.com/donate",
				newsletterEnabled: true,
				commentsDefaultPolicy: "open-moderated",
				adminSlug: "custom-slug",
			},
			actor,
		);
		const settings = await store.sqliteSettingsRepository.getSettings();
		expect(settings).toEqual({
			siteTitle: "Astro",
			siteTagline: "Press",
			donationUrl: "https://example.com/donate",
			newsletterEnabled: true,
			commentsDefaultPolicy: "open-moderated",
			adminSlug: "custom-slug",
		});
	});
});

