/**
 * Each parse function pushes errors with specific path + message strings.
 * These tests assert the exact path and message for every error branch so
 * StringLiteral/ObjectLiteral mutations on the errors.push() calls die.
 */
import { describe, expect, it } from "vitest";
import { parseSections } from "../../src/sections/schema";

function expectErr(input: unknown, path: string, message: string) {
	const r = parseSections(input);
	expect(r.ok).toBe(false);
	if (!r.ok) {
		const found = r.errors.find((e) => e.path === path);
		if (!found) {
			throw new Error(`expected error at path '${path}' but got: ${JSON.stringify(r.errors)}`);
		}
		expect(found.message).toBe(message);
	}
}

describe("schema error paths — exact path + message coverage", () => {
	it("CTA missing label", () => {
		expectErr(
			[{ id: "h", kind: "hero", headline: "x", primaryCta: { href: "/p" } }],
			"$[0].primaryCta.label",
			"label is required",
		);
	});

	it("CTA missing href", () => {
		expectErr(
			[{ id: "h", kind: "hero", headline: "x", primaryCta: { label: "L" } }],
			"$[0].primaryCta.href",
			"href is required",
		);
	});

	it("CTA non-object", () => {
		expectErr(
			[{ id: "h", kind: "hero", headline: "x", primaryCta: 7 }],
			"$[0].primaryCta",
			"must be an object with label + href",
		);
	});

	it("hero subhead non-string", () => {
		expectErr(
			[{ id: "h", kind: "hero", headline: "x", subhead: 5 }],
			"$[0].subhead",
			"subhead must be string",
		);
	});

	it("hero mediaId non-string", () => {
		expectErr(
			[{ id: "h", kind: "hero", headline: "x", mediaId: 5 }],
			"$[0].mediaId",
			"mediaId must be string",
		);
	});

	it("hero headline missing", () => {
		expectErr(
			[{ id: "h", kind: "hero", alignment: "start" }],
			"$[0].headline",
			"headline is required",
		);
	});

	it("feature-grid heading missing", () => {
		expectErr(
			[{ id: "f", kind: "feature-grid", items: [] }],
			"$[0].heading",
			"heading is required",
		);
	});

	it("feature-grid items not array", () => {
		expectErr(
			[{ id: "f", kind: "feature-grid", heading: "X", items: "no" }],
			"$[0].items",
			"items must be an array",
		);
	});

	it("feature-grid item not object", () => {
		expectErr(
			[{ id: "f", kind: "feature-grid", heading: "X", items: ["nope"] }],
			"$[0].items[0]",
			"must be object",
		);
	});

	it("feature-grid item.title missing", () => {
		expectErr(
			[
				{
					id: "f",
					kind: "feature-grid",
					heading: "X",
					items: [{ body: "b" }],
				},
			],
			"$[0].items[0].title",
			"title required",
		);
	});

	it("feature-grid item.body missing", () => {
		expectErr(
			[
				{
					id: "f",
					kind: "feature-grid",
					heading: "X",
					items: [{ title: "t" }],
				},
			],
			"$[0].items[0].body",
			"body required",
		);
	});

	it("testimonials ids required when source=ids", () => {
		expectErr(
			[{ id: "t", kind: "testimonials", source: "ids", layout: "grid" }],
			"$[0].ids",
			"ids[] required when source=ids",
		);
	});

	it("testimonials ids empty array also rejected", () => {
		expectErr(
			[
				{
					id: "t",
					kind: "testimonials",
					source: "ids",
					layout: "grid",
					ids: [],
				},
			],
			"$[0].ids",
			"ids[] required when source=ids",
		);
	});

	it("cta-banner headline missing", () => {
		expectErr(
			[
				{
					id: "c",
					kind: "cta-banner",
					primaryCta: { label: "x", href: "/" },
				},
			],
			"$[0].headline",
			"headline required",
		);
	});

	it("cta-banner primaryCta missing → label error", () => {
		const r = parseSections([{ id: "c", kind: "cta-banner", headline: "H" }]);
		expect(r.ok).toBe(false);
		if (!r.ok) {
			expect(r.errors.some((e) => e.path === "$[0].primaryCta")).toBe(true);
		}
	});

	it("image-text heading missing", () => {
		expectErr(
			[
				{
					id: "i",
					kind: "image-text",
					body: "b",
					mediaId: "",
					imageSide: "start",
				},
			],
			"$[0].heading",
			"heading required",
		);
	});

	it("image-text body missing", () => {
		expectErr(
			[
				{
					id: "i",
					kind: "image-text",
					heading: "H",
					mediaId: "",
					imageSide: "start",
				},
			],
			"$[0].body",
			"body required",
		);
	});

	it("image-text mediaId non-string", () => {
		expectErr(
			[
				{
					id: "i",
					kind: "image-text",
					heading: "H",
					body: "B",
					mediaId: 5,
				},
			],
			"$[0].mediaId",
			"mediaId must be string",
		);
	});

	it("faq items not array", () => {
		expectErr([{ id: "f", kind: "faq", items: "no" }], "$[0].items", "items must be an array");
	});

	it("faq item not object", () => {
		expectErr([{ id: "f", kind: "faq", items: ["nope"] }], "$[0].items[0]", "must be object");
	});

	it("faq item.question missing", () => {
		expectErr(
			[{ id: "f", kind: "faq", items: [{ answer: "a" }] }],
			"$[0].items[0].question",
			"question required",
		);
	});

	it("faq item.answer missing", () => {
		expectErr(
			[{ id: "f", kind: "faq", items: [{ question: "q" }] }],
			"$[0].items[0].answer",
			"answer required",
		);
	});

	it("gallery mediaIds non-array", () => {
		expectErr(
			[{ id: "g", kind: "gallery", mediaIds: "no" }],
			"$[0].mediaIds",
			"mediaIds must be string[]",
		);
	});

	it("gallery mediaIds with non-string", () => {
		expectErr(
			[{ id: "g", kind: "gallery", mediaIds: [1] }],
			"$[0].mediaIds",
			"mediaIds must be string[]",
		);
	});

	it("rich-text html non-string", () => {
		expectErr([{ id: "r", kind: "rich-text", html: 5 }], "$[0].html", "html must be a string");
	});

	it("section id missing → exact message", () => {
		expectErr([{ kind: "hero", headline: "x", alignment: "start" }], "$[0].id", "id is required");
	});

	it("section non-object → exact message", () => {
		expectErr(["bad"], "$[0]", "section must be an object");
	});

	it("unknown kind error message includes kind value", () => {
		const r = parseSections([{ id: "x", kind: "what" }]);
		expect(r.ok).toBe(false);
		if (!r.ok) {
			const e = r.errors.find((x) => x.path === "$[0].kind");
			expect(e?.message).toBe("unknown section kind: what");
		}
	});

	it("top-level non-array message", () => {
		const r = parseSections({ random: 1 });
		expect(r.ok).toBe(false);
		if (!r.ok) expect(r.errors[0].message).toBe("sections payload must be an array");
	});

	it("intro included on success only when non-empty (string truthy guard)", () => {
		const r = parseSections([
			{
				id: "f",
				kind: "feature-grid",
				heading: "H",
				intro: "x",
				items: [],
			},
		]);
		expect(r.ok).toBe(true);
		if (r.ok && r.sections[0].kind === "feature-grid") {
			expect(r.sections[0].intro).toBe("x");
		}
	});

	it("testimonials heading included exactly when non-empty (truthy guard)", () => {
		const r1 = parseSections([
			{
				id: "t",
				kind: "testimonials",
				source: "approved",
				layout: "grid",
				heading: "X",
			},
		]);
		if (r1.ok && r1.sections[0].kind === "testimonials") {
			expect(r1.sections[0].heading).toBe("X");
		}
		const r2 = parseSections([
			{
				id: "t",
				kind: "testimonials",
				source: "approved",
				layout: "grid",
				heading: "",
			},
		]);
		if (r2.ok && r2.sections[0].kind === "testimonials") {
			expect("heading" in r2.sections[0]).toBe(false);
		}
	});

	it("cta-banner secondaryCta validated when present", () => {
		const r = parseSections([
			{
				id: "c",
				kind: "cta-banner",
				headline: "H",
				primaryCta: { label: "x", href: "/" },
				secondaryCta: { label: "S", href: "/s" },
			},
		]);
		expect(r.ok).toBe(true);
		if (r.ok && r.sections[0].kind === "cta-banner") {
			expect(r.sections[0].secondaryCta?.label).toBe("S");
		}
	});

	it("cta-banner secondaryCta with bad shape collects error", () => {
		const r = parseSections([
			{
				id: "c",
				kind: "cta-banner",
				headline: "H",
				primaryCta: { label: "x", href: "/" },
				secondaryCta: { label: "" },
			},
		]);
		expect(r.ok).toBe(false);
		if (!r.ok) expect(r.errors.some((e) => e.path.startsWith("$[0].secondaryCta"))).toBe(true);
	});

	it("hero secondaryCta with bad shape collects error", () => {
		const r = parseSections([
			{
				id: "h",
				kind: "hero",
				headline: "x",
				secondaryCta: { href: "/p" },
			},
		]);
		expect(r.ok).toBe(false);
		if (!r.ok) expect(r.errors.some((e) => e.path === "$[0].secondaryCta.label")).toBe(true);
	});

	it("rich-text returns RichTextSection with kind preserved", () => {
		const r = parseSections([{ id: "r", kind: "rich-text", html: "<p>x</p>" }]);
		expect(r.ok).toBe(true);
		if (r.ok) {
			expect(r.sections[0]).toEqual({
				id: "r",
				kind: "rich-text",
				html: "<p>x</p>",
			});
		}
	});

	it("gallery preserves mediaIds array reference contents", () => {
		const r = parseSections([
			{
				id: "g",
				kind: "gallery",
				mediaIds: ["a", "b"],
				columns: 4,
			},
		]);
		expect(r.ok).toBe(true);
		if (r.ok && r.sections[0].kind === "gallery") {
			expect(r.sections[0].mediaIds).toEqual(["a", "b"]);
		}
	});

	it("faq preserves item question + answer pairs", () => {
		const r = parseSections([
			{
				id: "f",
				kind: "faq",
				items: [
					{ question: "Q1", answer: "A1" },
					{ question: "Q2", answer: "A2" },
				],
			},
		]);
		if (r.ok && r.sections[0].kind === "faq") {
			expect(r.sections[0].items).toEqual([
				{ question: "Q1", answer: "A1" },
				{ question: "Q2", answer: "A2" },
			]);
		}
	});

	it("feature-grid preserves icon when truthy non-empty", () => {
		const r = parseSections([
			{
				id: "f",
				kind: "feature-grid",
				heading: "H",
				items: [{ icon: "*", title: "T", body: "B" }],
			},
		]);
		if (r.ok && r.sections[0].kind === "feature-grid") {
			expect(r.sections[0].items[0]).toEqual({
				icon: "*",
				title: "T",
				body: "B",
			});
		}
	});

	it("hero preserved id stays as the input string verbatim", () => {
		const r = parseSections([{ id: "abc-123", kind: "hero", headline: "x", alignment: "start" }]);
		if (r.ok) expect(r.sections[0].id).toBe("abc-123");
	});

	it("testimonials full-shape round-trip preserves source + layout + ids", () => {
		const r = parseSections([
			{
				id: "t",
				kind: "testimonials",
				source: "ids",
				ids: ["x", "y"],
				layout: "carousel",
				heading: "H",
			},
		]);
		if (r.ok && r.sections[0].kind === "testimonials") {
			expect(r.sections[0]).toEqual({
				id: "t",
				kind: "testimonials",
				source: "ids",
				layout: "carousel",
				heading: "H",
				ids: ["x", "y"],
			});
		}
	});
});

tests/admin-ui.test.ts.source:
import { afterEach, describe, expect, it } from "vitest";

import { buildAstropressAdminDocumentTitle } from "../src/admin-branding";
import { adminLabels, getAdminLabel, resolveAstropressAdminUiConfig } from "../src/admin-ui";
import { getCmsConfig, type peekCmsConfig, registerCms } from "../src/config";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

function restoreConfig(config: ReturnType<typeof peekCmsConfig>) {
	(globalThis as typeof globalThis & { [CMS_CONFIG_KEY]?: unknown })[CMS_CONFIG_KEY] =
		config ?? null;
}

afterEach(() => {
	restoreConfig(null);
});

describe("getCmsConfig — uninitialized state", () => {
	it("throws when getCmsConfig is called before registerCms", () => {
		restoreConfig(null);
		expect(() => getCmsConfig()).toThrow("Astropress not initialized");
	});
});

describe("admin ui", () => {
	it("exposes generic defaults when no admin customization is registered", () => {
		restoreConfig(null);

		const adminUi = resolveAstropressAdminUiConfig();

		expect(adminUi.branding.productName).toBe("Astropress Admin");
		expect(adminUi.branding.logoSrc).toBeNull();
		expect(adminUi.branding.stylesheetHref).toBeNull();
		expect(adminUi.labels.sidebarTitle).toBe("Workspace");
		expect(adminUi.navigation.routePages).toBe("Route Table");
		expect(buildAstropressAdminDocumentTitle("Dashboard")).toBe("Dashboard | Astropress Admin");
	});

	it("merges host branding, labels, navigation, and assets from registerCms()", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["home"],
			seedPages: [],
			archives: [],
			translationStatus: [],
			admin: {
				branding: {
					appName: "Client Console",
					productName: "Client Console Admin",
					shellName: "Client Workspace",
					logoSrc: "/brand/admin-mark.svg",
					faviconHref: "/brand/favicon.ico",
					stylesheetHref: "/brand/admin.css",
				},
				labels: {
					sidebarTitle: "Operations",
					signOut: "Log out",
					loginHeading: "Client sign in",
					loginSubmit: "Continue",
				},
				navigation: {
					routePages: "Page Routes",
					media: "Asset Library",
				},
			},
		});

		const adminUi = resolveAstropressAdminUiConfig();

		expect(adminUi.branding.appName).toBe("Client Console");
		expect(adminUi.branding.productName).toBe("Client Console Admin");
		expect(adminUi.branding.shellName).toBe("Client Workspace");
		expect(adminUi.branding.logoSrc).toBe("/brand/admin-mark.svg");
		expect(adminUi.branding.faviconHref).toBe("/brand/favicon.ico");
		expect(adminUi.branding.stylesheetHref).toBe("/brand/admin.css");
		expect(adminUi.labels.sidebarTitle).toBe("Operations");
		expect(adminUi.labels.signOut).toBe("Log out");
		expect(adminUi.labels.loginHeading).toBe("Client sign in");
		expect(adminUi.labels.loginSubmit).toBe("Continue");
		expect(adminUi.navigation.routePages).toBe("Page Routes");
		expect(adminUi.navigation.media).toBe("Asset Library");
		expect(buildAstropressAdminDocumentTitle("Dashboard")).toBe("Dashboard | Client Console Admin");
	});

	it("exposes locale-aware admin labels in Spanish when locale is es", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "es")).toBe("Guardar");
		expect(getAdminLabel("publishButton", "es")).toBe("Publicar");
		expect(getAdminLabel("signOut", "es")).toBe("Cerrar sesión");
		expect(getAdminLabel("loginHeading", "es")).toBe("Acceder al panel de administración");
		expect(getAdminLabel("sidebarTitle", "es")).toBe("Espacio de trabajo");
	});

	it("exposes locale-aware admin labels in French when locale is fr", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "fr")).toBe("Enregistrer");
		expect(getAdminLabel("deleteButton", "fr")).toBe("Supprimer");
		expect(getAdminLabel("cancelButton", "fr")).toBe("Annuler");
	});

	it("exposes locale-aware admin labels in Japanese when locale is ja", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "ja")).toBe("保存");
		expect(getAdminLabel("publishButton", "ja")).toBe("公開");
		expect(getAdminLabel("signOut", "ja")).toBe("サインアウト");
	});

	it("exposes locale-aware admin labels in Arabic when locale is ar", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "ar")).toBe("حفظ");
		expect(getAdminLabel("publishButton", "ar")).toBe("نشر");
		expect(getAdminLabel("deleteButton", "ar")).toBe("حذف");
		expect(getAdminLabel("cancelButton", "ar")).toBe("إلغاء");
		expect(getAdminLabel("signOut", "ar")).toBe("تسجيل الخروج");
		expect(getAdminLabel("loginHeading", "ar")).toBe("تسجيل الدخول إلى لوحة الإدارة");
		expect(getAdminLabel("loginSubmit", "ar")).toBe("تسجيل الدخول");
		expect(getAdminLabel("sidebarTitle", "ar")).toBe("مساحة العمل");
		expect(getAdminLabel("navDashboard", "ar")).toBe("لوحة التحكم");
		expect(getAdminLabel("navMedia", "ar")).toBe("الوسائط");
		expect(getAdminLabel("navUsers", "ar")).toBe("المستخدمون");
		expect(getAdminLabel("navSettings", "ar")).toBe("الإعدادات");
		expect(getAdminLabel("changeLanguage", "ar")).toBe("تغيير اللغة");
		expect(getAdminLabel("loadingLabel", "ar")).toBe("جارٍ التحميل…");
		expect(getAdminLabel("errorLabel", "ar")).toBe("فشل الإجراء");
	});

	it("BCP-47 ar-SA resolves to ar", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "ar-SA")).toBe("حفظ");
	});

	it("translates navGroupComingSoon per locale (used by integration-honesty sidebar split)", () => {
		restoreConfig(null);
		expect(getAdminLabel("navGroupComingSoon", "en")).toBe("Coming soon");
		expect(getAdminLabel("navGroupComingSoon", "es")).toBe("Próximamente");
		expect(getAdminLabel("navGroupComingSoon", "fr")).toBe("Bientôt disponible");
		expect(getAdminLabel("navGroupComingSoon", "ar")).toBe("قريبًا");
		expect(getAdminLabel("navGroupComingSoon", "ja")).toBe("近日公開");
	});

	it("translates RequiresIntegration coming-soon strings per locale", () => {
		restoreConfig(null);
		expect(getAdminLabel("stubComingSoonHeading", "en")).toBe("Coming soon");
		expect(getAdminLabel("stubComingSoonBody", "en")).toMatch(/roadmap/i);
		expect(getAdminLabel("stubComingSoonLink", "en")).toMatch(/GitHub/);
		expect(getAdminLabel("stubComingSoonHeading", "es")).toBe("Próximamente");
		expect(getAdminLabel("stubComingSoonHeading", "ja")).toBe("近日公開");
		expect(getAdminLabel("stubComingSoonHeading", "ar")).toBe("قريبًا");
		expect(getAdminLabel("stubComingSoonBody", "fr")).not.toBe(adminLabels.en.stubComingSoonBody);
	});

	it("Arabic translations are non-empty strings for every key", () => {
		const arDict = adminLabels.ar;
		const keys = Object.keys(adminLabels.en) as Array<keyof typeof adminLabels.en>;
		for (const k of keys) {
			expect(typeof arDict[k]).toBe("string");
			expect(arDict[k].length).toBeGreaterThan(0);
		}
	});

	it("falls back to English when locale is unknown", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "zz")).toBe(adminLabels.en.saveButton);
		expect(getAdminLabel("publishButton", "xx")).toBe(adminLabels.en.publishButton);
	});

	it("falls back to English when locale is undefined (no cms config)", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton")).toBe("Save");
		expect(getAdminLabel("sidebarTitle")).toBe("Workspace");
	});

	it("uses site configured locale from registerCms when no explicit locale is passed", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [],
			locales: ["de"],
		});
		expect(getAdminLabel("saveButton")).toBe("Speichern");
		expect(getAdminLabel("signOut")).toBe("Abmelden");
	});

	it("BCP-47 tags with region (e.g. es-MX) resolve to the base locale (es)", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "es-MX")).toBe("Guardar");
		expect(getAdminLabel("saveButton", "pt-BR")).toBe("Salvar");
	});

	it("resolveAstropressAdminUiConfig(locale) applies translations through applyTranslations", () => {
		restoreConfig(null);
		const adminUi = resolveAstropressAdminUiConfig("es");
		expect(adminUi.labels.signOut).toBe("Cerrar sesión");
		expect(adminUi.labels.sidebarTitle).toBe("Espacio de trabajo");
		expect(adminUi.navigation.dashboard).toBeTruthy();
		expect(adminUi.branding.productName).toBe("Astropress Admin");
	});

	it("resolveAstropressAdminUiConfig(locale) preserves host overrides and translates remaining keys", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [],
			admin: {
				labels: { signOut: "Salir" },
				navigation: { routePages: "Rutas" },
			},
		});
		const adminUi = resolveAstropressAdminUiConfig("es");
		expect(adminUi.labels.sidebarTitle).toBe("Espacio de trabajo");
		expect(adminUi.navigation.dashboard).toBeTruthy();
	});

	it("falls back to null for stylesheetHref when override is empty string", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [],
			admin: { branding: { stylesheetHref: "" } },
		});
		const adminUi = resolveAstropressAdminUiConfig();
		expect(adminUi.branding.stylesheetHref).toBeNull();
	});

	it("falls back to productName for shellName/logoAlt and to /ap-admin for logoHref when overrides are empty strings", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [],
			admin: {
				branding: {
					productName: "Fallback Admin",
					shellName: "",
					logoAlt: "",
					logoHref: "",
				},
			},
		});

		const adminUi = resolveAstropressAdminUiConfig();
		// shellName falls back to productName when empty
		expect(adminUi.branding.shellName).toBe("Fallback Admin");
		// logoAlt falls back to productName when empty
		expect(adminUi.branding.logoAlt).toBe("Fallback Admin");
		// logoHref falls back to "/ap-admin" when empty
		expect(adminUi.branding.logoHref).toBe("/ap-admin");
	});
});

