import type { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { z } from "zod";

import * as adminStoreDispatch from "../src/admin-store-dispatch";
import { _resetRegistryForTests, registerProvider } from "../src/integrations/registry";
import {
	connectIntegrationAction,
	disconnectIntegrationAction,
	reverifyIntegrationAction,
} from "../src/runtime-actions-integrations";
import { createIntegrationsRepository } from "../src/sqlite-runtime/integrations";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

interface FakeRepo {
	connect: ReturnType<typeof vi.fn>;
	updateStatus: ReturnType<typeof vi.fn>;
	disconnect: ReturnType<typeof vi.fn>;
	findStatus: ReturnType<typeof vi.fn>;
	listStatuses: ReturnType<typeof vi.fn>;
	findSecret: ReturnType<typeof vi.fn>;
	listPreviousKidContexts: ReturnType<typeof vi.fn>;
}

function makeRepo(): FakeRepo {
	return {
		connect: vi.fn(async () => {}),
		updateStatus: vi.fn(() => true),
		disconnect: vi.fn(() => true),
		findStatus: vi.fn(),
		listStatuses: vi.fn(() => []),
		findSecret: vi.fn(),
		listPreviousKidContexts: vi.fn(() => []),
	};
}

function withRepo(repo: FakeRepo | null) {
	// Stub the dispatch helper to always run the local-store branch
	// (no D1 binding) and hand back a minimal store with the repo.
	vi.spyOn(adminStoreDispatch, "withLocalStoreFallback").mockImplementation(
		async (_locals, _onD1, onLocal) => onLocal({ integrations: repo ?? undefined } as never),
	);
}

function withD1Backed(db: DatabaseSync) {
	// Stub the dispatch helper to take the D1 branch with a real D1
	// shape (sqlite-backed) so the D1IntegrationsRepository write
	// path runs to completion end-to-end.
	const d1 = new SqliteBackedD1Database(db);
	vi.spyOn(adminStoreDispatch, "withLocalStoreFallback").mockImplementation(
		async (_locals, onD1, _onLocal) => onD1(d1 as never),
	);
	return d1;
}

const FIELDS_SCHEMA = z.object({ apiKey: z.string().min(1) });

beforeEach(() => {
	_resetRegistryForTests();
	registerProvider("newsletter", {
		id: "fake-listmonk",
		label: "Fake Listmonk",
		fields: FIELDS_SCHEMA,
	});
});

afterEach(() => {
	vi.restoreAllMocks();
	_resetRegistryForTests();
});

describe("connectIntegrationAction", () => {
	it("returns INTEGRATION_PROVIDER_NOT_FOUND when the provider is not registered", async () => {
		const r = await connectIntegrationAction(null, {
			domain: "newsletter",
			providerId: "missing",
			fields: { apiKey: "k" },
		});
		expect(r).toEqual({
			ok: false,
			status: "error",
			code: "INTEGRATION_PROVIDER_NOT_FOUND",
		});
	});

	it("returns INTEGRATIONS_NOT_AVAILABLE when the local admin store has no integrations repo", async () => {
		withRepo(null);
		const r = await connectIntegrationAction(null, {
			domain: "newsletter",
			providerId: "fake-listmonk",
			fields: { apiKey: "k" },
		});
		expect(r).toEqual({
			ok: false,
			status: "error",
			code: "INTEGRATIONS_NOT_AVAILABLE",
		});
	});

	it("D1 path: connect writes the status + sealed-secret rows atomically via batch", async () => {
		const db = makeDb();
		withD1Backed(db);
		const r = await connectIntegrationAction(null, {
			domain: "newsletter",
			providerId: "fake-listmonk",
			fields: { apiKey: "k-d1-canary" },
		});
		expect(r.ok).toBe(true);
		// Read back via the sqlite repo (same underlying tables).
		const repo = createIntegrationsRepository({
			getDb: () => db as never,
			now: () => "2026-05-18T00:00:00Z",
		});
		expect(repo.findStatus("newsletter", "fake-listmonk")?.status).toBe("connected");
	});

	it("calls repo.connect with the validated fields when the provider exists and the repo is available", async () => {
		const repo = makeRepo();
		withRepo(repo);
		const r = await connectIntegrationAction(null, {
			domain: "newsletter",
			providerId: "fake-listmonk",
			fields: { apiKey: "k" },
		});
		expect(r.ok).toBe(true);
		expect(repo.connect).toHaveBeenCalledOnce();
		const [callArgs] = repo.connect.mock.calls[0];
		expect(callArgs.secretFields).toEqual({ apiKey: "k" });
		expect(callArgs.domain).toBe("newsletter");
		expect(callArgs.provider).toBe("fake-listmonk");
	});
});

describe("reverifyIntegrationAction", () => {
	it("returns INTEGRATION_PROVIDER_NOT_FOUND when the provider is not registered", async () => {
		const r = await reverifyIntegrationAction(null, "newsletter", "missing", {
			apiKey: "k",
		});
		expect(r).toEqual({
			ok: false,
			status: "error",
			code: "INTEGRATION_PROVIDER_NOT_FOUND",
		});
	});

	it("returns INTEGRATIONS_NOT_AVAILABLE when the repo is missing", async () => {
		withRepo(null);
		const r = await reverifyIntegrationAction(null, "newsletter", "fake-listmonk", { apiKey: "k" });
		expect(r).toEqual({
			ok: false,
			status: "error",
			code: "INTEGRATIONS_NOT_AVAILABLE",
		});
	});

	it("D1 path: reverify awaits the async updateStatus write (no fire-and-forget)", async () => {
		const db = makeDb();
		withD1Backed(db);
		// Seed an existing 'connected' row that reverify will flip.
		db.prepare(
			"INSERT INTO connected_integrations (domain, provider, status, config_json, connected_at, last_check_at, last_error) VALUES (?, ?, 'connected', '{}', '2026-01-01', NULL, NULL)",
		).run("newsletter", "fake-listmonk");
		const r = await reverifyIntegrationAction(null, "newsletter", "fake-listmonk", {
			apiKey: "k-canary",
		});
		expect(r.ok).toBe(true);
		const row = db
			.prepare(
				"SELECT status, last_check_at FROM connected_integrations WHERE domain=? AND provider=?",
			)
			.get("newsletter", "fake-listmonk") as { status: string; last_check_at: string | null };
		expect(row.status).toBe("connected");
		expect(row.last_check_at).not.toBeNull(); // proves updateStatus ran
	});

	it("calls repo.updateStatus with status='connected' when verify passes (no provider.verify => trivially ok)", async () => {
		const repo = makeRepo();
		withRepo(repo);
		const r = await reverifyIntegrationAction(null, "newsletter", "fake-listmonk", { apiKey: "k" });
		expect(r.ok).toBe(true);
		expect(repo.updateStatus).toHaveBeenCalledOnce();
		const [updateArgs] = repo.updateStatus.mock.calls[0];
		expect(updateArgs.status).toBe("connected");
	});
});

describe("disconnectIntegrationAction", () => {
	it("returns INTEGRATIONS_NOT_AVAILABLE when the repo is missing", async () => {
		withRepo(null);
		const r = await disconnectIntegrationAction(null, "newsletter", "fake-listmonk");
		expect(r).toEqual({
			ok: false,
			code: "INTEGRATIONS_NOT_AVAILABLE",
		});
	});

	it("D1 path: disconnect deletes the row (awaiting the async repo call)", async () => {
		const db = makeDb();
		withD1Backed(db);
		db.prepare(
			"INSERT INTO connected_integrations (domain, provider, status, config_json, connected_at, last_check_at, last_error) VALUES (?, ?, 'connected', '{}', '2026-01-01', NULL, NULL)",
		).run("newsletter", "fake-listmonk");
		const r = await disconnectIntegrationAction(null, "newsletter", "fake-listmonk");
		expect(r).toEqual({ ok: true });
		const remaining = db
			.prepare("SELECT COUNT(*) AS n FROM connected_integrations WHERE domain=? AND provider=?")
			.get("newsletter", "fake-listmonk") as { n: number };
		expect(remaining.n).toBe(0);
	});

	it("calls repo.disconnect with the (domain, providerId) pair", async () => {
		const repo = makeRepo();
		withRepo(repo);
		const r = await disconnectIntegrationAction(null, "newsletter", "fake-listmonk");
		expect(r).toEqual({ ok: true });
		expect(repo.disconnect).toHaveBeenCalledWith("newsletter", "fake-listmonk");
	});
});

tests/integrations/webhooks/inbound.test.source:
import { describe, expect, it } from "vitest";

import {
	algorithmHashName,
	algorithmHeaderPrefix,
	computeWebhookHmacBytes,
	extractWebhookHexSignature,
	parseWebhookHexBytes,
	verifyGithubWebhookSignature,
	verifyInboundWebhookSignature,
} from "../../../src/integrations/webhooks/inbound";

const SECRET = "shh-its-a-secret";
const BODY = new TextEncoder().encode('{"event":"push"}');

async function signHex(
	algo: "hmac-sha256" | "hmac-sha512",
	secret: string,
	body: Uint8Array,
): Promise<string> {
	const sig = await computeWebhookHmacBytes(algo, secret, body);
	return Array.from(sig)
		.map((b) => b.toString(16).padStart(2, "0"))
		.join("");
}

describe("algorithmHashName", () => {
	it("maps hmac-sha256 to SHA-256", () => {
		expect(algorithmHashName("hmac-sha256")).toBe("SHA-256");
	});
	it("maps hmac-sha512 to SHA-512", () => {
		expect(algorithmHashName("hmac-sha512")).toBe("SHA-512");
	});
});

describe("algorithmHeaderPrefix", () => {
	it("maps hmac-sha256 to 'sha256='", () => {
		expect(algorithmHeaderPrefix("hmac-sha256")).toBe("sha256=");
	});
	it("maps hmac-sha512 to 'sha512='", () => {
		expect(algorithmHeaderPrefix("hmac-sha512")).toBe("sha512=");
	});
});

describe("extractWebhookHexSignature", () => {
	it("strips the sha256= prefix when present", () => {
		expect(extractWebhookHexSignature("sha256=abcdef", "hmac-sha256")).toBe("abcdef");
	});
	it("strips the sha512= prefix when present", () => {
		expect(extractWebhookHexSignature("sha512=abcdef", "hmac-sha512")).toBe("abcdef");
	});
	it("returns the input unchanged when the prefix is absent", () => {
		expect(extractWebhookHexSignature("abcdef", "hmac-sha256")).toBe("abcdef");
	});
	it("does not strip a sha512= prefix when algo is hmac-sha256", () => {
		expect(extractWebhookHexSignature("sha512=abcdef", "hmac-sha256")).toBe("sha512=abcdef");
	});
	it("returns empty when the entire input is the prefix", () => {
		expect(extractWebhookHexSignature("sha256=", "hmac-sha256")).toBe("");
	});
});

describe("parseWebhookHexBytes", () => {
	it("parses a valid even-length hex string", () => {
		const out = parseWebhookHexBytes("deadbeef");
		expect(out).not.toBeNull();
		expect(Array.from(out as Uint8Array)).toEqual([0xde, 0xad, 0xbe, 0xef]);
	});
	it("accepts uppercase hex", () => {
		const out = parseWebhookHexBytes("DEADBEEF");
		expect(out).not.toBeNull();
		expect(Array.from(out as Uint8Array)).toEqual([0xde, 0xad, 0xbe, 0xef]);
	});
	it("returns null on empty input", () => {
		expect(parseWebhookHexBytes("")).toBeNull();
	});
	it("returns null on odd-length input", () => {
		expect(parseWebhookHexBytes("abc")).toBeNull();
	});
	it("returns null on non-hex characters", () => {
		expect(parseWebhookHexBytes("zz")).toBeNull();
	});
	it("returns null on whitespace inside the value", () => {
		expect(parseWebhookHexBytes("ab cd")).toBeNull();
	});

	it("rejects a hex string with a non-hex prefix (kills regex-anchor mutants)", () => {
		expect(parseWebhookHexBytes("zz0011")).toBeNull();
	});

	it("rejects a hex string with a non-hex suffix (kills regex-anchor mutants)", () => {
		expect(parseWebhookHexBytes("0011zz")).toBeNull();
	});

	it("returns a Uint8Array of length hex.length / 2 (no extra trailing bytes)", () => {
		const out = parseWebhookHexBytes("0011");
		expect((out as Uint8Array).length).toBe(2);
	});

	it("parses every byte of a multi-byte hex string (kills < → <= loop bound mutants)", () => {
		const out = parseWebhookHexBytes("00112233");
		expect(Array.from(out as Uint8Array)).toEqual([0, 0x11, 0x22, 0x33]);
	});
});

describe("verifyInboundWebhookSignature", () => {
	it("returns true for a valid sha256 signature", async () => {
		const hex = await signHex("hmac-sha256", SECRET, BODY);
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha256",
			header: `sha256=${hex}`,
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(true);
	});

	it("returns true for a valid sha512 signature", async () => {
		const hex = await signHex("hmac-sha512", SECRET, BODY);
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha512",
			header: `sha512=${hex}`,
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(true);
	});

	it("returns true when the header has no algorithm prefix but is otherwise valid hex", async () => {
		const hex = await signHex("hmac-sha256", SECRET, BODY);
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha256",
			header: hex,
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(true);
	});

	it("returns false on a forged signature (wrong secret)", async () => {
		const hex = await signHex("hmac-sha256", "different-secret", BODY);
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha256",
			header: `sha256=${hex}`,
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(false);
	});

	it("returns false on a tampered body (signature for different bytes)", async () => {
		const hex = await signHex("hmac-sha256", SECRET, BODY);
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha256",
			header: `sha256=${hex}`,
			body: new TextEncoder().encode('{"event":"push","tampered":true}'),
			secret: SECRET,
		});
		expect(ok).toBe(false);
	});

	it("returns false on algorithm mismatch (signed sha256, verified sha512)", async () => {
		const hex = await signHex("hmac-sha256", SECRET, BODY);
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha512",
			header: `sha512=${hex}`,
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(false);
	});

	it("returns false on empty header", async () => {
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha256",
			header: "",
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(false);
	});

	it("returns false on empty secret (the guard is load-bearing — WebCrypto refuses zero-length keys)", async () => {
		// We sign with a real secret so parseWebhookHexBytes accepts the
		// header. Without the empty-secret guard, the WebCrypto key
		// import would throw — the test would still surface the mutant.
		const hex = await signHex("hmac-sha256", SECRET, BODY);
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha256",
			header: `sha256=${hex}`,
			body: BODY,
			secret: "",
		});
		expect(ok).toBe(false);
	});

	it("returns false when the header decodes to the wrong byte length", async () => {
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha256",
			header: "sha256=deadbeef",
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(false);
	});

	it("returns false on non-hex header content", async () => {
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha256",
			header: "sha256=zzzz",
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(false);
	});

	it("returns false on odd-length header content", async () => {
		const ok = await verifyInboundWebhookSignature({
			algo: "hmac-sha256",
			header: "sha256=abc",
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(false);
	});
});

describe("verifyGithubWebhookSignature", () => {
	it("delegates to hmac-sha256 verification", async () => {
		const hex = await signHex("hmac-sha256", SECRET, BODY);
		const ok = await verifyGithubWebhookSignature({
			header: `sha256=${hex}`,
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(true);
	});

	it("rejects forged signatures", async () => {
		const hex = await signHex("hmac-sha256", "wrong", BODY);
		const ok = await verifyGithubWebhookSignature({
			header: `sha256=${hex}`,
			body: BODY,
			secret: SECRET,
		});
		expect(ok).toBe(false);
	});
});

