import type { DatabaseSync } from "node:sqlite";
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

import { registerCms } from "../src/config";
import type { AstropressWordPressImportReport } from "../src/platform-contracts.js";
import { createApiTokenStore } from "../src/sqlite-runtime/api-tokens.js";
import { makeDb } from "./helpers/make-db.js";

// ─── Hoisted mock functions ────────────────────────────────────────────────────

const mocks = vi.hoisted(() => ({
	loadLocalAdminStore: vi.fn(),
	importWordPress: vi.fn(),
}));

vi.mock("@astropress-diy/astropress/local-runtime-modules", () => ({
	loadLocalAdminStore: mocks.loadLocalAdminStore,
}));

vi.mock("@astropress-diy/astropress/import/wordpress", () => ({
	createAstropressWordPressImportSource: () => ({
		importWordPress: mocks.importWordPress,
	}),
}));

// ─── Page handler import (after mocks) ───────────────────────────────────────

import { POST } from "../pages/ap-api/v1/import/wordpress.js";

// ─── Test fixtures ────────────────────────────────────────────────────────────

const BASE = "http://localhost";

let db: DatabaseSync;
let importWriteToken: string;
let contentReadToken: string;

const MOCK_REPORT: AstropressWordPressImportReport = {
	status: "completed",
	importedRecords: 3,
	importedMedia: 1,
	importedComments: 0,
	importedUsers: 1,
	importedRedirects: 2,
	downloadedMedia: 0,
	failedMedia: [],
	reviewRequired: false,
	manualTasks: [],
	warnings: [],
	plan: {
		exportFile: "/tmp/export.xml",
		includeComments: true,
		includeUsers: true,
		includeMedia: true,
		downloadMedia: false,
		applyLocal: true,
		permalinkStrategy: "preserve-wordpress-links",
		resumeSupported: true,
		entityCounts: {
			posts: 2,
			pages: 1,
			attachments: 1,
			redirects: 2,
			comments: 0,
			users: 1,
			categories: 0,
			tags: 0,
		},
		reviewRequired: false,
		manualTasks: [],
	},
	inventory: {
		exportFile: "/tmp/export.xml",
		detectedRecords: 4,
		detectedMedia: 1,
		detectedComments: 0,
		detectedUsers: 1,
		detectedShortcodes: 0,
		detectedBuilderMarkers: 0,
		entityCounts: {
			posts: 2,
			pages: 1,
			attachments: 1,
			redirects: 2,
			comments: 0,
			users: 1,
			categories: 0,
			tags: 0,
		},
		unsupportedPatterns: [],
		remediationCandidates: [],
		warnings: [],
	},
};

beforeAll(async () => {
	db = makeDb();
	registerCms({
		templateKeys: ["content"],
		siteUrl: "https://example.com",
		seedPages: [],
		archives: [],
		translationStatus: [],
		api: { enabled: true },
	});

	const store = createApiTokenStore(db);
	importWriteToken = (await store.create({ label: "import", scopes: ["import:write"] })).rawToken;
	contentReadToken = (await store.create({ label: "read", scopes: ["content:read"] })).rawToken;
});

afterAll(() => {
	db.close();
});

beforeEach(() => {
	const apiTokens = createApiTokenStore(db);
	mocks.loadLocalAdminStore.mockResolvedValue({
		apiTokens,
		checkRateLimit: () => true,
	});
	mocks.importWordPress.mockResolvedValue(MOCK_REPORT);
});

// ─── Context builder ──────────────────────────────────────────────────────────

type AnyAPIContext = Parameters<typeof POST>[0];

function ctx(request: Request): AnyAPIContext {
	return { request, params: {}, locals: {} } as unknown as AnyAPIContext;
}

function req(opts: { token?: string; body?: unknown } = {}): Request {
	const headers: Record<string, string> = {
		"Content-Type": "application/json",
	};
	if (opts.token) headers.Authorization = `Bearer ${opts.token}`;
	return new Request(`${BASE}/ap-api/v1/import/wordpress`, {
		method: "POST",
		headers,
		body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
	});
}

// ─── POST /ap-api/v1/import/wordpress ────────────────────────────────────────

describe("POST /ap-api/v1/import/wordpress — auth and scope", () => {
	it("returns 401 without Authorization header", async () => {
		const res = await POST(ctx(req({ body: { exportFile: "/tmp/export.xml" } })));
		expect(res.status).toBe(401);
	});

	it("returns 403 when token lacks import:write scope", async () => {
		const res = await POST(
			ctx(
				req({
					token: contentReadToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(res.status).toBe(403);
	});

	it("returns 404 when API is disabled", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			api: { enabled: false },
		});
		const res = await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(res.status).toBe(404);
		// Restore
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			api: { enabled: true },
		});
	});
});

describe("POST /ap-api/v1/import/wordpress — request validation", () => {
	it("returns 422 when exportFile is missing from body", async () => {
		const res = await POST(ctx(req({ token: importWriteToken, body: {} })));
		expect(res.status).toBe(422);
		const body = (await res.json()) as Record<string, unknown>;
		expect(body.code).toBe("validation_error");
	});

	it("returns 422 when exportFile is empty string", async () => {
		const res = await POST(ctx(req({ token: importWriteToken, body: { exportFile: "  " } })));
		expect(res.status).toBe(422);
	});
});

describe("POST /ap-api/v1/import/wordpress — success path", () => {
	it("returns 200 with AstropressWordPressImportReport shape", async () => {
		const res = await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(res.status).toBe(200);
		const body = (await res.json()) as Record<string, unknown>;
		expect(body.status).toBe("completed");
		expect(typeof body.importedRecords).toBe("number");
		expect(typeof body.importedMedia).toBe("number");
		expect(Array.isArray(body.failedMedia)).toBe(true);
		expect(typeof body.reviewRequired).toBe("boolean");
	});

	it("calls importWordPress with the provided exportFile and applyLocal: true", async () => {
		await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(mocks.importWordPress).toHaveBeenCalledWith(
			expect.objectContaining({
				exportFile: "/tmp/export.xml",
				applyLocal: true,
			}),
		);
	});

	it("returns completed_with_warnings status when import has warnings", async () => {
		mocks.importWordPress.mockResolvedValueOnce({
			...MOCK_REPORT,
			status: "completed_with_warnings",
			reviewRequired: true,
			warnings: ["Review remediation-candidates.json"],
		});
		const res = await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(res.status).toBe(200);
		const body = (await res.json()) as { status: string; warnings: string[] };
		expect(body.status).toBe("completed_with_warnings");
		expect(body.warnings.length).toBeGreaterThan(0);
	});
});

tests/build-time-content-loader.test.ts.source:
import {
	type AstropressPlatformAdapter,
	assertProviderContract,
	type ContentListOptions,
	type ContentStoreRecord,
	normalizeProviderCapabilities,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import { createAstropressBuildTimeLoader } from "../src/build-time-content-loader";

function makeTestRecord(
	overrides: Partial<ContentStoreRecord> &
		Pick<ContentStoreRecord, "id" | "kind" | "slug" | "status">,
): ContentStoreRecord {
	return {
		title: overrides.title ?? `Title for ${overrides.slug}`,
		body: null,
		locale: null,
		metadata: {},
		...overrides,
	};
}

function createFilteringAdapter(records: ContentStoreRecord[]): AstropressPlatformAdapter {
	return assertProviderContract({
		capabilities: normalizeProviderCapabilities({ name: "test-filtering" }),
		content: {
			async list(kind, options?: ContentListOptions) {
				let results = [...records];

				if (kind) {
					results = results.filter((r) => r.kind === kind);
				}

				if (options?.status && options.status !== "all") {
					results = results.filter((r) => r.status === options.status);
				}

				if (options?.locale) {
					results = results.filter((r) => !r.locale || r.locale === options.locale);
				}

				if (options?.offset) {
					results = results.slice(options.offset);
				}

				if (options?.limit !== undefined) {
					results = results.slice(0, options.limit);
				}

				return results;
			},
			async get(id) {
				return records.find((r) => r.id === id) ?? null;
			},
			async save(record) {
				return record;
			},
			async delete() {},
		},
		media: {
			async put(a) {
				return a;
			},
			async get() {
				return null;
			},
			async delete() {},
		},
		revisions: {
			async list() {
				return [];
			},
			async append(r) {
				return r;
			},
		},
		auth: {
			async signIn() {
				return null;
			},
			async signOut() {},
			async getSession() {
				return null;
			},
		},
	});
}

describe("ContentListOptions", () => {
	it("list accepts status filter and returns only published records", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "hello-world",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "unpublished",
				status: "draft",
			}),
		];
		const adapter = createFilteringAdapter(records);

		const published = await adapter.content.list("post", {
			status: "published",
		});
		expect(published.map((r) => r.slug)).toEqual(["hello-world"]);
	});

	it("list with no status filter returns all records", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "hello-world",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "draft-post",
				status: "draft",
			}),
		];
		const adapter = createFilteringAdapter(records);

		const all = await adapter.content.list("post");
		expect(all).toHaveLength(2);
	});

	it("list with kind and status filter returns only matching records", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "post-1",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "page",
				slug: "page-1",
				status: "published",
			}),
			makeTestRecord({
				id: "c",
				kind: "post",
				slug: "post-draft",
				status: "draft",
			}),
		];
		const adapter = createFilteringAdapter(records);

		const posts = await adapter.content.list("post", { status: "published" });
		expect(posts.map((r) => r.kind)).toEqual(["post"]);
		expect(posts.map((r) => r.slug)).toEqual(["post-1"]);
	});

	it("list respects limit and offset", async () => {
		const records: ContentStoreRecord[] = Array.from({ length: 10 }, (_, i) =>
			makeTestRecord({
				id: `post-${i}`,
				kind: "post",
				slug: `post-${i}`,
				status: "published",
			}),
		);
		const adapter = createFilteringAdapter(records);

		const page1 = await adapter.content.list("post", {
			status: "published",
			limit: 3,
			offset: 0,
		});
		expect(page1).toHaveLength(3);

		const page2 = await adapter.content.list("post", {
			status: "published",
			limit: 3,
			offset: 3,
		});
		expect(page2).toHaveLength(3);
		expect(page2[0].slug).toBe("post-3");
	});
});

describe("createAstropressBuildTimeLoader", () => {
	it("returns a loader with posts() and pages() factories", () => {
		const adapter = createFilteringAdapter([]);
		const loader = createAstropressBuildTimeLoader(adapter);

		expect(typeof loader.posts).toBe("function");
		expect(typeof loader.pages).toBe("function");
	});

	it("posts loader fetches only published posts", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "live-post",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "draft-post",
				status: "draft",
			}),
			makeTestRecord({
				id: "c",
				kind: "page",
				slug: "a-page",
				status: "published",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter);

		const posts = await loader.posts().load();
		expect(posts).toHaveLength(1);
		expect(posts[0].slug).toBe("live-post");
		expect(posts[0].kind).toBe("post");
	});

	it("pages loader fetches only published pages", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "page",
				slug: "about",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "page",
				slug: "draft-page",
				status: "draft",
			}),
			makeTestRecord({
				id: "c",
				kind: "post",
				slug: "a-post",
				status: "published",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter);

		const pages = await loader.pages().load();
		expect(pages).toHaveLength(1);
		expect(pages[0].slug).toBe("about");
		expect(pages[0].kind).toBe("page");
	});

	it("each returned record has the required ContentStoreRecord shape", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "post-1",
				kind: "post",
				slug: "post-1",
				status: "published",
				title: "Hello World",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter);

		const posts = await loader.posts().load();
		const record = posts[0];

		expect(record).toHaveProperty("id");
		expect(record).toHaveProperty("kind");
		expect(record).toHaveProperty("slug");
		expect(record).toHaveProperty("status");
		expect(record).toHaveProperty("title");
	});

	it("loader kind property matches the content kind", () => {
		const adapter = createFilteringAdapter([]);
		const loader = createAstropressBuildTimeLoader(adapter);

		expect(loader.posts().kind).toBe("post");
		expect(loader.pages().kind).toBe("page");
	});

	it("respects locale option when provided", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "en-post",
				status: "published",
				locale: "en",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "fr-post",
				status: "published",
				locale: "fr",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter, { locale: "en" });

		const posts = await loader.posts().load();
		expect(posts).toHaveLength(1);
		expect(posts[0].slug).toBe("en-post");
	});
});

