import { afterEach, describe, expect, it } from "vitest";

import {
	_resetOAuthRegistryForTests,
	type OAuthProviderDefinition,
} from "../../../src/integrations/oauth/registry";
import { buildAuthorizeRedirect, buildRedirectUri } from "../../../src/integrations/oauth/start";
import { verifyOAuthState } from "../../../src/integrations/oauth/state";

const GITHUB: OAuthProviderDefinition = {
	id: "github",
	domain: "deploy-hooks",
	label: "GitHub",
	authorizationUrl: "https://github.com/login/oauth/authorize",
	tokenUrl: "https://github.com/login/oauth/access_token",
	scopes: ["repo:status", "read:org"],
	clientIdEnv: "GITHUB_OAUTH_CLIENT_ID",
	clientSecretEnv: "GITHUB_OAUTH_CLIENT_SECRET",
	redirectPath: "/ap-admin/oauth/callback/github",
};

const NOW = 1_700_000_000_000;
const ROOT = "test-root-secret";

describe("buildRedirectUri", () => {
	it("joins origin and path with one slash", () => {
		expect(buildRedirectUri("https://x.example", "/cb")).toBe("https://x.example/cb");
	});

	it("trims trailing slashes from the origin", () => {
		expect(buildRedirectUri("https://x.example///", "/cb")).toBe("https://x.example/cb");
	});

	it("prepends a slash when the path is missing one", () => {
		expect(buildRedirectUri("https://x.example", "cb")).toBe("https://x.example/cb");
	});

	it("preserves the exact path beyond the leading slash", () => {
		expect(buildRedirectUri("https://x.example", "/ap-admin/oauth/callback/github")).toBe(
			"https://x.example/ap-admin/oauth/callback/github",
		);
	});

	it("returns just the prefixed path when origin is empty", () => {
		// kills end > 0 → end >= 0 / true mutants: distinguishes the
		// terminating end===0 case from the always-loop variants.
		expect(buildRedirectUri("", "/cb")).toBe("/cb");
	});

	it("returns just the prefixed path when origin is only slashes", () => {
		expect(buildRedirectUri("///", "/cb")).toBe("/cb");
	});
});

describe("buildAuthorizeRedirect", () => {
	afterEach(() => _resetOAuthRegistryForTests());

	it("returns a URL on the provider's authorize host with the expected query keys", async () => {
		const { redirectUrl } = await buildAuthorizeRedirect({
			provider: GITHUB,
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/ap-admin/deploy-hooks",
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const url = new URL(redirectUrl);
		expect(url.origin).toBe("https://github.com");
		expect(url.pathname).toBe("/login/oauth/authorize");
		expect(url.searchParams.get("client_id")).toBe("abc123");
		expect(url.searchParams.get("redirect_uri")).toBe(
			"https://my.example/ap-admin/oauth/callback/github",
		);
		expect(url.searchParams.get("response_type")).toBe("code");
		expect(url.searchParams.get("scope")).toBe("repo:status read:org");
		expect(url.searchParams.get("state")).toBeTruthy();
	});

	it("the issued state verifies under the same rootSecret + provider context", async () => {
		const { state } = await buildAuthorizeRedirect({
			provider: GITHUB,
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/ap-admin/deploy-hooks",
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const verified = await verifyOAuthState({
			token: state.token,
			rootSecret: ROOT,
			nowMs: NOW + 1000,
			expectedContext: {
				domain: GITHUB.domain,
				providerId: GITHUB.id,
				returnTo: "/ap-admin/deploy-hooks",
			},
		});
		expect(verified.ok).toBe(true);
	});

	it("does not verify under a different rootSecret", async () => {
		const { state } = await buildAuthorizeRedirect({
			provider: GITHUB,
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/ap-admin/deploy-hooks",
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const verified = await verifyOAuthState({
			token: state.token,
			rootSecret: "different-root",
			nowMs: NOW + 1000,
		});
		expect(verified.ok).toBe(false);
	});

	it("space-joins multiple scopes into the scope query parameter", async () => {
		const { redirectUrl } = await buildAuthorizeRedirect({
			provider: { ...GITHUB, scopes: ["a", "b", "c"] },
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/x",
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(new URL(redirectUrl).searchParams.get("scope")).toBe("a b c");
	});

	it("allows ttlMs to be plumbed through to the state issuer", async () => {
		const { state } = await buildAuthorizeRedirect({
			provider: GITHUB,
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/x",
			rootSecret: ROOT,
			nowMs: NOW,
			ttlMs: 60_000,
		});
		expect(state.expiresAt).toBe(NOW + 60_000);
	});
});

tests/sqlite-runtime/content-submissions.source:
import { describe, expect, it } from "vitest";

import { createSqliteSubmissionStore } from "../../src/sqlite-runtime/content-submissions.js";
import { makeDb } from "../helpers/make-db.js";

describe("createSqliteSubmissionStore", () => {
	it("submitContact persists a row that getContactSubmissions reads back", () => {
		const db = makeDb();
		const { sqliteSubmissionRepository } = createSqliteSubmissionStore(() => db);

		const submitted = sqliteSubmissionRepository.submitContact({
			name: "Alice",
			email: "alice@example.com",
			message: "Hello",
			submittedAt: "2026-05-03T10:00:00.000Z",
		});
		expect(submitted.ok).toBe(true);

		const rows = sqliteSubmissionRepository.getContactSubmissions();
		expect(rows).toHaveLength(1);
		expect(rows[0]?.email).toBe("alice@example.com");
		expect(rows[0]?.name).toBe("Alice");
		expect(rows[0]?.message).toBe("Hello");
	});

	it("getContactSubmissions returns rows ordered by submitted_at DESC then id DESC", () => {
		const db = makeDb();
		const { sqliteSubmissionRepository } = createSqliteSubmissionStore(() => db);

		sqliteSubmissionRepository.submitContact({
			name: "First",
			email: "first@x",
			message: "1",
			submittedAt: "2026-05-01T10:00:00.000Z",
		});
		sqliteSubmissionRepository.submitContact({
			name: "Second",
			email: "second@x",
			message: "2",
			submittedAt: "2026-05-03T10:00:00.000Z",
		});

		const rows = sqliteSubmissionRepository.getContactSubmissions();
		expect(rows.map((r) => r.email)).toEqual(["second@x", "first@x"]);
	});

	it("schedulePublish + listScheduled returns the future scheduled row", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = createSqliteSubmissionStore(() => db);
		// Seed an existing entry so the schedulePublish UPDATE can find a row
		// to set scheduled_at on.
		db.prepare(
			"INSERT INTO content_entries (slug, legacy_url, title, kind, body) VALUES (?, ?, ?, 'page', '')",
		).run("hello-world", "/hello-world", "Hello World");

		const future = new Date(Date.now() + 60_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("hello-world", future);

		const scheduled = sqliteSchedulingRepository.listScheduled();
		expect(scheduled).toHaveLength(1);
		expect(scheduled[0]?.slug).toBe("hello-world");
		expect(scheduled[0]?.scheduledAt).toBe(future);
	});

	it("cancelScheduledPublish clears scheduled_at and listScheduled drops the row", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = createSqliteSubmissionStore(() => db);
		db.prepare(
			"INSERT INTO content_entries (slug, legacy_url, title, kind, body) VALUES (?, ?, ?, 'page', '')",
		).run("a", "/a", "A");

		const future = new Date(Date.now() + 60_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("a", future);
		expect(sqliteSchedulingRepository.listScheduled()).toHaveLength(1);

		sqliteSchedulingRepository.cancelScheduledPublish("a");
		expect(sqliteSchedulingRepository.listScheduled()).toHaveLength(0);
	});

	it("runScheduledPublishes promotes due entries to published and returns the row count", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = createSqliteSubmissionStore(() => db);
		db.prepare(
			"INSERT INTO content_entries (slug, legacy_url, title, kind, body) VALUES (?, ?, ?, 'page', '')",
		).run("due", "/due", "Due");

		const past = new Date(Date.now() - 60_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("due", past);

		const changed = sqliteSchedulingRepository.runScheduledPublishes();
		expect(changed).toBe(1);
		// scheduled_at cleared after promotion.
		const row = db
			.prepare("SELECT status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("due") as { status: string; scheduled_at: string | null };
		expect(row.status).toBe("published");
		expect(row.scheduled_at).toBeNull();
	});

	it("listScheduled excludes entries whose scheduled_at is in the past", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = createSqliteSubmissionStore(() => db);
		db.prepare(
			"INSERT INTO content_entries (slug, legacy_url, title, kind, body) VALUES (?, ?, ?, 'page', '')",
		).run("past", "/past", "P");

		const past = new Date(Date.now() - 60_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("past", past);

		// Past entries don't appear in listScheduled (>now filter).
		expect(sqliteSchedulingRepository.listScheduled()).toHaveLength(0);
	});
});

