import { describe, expect, it } from "vitest";
import { renderSectionsDocument } from "../../src/sections/preview-renderer";
import type { Section } from "../../src/sections/schema";

const ctx = { mediaUrls: {}, testimonials: [] };

describe("renderSectionsDocument", () => {
	it("renders an empty document for no sections", () => {
		const html = renderSectionsDocument([], ctx);
		expect(html).toContain("<!doctype html>");
		expect(html).toContain('class="ap-sections"');
	});

	it("includes the stylesheet link when stylesheetUrl is given", () => {
		const html = renderSectionsDocument([], ctx, {
			stylesheetUrl: "/sections.css",
		});
		expect(html).toContain('rel="stylesheet"');
		expect(html).toContain("/sections.css");
	});

	it("renders dir=rtl when context dir is rtl", () => {
		const html = renderSectionsDocument([], { ...ctx, dir: "rtl" });
		expect(html).toContain('dir="rtl"');
	});

	it("escapes HTML in plain-text fields", () => {
		const sections: Section[] = [
			{
				id: "h",
				kind: "hero",
				headline: '<img src=x onerror="alert(1)">',
				alignment: "start",
			},
		];
		const html = renderSectionsDocument(sections, ctx);
		expect(html).not.toMatch(/<img\s+src=x\s+onerror/);
		expect(html).toContain("&lt;img");
	});

	it("renders hero with primary CTA href escaped", () => {
		const sections: Section[] = [
			{
				id: "h",
				kind: "hero",
				headline: "Hi",
				alignment: "center",
				primaryCta: { label: "Go", href: 'javascript"' },
			},
		];
		const html = renderSectionsDocument(sections, ctx);
		expect(html).toContain("&quot;");
	});

	it("renders rich-text html as-is (sanitization runs at save time)", () => {
		const sections: Section[] = [{ id: "r", kind: "rich-text", html: "<p>preserved</p>" }];
		const html = renderSectionsDocument(sections, ctx);
		expect(html).toContain("<p>preserved</p>");
	});

	it("renders gallery with valid media urls", () => {
		const sections: Section[] = [
			{
				id: "g",
				kind: "gallery",
				mediaIds: ["a", "b"],
				columns: 3,
			},
		];
		const html = renderSectionsDocument(sections, {
			...ctx,
			mediaUrls: { a: "/a.png", b: "/b.png" },
		});
		expect(html).toContain("/a.png");
		expect(html).toContain("/b.png");
	});

	it("falls back to placeholder when image-text mediaId is missing", () => {
		const sections: Section[] = [
			{
				id: "it",
				kind: "image-text",
				heading: "X",
				body: "<p>y</p>",
				mediaId: "missing",
				imageSide: "end",
			},
		];
		const html = renderSectionsDocument(sections, ctx);
		expect(html).toContain("ap-image-text__placeholder");
	});

	it("renders all eight section kinds without throwing", () => {
		const all: Section[] = [
			{ id: "1", kind: "hero", headline: "H", alignment: "start" },
			{
				id: "2",
				kind: "feature-grid",
				heading: "F",
				columns: 3,
				items: [{ title: "t", body: "b" }],
			},
			{ id: "3", kind: "testimonials", source: "approved", layout: "grid" },
			{
				id: "4",
				kind: "cta-banner",
				headline: "Now",
				primaryCta: { label: "X", href: "/" },
				tone: "neutral",
			},
			{
				id: "5",
				kind: "image-text",
				heading: "I",
				body: "<p>b</p>",
				mediaId: "",
				imageSide: "start",
			},
			{ id: "6", kind: "faq", items: [{ question: "q?", answer: "a" }] },
			{ id: "7", kind: "gallery", mediaIds: [], columns: 2 },
			{ id: "8", kind: "rich-text", html: "<p>x</p>" },
		];
		const html = renderSectionsDocument(all, ctx);
		expect(html).toContain("ap-hero");
		expect(html).toContain("ap-feature-grid");
		expect(html).toContain("ap-testimonials");
		expect(html).toContain("ap-cta");
		expect(html).toContain("ap-image-text");
		expect(html).toContain("ap-faq");
		expect(html).toContain("ap-gallery");
		expect(html).toContain("ap-rich-text");
	});
});

tests/d1-local-integration.test.ts.source:
/**
 * D1 local integration tests — exercises the Cloudflare adapter through a real
 * SQLite-backed D1 shim (SqliteBackedD1Database).
 *
 * These tests use a local SQLite-backed D1 shim. Cloudflare D1 uses SQLite under
 * the hood and the shim is functionally equivalent for integration testing purposes.
 * No Cloudflare account or credentials required.
 */

import { createAstropressCloudflareAdapter, registerCms } from "@astropress-diy/astropress";
import { beforeEach, describe, expect, it } from "vitest";
import { makeDb, STANDARD_CMS_CONFIG } from "./helpers/make-db.js";
import {
	createSeededCloudflareDatabase,
	SqliteBackedD1Database,
} from "./helpers/provider-test-fixtures.js";

beforeEach(() => {
	registerCms(STANDARD_CMS_CONFIG);
});

describe("D1 adapter: auth round-trip via SQLite shim", () => {
	it("creates a session, retrieves it, and revokes it", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Sign in
		const session = await adapter.auth.signIn("admin@example.com", "password");
		expect(session).not.toBeNull();
		expect(session?.email).toBe("admin@example.com");
		expect(session?.isAdmin).toBe(true);

		// Retrieve session
		const retrieved = await adapter.auth.getSession(session?.id);
		expect(retrieved?.email).toBe("admin@example.com");

		// Revoke session
		await adapter.auth.signOut(session?.id);
		const revoked = await adapter.auth.getSession(session?.id);
		expect(revoked).toBeNull();
	});
});

describe("D1 adapter: content CRUD via SQLite shim", () => {
	it("creates a content record, reads it back, updates it, and deletes it", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Create
		const saved = await adapter.content.save({
			id: "d1-test-slug",
			slug: "d1-test-slug",
			kind: "post",
			title: "D1 Test Post",
			status: "draft",
			body: "<p>Initial body</p>",
			metadata: {
				seoTitle: "D1 Test Post",
				metaDescription: "Testing D1",
				legacyUrl: "/d1-test-slug",
				templateKey: "content",
				updatedAt: new Date().toISOString(),
				summary: "",
			},
		});
		expect(saved.slug).toBe("d1-test-slug");

		// Read back
		const fetched = await adapter.content.get("d1-test-slug");
		expect(fetched?.title).toBe("D1 Test Post");
		expect(fetched?.status).toBe("draft");

		// Update
		const updated = await adapter.content.save({
			...saved,
			title: "D1 Updated Post",
			status: "published",
		});
		expect(updated.title).toBe("D1 Updated Post");
		expect(updated.status).toBe("published");

		// Delete (soft delete — archives the record)
		await adapter.content.delete("d1-test-slug");
		const afterDelete = await adapter.content.get("d1-test-slug");
		// The Cloudflare adapter soft-deletes posts by setting status to "archived"
		expect(afterDelete?.status).toBe("archived");
	});
});

describe("D1 adapter: schema bootstrap via SQLite shim", () => {
	it("bootstraps the schema and confirms schema_migrations table exists", () => {
		const db = makeDb();

		const tableRow = db
			.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='schema_migrations'")
			.get() as { name: string } | undefined;

		expect(tableRow?.name).toBe("schema_migrations");
	});

	it("D1 shim executes SQL statements via prepare().all()", async () => {
		const db = await createSeededCloudflareDatabase();
		const d1 = new SqliteBackedD1Database(db);

		const result = await d1
			.prepare("SELECT COUNT(*) as count FROM admin_users")
			.first<{ count: number }>();
		expect(result).not.toBeNull();
		expect(result?.count).toBeGreaterThan(0);
	});
});

