/**
 * Content search tests — verifies FTS5 virtual table creation, trigger-based sync,
 * and search query behavior.
 *
 * All tests run in-process using DatabaseSync with the real schema.
 */

import { describe, expect, it, vi } from "vitest";

import { searchContentOverrides } from "../src/sqlite-runtime/search.js";
import { ensureFts5SearchIndex, getTableSql } from "../src/sqlite-schema-compat.js";
import { makeDb } from "./helpers/make-db.js";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

function setCmsConfig(search?: { enabled?: boolean }) {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = {
		siteName: "Test Site",
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [],
		search,
	};
}

function clearCmsConfig() {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = null;
}

describe("FTS5 search index creation", () => {
	it("ensureFts5SearchIndex creates content_fts virtual table", () => {
		const db = makeDb();
		expect(getTableSql(db, "content_fts")).toBeUndefined();

		ensureFts5SearchIndex(db);

		// FTS5 virtual tables appear in sqlite_master as type 'table'
		const row = db.prepare("SELECT name FROM sqlite_master WHERE name = 'content_fts'").get() as
			| { name: string }
			| undefined;
		expect(row?.name).toBe("content_fts");
		db.close();
	});

	it("ensureFts5SearchIndex is idempotent — calling twice does not throw", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);
		expect(() => ensureFts5SearchIndex(db)).not.toThrow();
		db.close();
	});
});

describe("FTS5 search query", () => {
	it("returns a record whose body matches a unique phrase", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by, body)
       VALUES ('fts-test-post', 'FTS Test Post', 'published', 'admin@example.com', 'uniqueftstestphrase searchable content')`,
		).run();

		const results = searchContentOverrides(db, "uniqueftstestphrase");
		expect(results.length).toBeGreaterThan(0);
		expect(results[0].slug).toBe("fts-test-post");
		db.close();
	});

	it("returns updated content after an UPDATE trigger fires", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by, body)
       VALUES ('fts-update-test', 'Update Test', 'draft', 'admin@example.com', 'originalbodycontent')`,
		).run();

		// Update the body — the AFTER UPDATE trigger should sync the FTS index
		db.prepare(
			`UPDATE content_overrides SET body = 'replacedftsbodyphrase' WHERE slug = 'fts-update-test'`,
		).run();

		const results = searchContentOverrides(db, "replacedftsbodyphrase");
		expect(results.length).toBeGreaterThan(0);
		expect(results[0].slug).toBe("fts-update-test");

		// Original phrase should no longer match
		const oldResults = searchContentOverrides(db, "originalbodycontent");
		expect(oldResults).toHaveLength(0);
		db.close();
	});
});

describe("searchRuntimeContentStates gating", () => {
	it("returns empty array with a warning when search.enabled is false", async () => {
		setCmsConfig({ enabled: false });
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

		// Import after setting config to ensure peekCmsConfig resolves correctly
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const results = await searchRuntimeContentStates("hello");

		expect(results).toEqual([]);
		expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining("search.enabled"));
		warnSpy.mockRestore();
		clearCmsConfig();
	});
});

tests/project-adapter.integration.test.t.source:
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";
import {
	createAstropressProjectAdapter,
	resolveAstropressProjectAdapterMode,
} from "../src/adapters/project.js";

describe("project adapter integration", () => {
	it("selects project adapters from runtime mode and project env", async () => {
		expect(resolveAstropressProjectAdapterMode({})).toBe("local");
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "hosted",
			}),
		).toBe("hosted");

		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-adapter-"));
		const localAdapter = createAstropressProjectAdapter({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_LOCAL_PROVIDER: "supabase",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "project-adapter.sqlite"),
			},
		});

		expect(localAdapter.capabilities.name).toBe("supabase");

		await rm(workspace, { recursive: true, force: true });
	});

	it("trims surrounding whitespace before matching the 'hosted' mode (kills .trim removal)", () => {
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "  hosted  ",
			}),
		).toBe("hosted");
	});

	it("returns 'local' when ASTROPRESS_RUNTIME_MODE is the literal 'local'", () => {
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "local",
			}),
		).toBe("local");
	});

	it("returns 'local' when ASTROPRESS_RUNTIME_MODE is undefined (no env)", () => {
		expect(resolveAstropressProjectAdapterMode({})).toBe("local");
	});

	it("returns 'local' for any value other than 'hosted' (e.g. typo)", () => {
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "hosting",
			}),
		).toBe("local");
	});

	it("explicit options.mode overrides any env-derived mode (kills ?? to && mutant)", async () => {
		// env says hosted, but options.mode="local" should win.
		const workspace = await mkdtemp(join(tmpdir(), "astropress-mode-override-"));
		const adapter = createAstropressProjectAdapter({
			mode: "local",
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_LOCAL_PROVIDER: "supabase",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "mode-override.sqlite"),
			},
		});
		expect(adapter.capabilities.name).toBe("supabase");
		await rm(workspace, { recursive: true, force: true });
	});

	it("creates a hosted adapter when mode='hosted' (kills BlockStatement/ConditionalExpression mutants on the if-branch)", () => {
		const adapter = createAstropressProjectAdapter({
			mode: "hosted",
			env: {
				ASTROPRESS_HOSTED_PROVIDER: "supabase",
				SUPABASE_URL: "https://x.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "test-service-key",
			},
		});
		// Hosted adapter advertises hostedAdmin capability.
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	it("explicit options.local.provider overrides projectEnv.localProvider (kills ?? to && in local branch)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-local-prov-"));
		// env says sqlite; options.local.provider="supabase" must win and
		// route through the supabase-sqlite adapter (capabilities.name="supabase").
		const adapter = createAstropressProjectAdapter({
			mode: "local",
			env: { ASTROPRESS_LOCAL_PROVIDER: "sqlite" },
			local: {
				provider: "supabase",
				workspaceRoot: workspace,
				dbPath: join(workspace, "local-prov.sqlite"),
			},
		});
		expect(adapter.capabilities.name).toBe("supabase");
		await rm(workspace, { recursive: true, force: true });
	});
});

tests/data-portability.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { beforeEach, describe, expect, it } from "vitest";

import { createSqlitePurgeOps } from "../src/sqlite-runtime/purge.js";
import { makeDb } from "./helpers/make-db.js";

function seedUser(db: DatabaseSync, email: string, name = "Test User") {
	db.prepare(
		`INSERT INTO admin_users (email, password_hash, name, is_admin)
     VALUES (?, 'hash', ?, 0)`,
	).run(email, name);
	const row = db.prepare("SELECT id FROM admin_users WHERE email = ? LIMIT 1").get(email) as {
		id: number;
	};

	// Insert a session for the user
	db.prepare(
		`INSERT INTO admin_sessions (id, user_id, csrf_token)
     VALUES (?, ?, 'csrf')`,
	).run(`sess-${email}`, row.id);

	// Insert audit events
	db.prepare(
		`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary)
     VALUES (?, 'content.update', 'content', 'post-1', 'Updated post')`,
	).run(email);

	// Insert a comment
	db.prepare(
		`INSERT INTO comments (id, author, email, body, route, status, policy)
     VALUES (?, 'Test User', ?, 'A comment', '/post-1', 'approved', 'open-moderated')`,
	).run(`comment-${email}`, email);

	// Insert a contact submission
	db.prepare(
		`INSERT INTO contact_submissions (name, email, message, submitted_at)
     VALUES ('Test User', ?, 'Hello', CURRENT_TIMESTAMP)`,
	).run(email);
}

describe("createSqlitePurgeOps — user data purge (GDPR)", () => {
	let db: DatabaseSync;
	let purge: ReturnType<typeof createSqlitePurgeOps>;

	beforeEach(() => {
		db = makeDb();
		purge = createSqlitePurgeOps(() => db);
	});

	it("revokes sessions for the user", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com");
		expect(result.ok).toBe(true);
		expect(result.revokedSessions).toBe(1);
	});

	it("anonymises audit events", () => {
		seedUser(db, "alice@test.com");
		purge.purgeUserData("alice@test.com");
		const row = db.prepare("SELECT user_email FROM audit_events LIMIT 1").get() as {
			user_email: string;
		};
		expect(row.user_email).toBe("[deleted]");
	});

	it("deletes comments by the user", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com");
		expect(result.deletedComments).toBe(1);
		const remaining = db
			.prepare("SELECT COUNT(*) as cnt FROM comments WHERE email = 'alice@test.com'")
			.get() as { cnt: number };
		expect(remaining.cnt).toBe(0);
	});

	it("deletes contact submissions by the user", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com");
		expect(result.deletedContactSubmissions).toBe(1);
	});

	it("suspends admin user by default", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com");
		expect(result.adminUserAction).toBe("suspended");
		const row = db
			.prepare("SELECT active FROM admin_users WHERE email = 'alice@test.com'")
			.get() as { active: number };
		expect(row.active).toBe(0);
	});

	it("deletes admin user when deleteAccount: true", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com", {
			deleteAccount: true,
		});
		expect(result.adminUserAction).toBe("deleted");
		const row = db
			.prepare("SELECT COUNT(*) as cnt FROM admin_users WHERE email = 'alice@test.com'")
			.get() as { cnt: number };
		expect(row.cnt).toBe(0);
	});

	it("returns not_found when user does not exist", () => {
		const result = purge.purgeUserData("nobody@test.com");
		expect(result.adminUserAction).toBe("not_found");
		expect(result.revokedSessions).toBe(0);
	});
});

tests/sections/schema.test.ts.source:
import { describe, expect, it } from "vitest";
import { parseSections, parseSectionsFromJson, SECTION_KINDS } from "../../src/sections/schema";

describe("parseSections", () => {
	it("returns empty array for null/undefined input", () => {
		expect(parseSections(null)).toEqual({ ok: true, sections: [] });
		expect(parseSections(undefined)).toEqual({ ok: true, sections: [] });
	});

	it("returns empty array for an empty object", () => {
		expect(parseSections({})).toEqual({ ok: true, sections: [] });
	});

	it("accepts a top-level array", () => {
		const r = parseSections([{ id: "h", kind: "hero", headline: "Hello", alignment: "center" }]);
		expect(r.ok).toBe(true);
		if (r.ok) expect(r.sections).toHaveLength(1);
	});

	it("accepts the {sections: [...]} envelope shape", () => {
		const r = parseSections({
			sections: [{ id: "h", kind: "hero", headline: "Hello", alignment: "center" }],
		});
		expect(r.ok).toBe(true);
		if (r.ok) expect(r.sections).toHaveLength(1);
	});

	it("rejects an unknown kind with a path-keyed error", () => {
		const r = parseSections([{ id: "x", kind: "weird-kind" }]);
		expect(r.ok).toBe(false);
		if (!r.ok)
			expect(r.errors[0]).toMatchObject({
				path: "$[0].kind",
				message: expect.stringContaining("unknown section kind"),
			});
	});

	it("requires hero.headline", () => {
		const r = parseSections([{ id: "h", kind: "hero", alignment: "start" }]);
		expect(r.ok).toBe(false);
		if (!r.ok)
			expect(r.errors).toContainEqual({
				path: "$[0].headline",
				message: "headline is required",
			});
	});

	it("validates feature-grid item shape", () => {
		const r = parseSections([
			{
				id: "fg",
				kind: "feature-grid",
				heading: "X",
				columns: 3,
				items: [{ title: "ok", body: "" }],
			},
		]);
		expect(r.ok).toBe(false);
		if (!r.ok) expect(r.errors[0].path).toBe("$[0].items[0].body");
	});

	it("normalises invalid columns to 3", () => {
		const r = parseSections([
			{
				id: "fg",
				kind: "feature-grid",
				heading: "X",
				columns: 99,
				items: [],
			},
		]);
		expect(r.ok).toBe(true);
		if (r.ok) {
			const fg = r.sections[0];
			if (fg.kind === "feature-grid") expect(fg.columns).toBe(3);
		}
	});

	it("requires testimonials.ids when source=ids", () => {
		const r = parseSections([{ id: "t", kind: "testimonials", source: "ids", layout: "grid" }]);
		expect(r.ok).toBe(false);
	});

	it("accepts a fully populated landing-page payload", () => {
		const r = parseSections([
			{
				id: "1",
				kind: "hero",
				headline: "H",
				alignment: "center",
				primaryCta: { label: "Go", href: "#" },
			},
			{
				id: "2",
				kind: "feature-grid",
				heading: "Why",
				columns: 3,
				items: [{ title: "T", body: "B" }],
			},
			{
				id: "3",
				kind: "cta-banner",
				headline: "Now",
				primaryCta: { label: "Yes", href: "#" },
				tone: "accent",
			},
			{ id: "4", kind: "rich-text", html: "<p>x</p>" },
		]);
		expect(r.ok).toBe(true);
		if (r.ok) expect(r.sections).toHaveLength(4);
	});

	it("covers all eight section kinds in the catalog", () => {
		expect(SECTION_KINDS).toHaveLength(8);
	});

	it("parseSectionsFromJson handles invalid JSON", () => {
		const r = parseSectionsFromJson("{not json");
		expect(r.ok).toBe(false);
		if (!r.ok) expect(r.errors[0].message).toContain("invalid JSON");
	});

	it("parseSectionsFromJson treats empty string as no sections", () => {
		const r = parseSectionsFromJson("");
		expect(r.ok).toBe(true);
		if (r.ok) expect(r.sections).toEqual([]);
	});
});

tests/media.test.ts.source:
import {
	getRuntimeMediaResolutionOptions,
	resolveMediaUrl,
	resolveRuntimeMediaUrl,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

const sampleRecord = {
	id: "img-001",
	sourceUrl: "https://legacy.example.org/wp-content/uploads/hero.jpg",
	localPath: "/images/home/community-garden-hero.jpg",
	r2Key: "images/home/community-garden-hero.jpg",
};

describe("resolveMediaUrl()", () => {
	it("returns localPath in development mode", () => {
		const url = resolveMediaUrl(sampleRecord, { mode: "development" });
		expect(url).toBe(sampleRecord.localPath);
	});

	it("development mode short-circuits even when r2BaseUrl is set (kills dev-branch mutants)", () => {
		// Critical: dev mode must NOT build an R2 URL even if one is configured.
		// Original returns localPath; if the dev short-circuit were removed we'd
		// fall through to the deployment branch and synthesize an R2 URL.
		const url = resolveMediaUrl(sampleRecord, {
			mode: "development",
			r2BaseUrl: "https://cdn.example.org",
		});
		expect(url).toBe(sampleRecord.localPath);
		expect(url).not.toContain("cdn.example.org");
	});

	it("returns localPath in deployment mode when no r2BaseUrl is provided", () => {
		const url = resolveMediaUrl(sampleRecord, { mode: "deployment" });
		expect(url).toBe(sampleRecord.localPath);
	});

	it("returns r2 URL in deployment mode when r2BaseUrl is provided", () => {
		const url = resolveMediaUrl(sampleRecord, {
			mode: "deployment",
			r2BaseUrl: "https://cdn.example.org",
		});
		expect(url).toBe("https://cdn.example.org/images/home/community-garden-hero.jpg");
	});

	it("strips trailing slash from r2BaseUrl before joining", () => {
		const url = resolveMediaUrl(sampleRecord, {
			mode: "deployment",
			r2BaseUrl: "https://cdn.example.org/",
		});
		expect(url).not.toContain("//images");
		expect(url).toBe("https://cdn.example.org/images/home/community-garden-hero.jpg");
	});

	it("keeps localPath when no r2 key exists", () => {
		const url = resolveMediaUrl(
			{ ...sampleRecord, r2Key: null },
			{ mode: "deployment", r2BaseUrl: "https://cdn.example.org" },
		);
		expect(url).toBe(sampleRecord.localPath);
	});

	it("builds runtime media options from env defaults", () => {
		expect(getRuntimeMediaResolutionOptions()).toEqual({
			mode: "development",
			r2BaseUrl: undefined,
		});
	});

	it("switches runtime media options to deployment when an R2 base URL is configured", () => {
		expect(
			getRuntimeMediaResolutionOptions({
				runtime: { env: { PUBLIC_R2_BASE_URL: "https://cdn.example.org" } },
			} as App.Locals),
		).toEqual({
			mode: "deployment",
			r2BaseUrl: "https://cdn.example.org",
		});
	});

	it("resolves runtime media URLs with local defaults", () => {
		expect(resolveRuntimeMediaUrl(sampleRecord)).toBe(sampleRecord.localPath);
	});

	it("resolves runtime media URLs to R2 when configured through runtime bindings", () => {
		expect(
			resolveRuntimeMediaUrl(sampleRecord, {
				runtime: { env: { PUBLIC_R2_BASE_URL: "https://cdn.example.org" } },
			} as App.Locals),
		).toBe("https://cdn.example.org/images/home/community-garden-hero.jpg");
	});
});

tests/adapters/supabase-sqlite.test.ts.source:
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import { createAstropressSupabaseSqliteAdapter } from "../../src/adapters/supabase-sqlite";

const workspaces: string[] = [];
afterEach(() => {
	workspaces.length = 0;
});

async function freshWorkspace(): Promise<string> {
	const w = await mkdtemp(join(tmpdir(), "astropress-supabase-sqlite-"));
	workspaces.push(w);
	return w;
}

describe("createAstropressSupabaseSqliteAdapter", () => {
	it("returns an adapter with the supabase capability profile", async () => {
		const workspace = await freshWorkspace();
		const adapter = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "supabase-admin.sqlite"),
		});
		expect(adapter).toBeDefined();
		// supabase wraps sqlite: the resulting adapter must expose the
		// supabase identity, not the bare sqlite identity.
		expect(adapter.capabilities.name).toBe("supabase");
	});

	it("accepts an empty options object via the default argument", async () => {
		// Pins the default-arg mutation: `options = {}` → `options = "Stryker was here"`.
		const adapter = createAstropressSupabaseSqliteAdapter();
		expect(adapter).toBeDefined();
		expect(adapter.capabilities.name).toBe("supabase");
	});

	it("propagates the workspaceRoot through to the wrapped sqlite adapter", async () => {
		const workspace = await freshWorkspace();
		const adapter = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
		});
		// The supabase wrapper exposes the inner sqlite adapter via the
		// capability profile; both should agree the adapter is set up.
		expect(adapter.capabilities.database).toBe(true);
	});

	it("end-to-end: sign-in works (proves backingAdapter actually wires sqlite)", async () => {
		// Pins the ObjectLiteral mutation that drops the backingAdapter:
		// without sqlite underneath, signIn would not resolve a user record.
		const workspace = await freshWorkspace();
		const adapter = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "supabase-admin.sqlite"),
		});
		const user = await adapter.auth.signIn("admin@example.com", "password");
		// The sqlite-backed signIn returns an admin user envelope shaped
		// { id, email, isAdmin }. The hosted-API path either throws at
		// config-read time (no SUPABASE_URL) or resolves over fetch — either
		// way it cannot produce this exact local-sqlite shape with the seed
		// admin's email and admin role flag.
		expect(user).toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});
		expect(typeof user?.id).toBe("string");
		// Distinguishes the sqlite-backed signIn from the in-memory fallback:
		// sqlite returns a generated session id, while the default in-memory
		// auth store always returns the seed user's literal id "admin-1".
		// This kills the ObjectLiteral mutation that drops backingAdapter.
		expect(user?.id).not.toBe("admin-1");
	});
});

