import { describe, expect, it } from "vitest";
import { sanitizeSections } from "../../src/sections/sanitize";
import type { Section } from "../../src/sections/schema";

describe("sanitizeSections — coverage", () => {
	it("returns an empty array when input is empty", async () => {
		const out = await sanitizeSections([]);
		expect(out).toEqual([]);
	});

	it("preserves section order", async () => {
		const input: Section[] = [
			{ id: "h", kind: "hero", headline: "h", alignment: "start" },
			{ id: "r", kind: "rich-text", html: "<p>a</p>" },
			{ id: "f", kind: "faq", items: [] },
			{
				id: "i",
				kind: "image-text",
				heading: "H",
				body: "<p>b</p>",
				mediaId: "",
				imageSide: "start",
			},
		];
		const out = await sanitizeSections(input);
		expect(out.map((s) => s.id)).toEqual(["h", "r", "f", "i"]);
	});

	it("keeps non-html-bearing kinds object-equal in shape", async () => {
		const input: Section[] = [{ id: "g", kind: "gallery", mediaIds: ["a"], columns: 3 }];
		const out = await sanitizeSections(input);
		expect(out[0]).toEqual(input[0]);
	});

	it("rich-text retains kind discriminator after sanitization", async () => {
		const out = await sanitizeSections([{ id: "r", kind: "rich-text", html: "<p>x</p>" }]);
		expect(out[0].kind).toBe("rich-text");
	});

	it("image-text retains heading + mediaId + imageSide unchanged", async () => {
		const out = await sanitizeSections([
			{
				id: "i",
				kind: "image-text",
				heading: "H",
				body: "<p>x</p><script>q()</script>",
				mediaId: "m",
				imageSide: "end",
			},
		]);
		const it0 = out[0];
		if (it0.kind !== "image-text") throw new Error();
		expect(it0.heading).toBe("H");
		expect(it0.mediaId).toBe("m");
		expect(it0.imageSide).toBe("end");
		expect(it0.body).not.toContain("<script");
	});

	it("strips dangerous attributes from rich-text", async () => {
		const out = await sanitizeSections([
			{
				id: "r",
				kind: "rich-text",
				html: '<a href="javascript:alert(1)">x</a>',
			},
		]);
		if (out[0].kind === "rich-text") {
			expect(out[0].html).not.toContain("javascript:");
		}
	});
});

tests/integrations/webhooks/registry.tes.source:
import { afterEach, describe, expect, it } from "vitest";

import {
	_resetInboundWebhookRegistryForTests,
	getInboundWebhookProvider,
	InboundWebhookRegistryError,
	listInboundWebhookProviders,
	registerInboundWebhookProvider,
} from "../../../src/integrations/webhooks/registry";

const GITHUB = {
	id: "github",
	label: "GitHub",
	signatureHeader: "X-Hub-Signature-256",
	algorithm: "hmac-sha256" as const,
	eventHeader: "X-GitHub-Event",
};

afterEach(() => _resetInboundWebhookRegistryForTests());

describe("registerInboundWebhookProvider", () => {
	it("registers a provider and returns the same definition", () => {
		expect(registerInboundWebhookProvider({ ...GITHUB })).toEqual(GITHUB);
	});

	it("getInboundWebhookProvider returns the registered provider", () => {
		registerInboundWebhookProvider({ ...GITHUB });
		expect(getInboundWebhookProvider("github")).toEqual(GITHUB);
	});

	it("getInboundWebhookProvider returns undefined for an unregistered id", () => {
		expect(getInboundWebhookProvider("github")).toBeUndefined();
	});

	it("rejects duplicate ids with DUPLICATE_PROVIDER", () => {
		registerInboundWebhookProvider({ ...GITHUB });
		let caught: unknown;
		try {
			registerInboundWebhookProvider({ ...GITHUB });
		} catch (e) {
			caught = e;
		}
		expect(caught).toBeInstanceOf(InboundWebhookRegistryError);
		const err = caught as InboundWebhookRegistryError;
		expect(err.name).toBe("InboundWebhookRegistryError");
		expect(err.code).toBe("DUPLICATE_PROVIDER");
		expect(err.message).toContain("github");
		expect(err.message).toContain("already registered");
	});

	it("listInboundWebhookProviders returns all registered providers", () => {
		registerInboundWebhookProvider({ ...GITHUB });
		registerInboundWebhookProvider({ ...GITHUB, id: "stripe" });
		const ids = listInboundWebhookProviders()
			.map((p) => p.id)
			.sort();
		expect(ids).toEqual(["github", "stripe"]);
	});

	it("listInboundWebhookProviders returns an empty array when none registered", () => {
		expect(listInboundWebhookProviders()).toEqual([]);
	});
});

tests/sections/templates.test.ts.source:
import { describe, expect, it } from "vitest";
import { parseSections } from "../../src/sections/schema";
import {
	buildTemplate,
	isTemplateKey,
	TEMPLATE_CATALOG,
	TEMPLATE_KEYS,
} from "../../src/sections/templates";

describe("page templates", () => {
	it("blank produces no sections", () => {
		expect(buildTemplate("blank")).toEqual([]);
	});

	it("landing produces hero, feature-grid, testimonials, cta-banner", () => {
		const sections = buildTemplate("landing");
		expect(sections.map((s) => s.kind)).toEqual([
			"hero",
			"feature-grid",
			"testimonials",
			"cta-banner",
		]);
	});

	it("about includes hero, image-text, feature-grid, cta-banner", () => {
		expect(buildTemplate("about").map((s) => s.kind)).toEqual([
			"hero",
			"image-text",
			"feature-grid",
			"cta-banner",
		]);
	});

	it("contact includes hero, image-text, faq, cta-banner", () => {
		expect(buildTemplate("contact").map((s) => s.kind)).toEqual([
			"hero",
			"image-text",
			"faq",
			"cta-banner",
		]);
	});

	it("each template's output round-trips through parseSections", () => {
		for (const key of TEMPLATE_KEYS) {
			const sections = buildTemplate(key);
			const parsed = parseSections(sections);
			expect(parsed.ok, `${key} must validate`).toBe(true);
		}
	});

	it("uses unique ids within a single template invocation", () => {
		const sections = buildTemplate("landing");
		const ids = sections.map((s) => s.id);
		expect(new Set(ids).size).toBe(ids.length);
	});

	it("isTemplateKey rejects unknown keys", () => {
		expect(isTemplateKey("landing")).toBe(true);
		expect(isTemplateKey("nope")).toBe(false);
	});

	it("TEMPLATE_CATALOG covers all template keys", () => {
		const catalogKeys = TEMPLATE_CATALOG.map((e) => e.key).sort();
		expect(catalogKeys).toEqual([...TEMPLATE_KEYS].sort());
	});

	it("each catalog entry's sectionKinds matches the built sections", () => {
		for (const entry of TEMPLATE_CATALOG) {
			const built = buildTemplate(entry.key).map((s) => s.kind);
			expect(built).toEqual(entry.sectionKinds);
		}
	});
});

