} from "../../src/integrations/badge-tone";

const LABELS: IntegrationStatusBadgeLabels = {
	connected: "Connected",
	error: "Needs attention",
	paused: "Paused",
	notConnected: "Not connected",
};

describe("integrationStatusBadgeTone", () => {
