import { afterEach, describe, expect, it } from "vitest";

import {
	ASTROPRESS_ADMIN_APP_NAME,
	ASTROPRESS_ADMIN_PRODUCT_NAME,
	buildAstropressAdminDocumentTitle,
} from "../src/admin-branding";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

afterEach(() => {
	(globalThis as typeof globalThis & { [CMS_CONFIG_KEY]?: unknown })[CMS_CONFIG_KEY] = null;
});

describe("admin-branding constants", () => {
	it("exports the expected default product name", () => {
		expect(ASTROPRESS_ADMIN_PRODUCT_NAME).toBe("Astropress Admin");
	});

	it("exports the expected default app name", () => {
		expect(ASTROPRESS_ADMIN_APP_NAME).toBe("Astropress");
	});
});

describe("buildAstropressAdminDocumentTitle", () => {
	it("appends the product name with ' | ' separator when title is non-empty", () => {
		expect(buildAstropressAdminDocumentTitle("Dashboard")).toBe("Dashboard | Astropress Admin");
	});

	it("returns just the product name when title is empty string", () => {
		expect(buildAstropressAdminDocumentTitle("")).toBe("Astropress Admin");
	});

	it("returns just the product name when title is whitespace only", () => {
		expect(buildAstropressAdminDocumentTitle("   ")).toBe("Astropress Admin");
		expect(buildAstropressAdminDocumentTitle("\t\n  ")).toBe("Astropress Admin");
	});

	it("trims surrounding whitespace from non-empty titles before joining", () => {
		expect(buildAstropressAdminDocumentTitle("  Pages  ")).toBe("Pages | Astropress Admin");
	});
});

tests/delete-undo.test.ts.source:
import { describe, expect, it } from "vitest";
import { isRestorableTable } from "../src/runtime-actions-restore";

// BDD: Undo toast after deleting admin resources
//
// Unit tests verify the restore action's table allowlist and redirect URL pattern.
// Full delete → undo flow is covered by admin-harness e2e tests.

describe("delete_undo", () => {
	it("Deleting a resource shows an undo toast — redirect URL includes restore params", () => {
		// Simulate what author-delete.ts produces after a successful delete.
		const id = 42;
		const redirectUrl = `/ap-admin/authors?deleted=1&restore_table=authors&restore_id=${id}`;
		const params = new URLSearchParams(redirectUrl.split("?")[1]);
		expect(params.get("deleted")).toBe("1");
		expect(params.get("restore_table")).toBe("authors");
		expect(params.get("restore_id")).toBe("42");
	});

	it("Clicking Undo restores the deleted resource — isRestorableTable validates the allowlist", () => {
		expect(isRestorableTable("authors")).toBe(true);
		expect(isRestorableTable("categories")).toBe(true);
		expect(isRestorableTable("tags")).toBe(true);
		expect(isRestorableTable("media_assets")).toBe(true);
		// Arbitrary table names must be rejected.
		expect(isRestorableTable("users")).toBe(false);
		expect(isRestorableTable("content_records")).toBe(false);
		expect(isRestorableTable("admin_users")).toBe(false);
	});
});

